CREATE OR REPLACE FUNCTION public.allocate_next_session_number(p_project_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  next_number INT;
BEGIN
  IF p_project_id IS NULL THEN
    RAISE EXCEPTION 'project_id required';
  END IF;

  -- Serialize creators per saga without blocking readers.
  PERFORM pg_advisory_xact_lock(hashtext(p_project_id::text));

  SELECT COALESCE(MAX(session_number), 0) + 1
    INTO next_number
    FROM public.sessions
   WHERE project_id = p_project_id;

  RETURN next_number;
END;
$function$

CREATE OR REPLACE FUNCTION public.apply_session_runtime_command(p_session_id uuid, p_expected_revision bigint, p_kind text, p_payload jsonb DEFAULT '{}'::jsonb, p_idempotency_key text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  actor UUID := auth.uid();
  v_session public.sessions;
  v_new_revision BIGINT;
  v_world JSONB;
  v_existing public.session_events;
  v_key TEXT := NULLIF(BTRIM(COALESCE(p_idempotency_key, '')), '');
  v_is_gm BOOLEAN;
  v_is_director BOOLEAN;
  v_roll JSONB;
  v_combat JSONB;
  v_presentation JSONB;
  v_program JSONB;
  v_knowledge JSONB;
  v_life JSONB;
  v_adventure JSONB;
  v_cue JSONB;
  v_scene_id TEXT;
  v_event_payload JSONB := COALESCE(p_payload, '{}'::jsonb);
BEGIN
  IF actor IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE = '42501';
  END IF;
  IF p_session_id IS NULL THEN
    RAISE EXCEPTION 'session_id required' USING ERRCODE = '22023';
  END IF;
  IF p_kind NOT IN (
    'join', 'leave', 'presence', 'status', 'roll', 'damage',
    'condition', 'scene', 'combat', 'gameplay', 'program', 'reveal',
    'life', 'adventure', 'cue'
  ) THEN
    RAISE EXCEPTION 'Invalid event kind' USING ERRCODE = '22023';
  END IF;
  IF NOT public.is_session_participant(p_session_id, actor) THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  IF v_key IS NOT NULL THEN
    SELECT * INTO v_existing
    FROM public.session_events
    WHERE session_id = p_session_id AND idempotency_key = v_key
    LIMIT 1;
    IF FOUND THEN
      RETURN public.get_session_runtime_snapshot(p_session_id)
        || jsonb_build_object('idempotentReplay', true, 'eventId', v_existing.id);
    END IF;
  END IF;

  SELECT * INTO v_session FROM public.sessions WHERE id = p_session_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Session not found' USING ERRCODE = 'P0002';
  END IF;
  IF v_session.status = 'completed' AND p_kind NOT IN ('leave', 'presence') THEN
    RAISE EXCEPTION 'Completed sessions cannot accept gameplay commands' USING ERRCODE = '22023';
  END IF;
  IF v_session.runtime_revision IS DISTINCT FROM p_expected_revision THEN
    RAISE EXCEPTION 'stale revision: expected %, actual %',
      p_expected_revision, v_session.runtime_revision
      USING ERRCODE = '40001';
  END IF;

  v_new_revision := v_session.runtime_revision + 1;
  v_world := COALESCE(v_session.world_state, '{}'::jsonb);
  v_is_gm := public.is_project_gm(v_session.project_id, actor);
  v_is_director := public.sagatree_session_has_director(p_session_id, actor);

  IF p_kind = 'roll' THEN
    v_roll := public.sagatree_resolve_session_check(p_session_id, actor, p_payload, v_is_gm);
    v_event_payload := v_roll->'eventPayload';
    v_world := v_roll->'worldState';
  ELSIF p_kind = 'combat' THEN
    v_combat := public.sagatree_resolve_combat_command(
      p_session_id, actor, p_payload, v_is_gm, v_world
    );
    v_event_payload := v_combat->'eventPayload';
    v_world := v_combat->'worldState';
  ELSIF p_kind = 'damage' THEN
    v_combat := public.sagatree_resolve_damage_command(p_payload, v_is_gm, v_world);
    v_event_payload := v_combat->'eventPayload';
    v_world := v_combat->'worldState';
  ELSIF p_kind = 'condition' THEN
    v_combat := public.sagatree_resolve_condition_command(p_payload, v_is_gm, v_world);
    v_event_payload := v_combat->'eventPayload';
    v_world := v_combat->'worldState';
  ELSIF p_kind = 'life' THEN
    v_life := public.sagatree_resolve_life_command(p_payload, v_is_gm, v_world);
    v_event_payload := v_life->'eventPayload';
    v_world := v_life->'worldState';
  ELSIF p_kind = 'adventure' THEN
    v_adventure := public.sagatree_resolve_adventure_command(
      p_session_id, p_payload, v_is_gm, v_world
    );
    v_event_payload := v_adventure->'eventPayload';
    v_world := v_adventure->'worldState';
  ELSIF p_kind = 'cue' THEN
    v_cue := public.sagatree_resolve_cue_command(p_payload, v_is_gm, v_is_director, v_world);
    v_event_payload := v_cue->'eventPayload';
    v_world := v_cue->'worldState';
  ELSIF p_kind = 'scene' THEN
    IF NOT v_is_gm THEN
      RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
    END IF;
    IF p_payload ? 'title' OR p_payload ? 'visibleActors' OR p_payload ? 'backdropUrl'
       OR p_payload ? 'description' OR p_payload ? 'locationLabel' OR p_payload ? 'sceneRef' THEN
      v_presentation := public.sagatree_build_scene_presentation(p_payload);
      v_scene_id := NULLIF(v_presentation->>'_sceneId', '');
      v_presentation := v_presentation - '_sceneId';
      v_world := jsonb_set(v_world, '{shared}', COALESCE(v_world->'shared', '{}'::jsonb), true);
      v_world := jsonb_set(v_world, '{shared,scenePresentation}', v_presentation, true);
      IF v_scene_id IS NOT NULL THEN
        v_world := jsonb_set(v_world, '{sceneId}', to_jsonb(v_scene_id), true);
      END IF;
      v_event_payload := v_presentation;
    ELSE
      IF p_payload ? 'sceneId' THEN
        v_world := jsonb_set(v_world, '{sceneId}', to_jsonb(p_payload->>'sceneId'), true);
      END IF;
    END IF;
  ELSIF p_kind = 'program' THEN
    IF NOT v_is_gm AND NOT v_is_director THEN
      RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
    END IF;
    v_program := public.sagatree_build_program_presentation(
      p_payload,
      COALESCE(v_world->'shared'->'programPresentation', NULL)
    );
    v_world := jsonb_set(v_world, '{shared}', COALESCE(v_world->'shared', '{}'::jsonb), true);
    v_world := jsonb_set(v_world, '{shared,programPresentation}', v_program, true);
    v_event_payload := v_program;
  ELSIF p_kind = 'reveal' THEN
    IF NOT v_is_gm THEN
      RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
    END IF;
    v_knowledge := public.sagatree_apply_knowledge_reveal(v_world, p_payload, actor);
    v_world := v_knowledge->'worldState';
    v_event_payload := v_knowledge->'eventPayload';
  ELSIF p_kind = 'gameplay' THEN
    IF NOT v_is_gm THEN
      RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
    END IF;
    IF p_payload ? 'sceneId' THEN
      v_world := jsonb_set(v_world, '{sceneId}', to_jsonb(p_payload->>'sceneId'), true);
    END IF;
    IF p_payload ? 'checkTarget' AND (p_payload->>'checkTarget') ~ '^-?[0-9]+$' THEN
      v_world := jsonb_set(v_world, '{shared}', COALESCE(v_world->'shared', '{}'::jsonb), true);
      v_world := jsonb_set(
        v_world,
        '{shared,checkTarget}',
        to_jsonb((p_payload->>'checkTarget')::int),
        true
      );
    END IF;
  END IF;

  IF p_kind = 'presence' THEN
    UPDATE public.session_players
       SET is_online = COALESCE((p_payload->>'isOnline')::boolean, true)
     WHERE session_id = p_session_id AND user_id = actor;
  END IF;

  IF p_kind = 'status' THEN
    IF NOT v_is_gm THEN
      RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
    END IF;
  END IF;

  UPDATE public.sessions
     SET runtime_revision = v_new_revision,
         world_state = v_world,
         updated_at = NOW()
   WHERE id = p_session_id;

  PERFORM public.append_session_event(
    p_session_id, p_kind, actor, COALESCE(v_event_payload, '{}'::jsonb), v_new_revision, v_key
  );

  RETURN public.get_session_runtime_snapshot(p_session_id)
    || jsonb_build_object('idempotentReplay', false);
END;
$function$

CREATE OR REPLACE FUNCTION public.archive_world_node_subtree(p_world_profile_id uuid, p_place_id uuid, p_confirm boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_preview JSONB;
  v_ids UUID[];
  v_n INT;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'not authenticated' USING ERRCODE = '42501';
  END IF;
  IF NOT public.current_user_can_edit_world_profile(p_world_profile_id) THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  v_preview := public.preview_world_node_consequences(p_world_profile_id, p_place_id);
  IF (v_preview->>'requiresConfirm')::BOOLEAN IS TRUE AND p_confirm IS NOT TRUE THEN
    RAISE EXCEPTION 'confirmation required' USING ERRCODE = '22023';
  END IF;

  v_ids := public.atlas_wb_descendant_ids(p_world_profile_id, p_place_id);
  v_ids := array_append(v_ids, p_place_id);

  UPDATE public.world_places
  SET status = 'archived', revision = revision + 1, updated_at = NOW()
  WHERE world_profile_id = p_world_profile_id AND id = ANY (v_ids);

  GET DIAGNOSTICS v_n = ROW_COUNT;

  RETURN jsonb_build_object(
    'archivedCount', v_n,
    'placeIds', to_jsonb(v_ids),
    'consequences', v_preview
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.assert_npc_creature_instance_gm(p_project_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_actor UUID := auth.uid();
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'not authenticated';
  END IF;

  IF p_project_id IS NULL THEN
    RAISE EXCEPTION 'missing project';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.projects p
    WHERE p.id = p_project_id
      AND p.gm_user_id = v_actor
  ) THEN
    RAISE EXCEPTION 'only gm may manage instances';
  END IF;

  IF NOT public.current_user_is_active_project_member(p_project_id) THEN
    RAISE EXCEPTION 'actor is not an active project member';
  END IF;

  RETURN v_actor;
END;
$function$

CREATE OR REPLACE FUNCTION public.assign_npc_creature_controller(p_project_id uuid, p_definition_id text, p_controller_user_id uuid DEFAULT NULL::uuid)
 RETURNS npc_creature_controller_assignments
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_actor UUID := auth.uid();
  v_definition_id TEXT := btrim(COALESCE(p_definition_id, ''));
  v_row public.npc_creature_controller_assignments;
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'not authenticated';
  END IF;

  IF p_project_id IS NULL THEN
    RAISE EXCEPTION 'missing project';
  END IF;

  IF char_length(v_definition_id) < 10 OR char_length(v_definition_id) > 160 THEN
    RAISE EXCEPTION 'invalid definition id';
  END IF;

  -- Actor must be the project GM and an active member.
  IF NOT EXISTS (
    SELECT 1
    FROM public.projects p
    WHERE p.id = p_project_id
      AND p.gm_user_id = v_actor
  ) THEN
    RAISE EXCEPTION 'only gm may assign controller';
  END IF;

  IF NOT public.current_user_is_active_project_member(p_project_id) THEN
    RAISE EXCEPTION 'actor is not an active project member';
  END IF;

  -- Controller must be null (unassigned / GM) or an active member.
  IF p_controller_user_id IS NOT NULL THEN
    IF NOT EXISTS (
      SELECT 1
      FROM public.project_members pm
      WHERE pm.project_id = p_project_id
        AND pm.user_id = p_controller_user_id
        AND pm.status = 'active'
    ) THEN
      RAISE EXCEPTION 'controller is not an active project member';
    END IF;
  END IF;

  -- Prefer Full sheet when a persisted definition exists; fail closed if present but not full.
  IF EXISTS (
    SELECT 1
    FROM public.npc_creature_definitions d
    WHERE d.id = v_definition_id
  ) AND NOT EXISTS (
    SELECT 1
    FROM public.npc_creature_definitions d
    WHERE d.id = v_definition_id
      AND d.status = 'active'
      AND COALESCE(d.payload->>'sheetMode', '') = 'full'
  ) THEN
    RAISE EXCEPTION 'definition is not a full character sheet';
  END IF;

  INSERT INTO public.npc_creature_controller_assignments (
    project_id,
    definition_id,
    controller_user_id,
    assigned_by,
    updated_at
  )
  VALUES (
    p_project_id,
    v_definition_id,
    p_controller_user_id,
    v_actor,
    NOW()
  )
  ON CONFLICT (project_id, definition_id) DO UPDATE
  SET
    controller_user_id = EXCLUDED.controller_user_id,
    assigned_by = EXCLUDED.assigned_by,
    updated_at = NOW()
  RETURNING * INTO v_row;

  RETURN v_row;
END;
$function$

CREATE OR REPLACE FUNCTION public.atlas_wb_create_primary_map(p_world uuid, p_place uuid, p_kind text, p_title text, p_parent_map uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_map UUID;
  v_map_kind TEXT := public.atlas_wb_map_kind_for_node(p_kind);
BEGIN
  -- Own local frame — do NOT copy parent bounds
  INSERT INTO public.world_atlas_maps (
    world_profile_id, parent_map_id, kind, title, sort_order, bounds, generator_meta
  ) VALUES (
    p_world,
    p_parent_map,
    v_map_kind,
    p_title,
    0,
    '{"minX":0,"minY":0,"maxX":1000,"maxY":1000}'::jsonb,
    jsonb_build_object(
      'engine', 'unified_canvas',
      'mapStatus', 'unlocated',
      'placeId', p_place
    )
  )
  RETURNING id INTO v_map;

  INSERT INTO public.world_place_map_links (
    world_profile_id, place_id, map_id, usage, anchor
  ) VALUES (
    p_world, p_place, v_map, 'primary', '{}'::jsonb
  );

  RETURN v_map;
END;
$function$

CREATE OR REPLACE FUNCTION public.atlas_wb_migration_apply(p_world_profile_id uuid, p_target text, p_confirm text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user UUID := auth.uid();
  v_owner UUID;
  v_gate BOOLEAN := false;
  v_batch UUID := gen_random_uuid();
  v_created_places UUID[] := '{}';
  v_created_maps UUID[] := '{}';
  v_created_links UUID[] := '{}';
  v_rewrites JSONB := '[]'::jsonb;
  v_orphan RECORD;
  v_continent UUID;
  v_country UUID;
  v_cont_seed TEXT;
  v_country_seed TEXT;
  v_cont_name TEXT;
  v_country_name TEXT;
  v_root_map UUID;
  v_cont_map UUID;
  v_country_map UUID;
  v_old_parent UUID;
  v_link UUID;
  v_place_row RECORD;
  v_before_places INT;
  v_after_places INT;
BEGIN
  IF p_target IS DISTINCT FROM 'staging' AND p_target IS DISTINCT FROM 'production' THEN
    RAISE EXCEPTION 'target must be staging|production' USING ERRCODE = '22023';
  END IF;
  IF p_target = 'staging' AND p_confirm IS DISTINCT FROM 'STAGING_APPLY' THEN
    RAISE EXCEPTION 'staging confirm token required' USING ERRCODE = '42501';
  END IF;
  IF p_target = 'production' AND p_confirm IS DISTINCT FROM 'PRODUCTION_APPLY_APPROVED' THEN
    RAISE EXCEPTION 'production confirm token required' USING ERRCODE = '42501';
  END IF;

  SELECT owner_user_id INTO v_owner
  FROM public.world_profiles
  WHERE id = p_world_profile_id;
  IF v_owner IS NULL THEN
    RAISE EXCEPTION 'world not found' USING ERRCODE = 'P0002';
  END IF;

  IF v_user IS NOT NULL AND v_user <> v_owner THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  IF v_user IS NULL
     AND current_setting('atlas.migration_operator', true) IS DISTINCT FROM '1' THEN
    RAISE EXCEPTION 'not authenticated' USING ERRCODE = '42501';
  END IF;

  SELECT COALESCE(g.enabled, false) INTO v_gate
  FROM public.atlas_wb_migration_gates g
  WHERE g.world_profile_id = p_world_profile_id;
  IF NOT COALESCE(v_gate, false) THEN
    RAISE EXCEPTION 'migration gate disabled for world' USING ERRCODE = '42501';
  END IF;

  SELECT count(*)::int INTO v_before_places
  FROM public.world_places
  WHERE world_profile_id = p_world_profile_id;

  v_root_map := public.atlas_wb_ensure_world_root_map(p_world_profile_id);

  -- Orphan settlements / places (null parent) → continent → country placeholders.
  FOR v_orphan IN
    SELECT p.id, p.kind, p.name, p.parent_place_id
    FROM public.world_places p
    WHERE p.world_profile_id = p_world_profile_id
      AND p.parent_place_id IS NULL
      AND p.status IS DISTINCT FROM 'archived'
      AND p.kind IN ('settlement', 'place')
      AND COALESCE(p.seed_key, '') NOT LIKE 'mig.ph.%'
  LOOP
    v_cont_seed := 'mig.ph.continent.' || v_orphan.id::text;
    v_country_seed := 'mig.ph.country.' || v_orphan.id::text;

    SELECT id INTO v_continent
    FROM public.world_places
    WHERE world_profile_id = p_world_profile_id AND seed_key = v_cont_seed;

    IF v_continent IS NULL THEN
      v_cont_name := public.atlas_wb_next_placeholder_name(
        p_world_profile_id, NULL, 'continent'
      );
      INSERT INTO public.world_places (
        world_profile_id, parent_place_id, kind, name, status, seed_key, sort_order
      ) VALUES (
        p_world_profile_id, NULL, 'continent', v_cont_name, 'placeholder', v_cont_seed, 0
      )
      RETURNING id INTO v_continent;
      v_created_places := array_append(v_created_places, v_continent);

      v_cont_map := public.atlas_wb_create_primary_map(
        p_world_profile_id, v_continent, 'continent',
        v_cont_name || ' (Karte)', v_root_map
      );
      v_created_maps := array_append(v_created_maps, v_cont_map);
      SELECT id INTO v_link FROM public.world_place_map_links
      WHERE place_id = v_continent AND usage = 'primary' LIMIT 1;
      IF v_link IS NOT NULL THEN
        v_created_links := array_append(v_created_links, v_link);
      END IF;
    ELSE
      SELECT map_id INTO v_cont_map
      FROM public.world_place_map_links
      WHERE place_id = v_continent AND usage = 'primary'
      LIMIT 1;
      IF v_cont_map IS NULL THEN
        v_link := public.atlas_wb_migration_ensure_primary_link(
          p_world_profile_id, v_continent
        );
        SELECT map_id INTO v_cont_map
        FROM public.world_place_map_links WHERE id = v_link;
      END IF;
    END IF;

    SELECT id INTO v_country
    FROM public.world_places
    WHERE world_profile_id = p_world_profile_id AND seed_key = v_country_seed;

    IF v_country IS NULL THEN
      v_country_name := public.atlas_wb_next_placeholder_name(
        p_world_profile_id, v_continent, 'country'
      );
      INSERT INTO public.world_places (
        world_profile_id, parent_place_id, kind, name, status, seed_key, sort_order
      ) VALUES (
        p_world_profile_id, v_continent, 'country', v_country_name,
        'placeholder', v_country_seed, 0
      )
      RETURNING id INTO v_country;
      v_created_places := array_append(v_created_places, v_country);

      v_country_map := public.atlas_wb_create_primary_map(
        p_world_profile_id, v_country, 'country',
        v_country_name || ' (Karte)', COALESCE(v_cont_map, v_root_map)
      );
      v_created_maps := array_append(v_created_maps, v_country_map);
      SELECT id INTO v_link FROM public.world_place_map_links
      WHERE place_id = v_country AND usage = 'primary' LIMIT 1;
      IF v_link IS NOT NULL THEN
        v_created_links := array_append(v_created_links, v_link);
      END IF;
    ELSE
      -- Ensure country still parents under continent (idempotent repair).
      UPDATE public.world_places
      SET parent_place_id = v_continent, updated_at = now()
      WHERE id = v_country
        AND parent_place_id IS DISTINCT FROM v_continent;
      SELECT map_id INTO v_country_map
      FROM public.world_place_map_links
      WHERE place_id = v_country AND usage = 'primary'
      LIMIT 1;
      IF v_country_map IS NULL THEN
        v_link := public.atlas_wb_migration_ensure_primary_link(
          p_world_profile_id, v_country
        );
        SELECT map_id INTO v_country_map
        FROM public.world_place_map_links WHERE id = v_link;
      END IF;
    END IF;

    SELECT parent_place_id INTO v_old_parent
    FROM public.world_places WHERE id = v_orphan.id;

    IF v_old_parent IS DISTINCT FROM v_country THEN
      UPDATE public.world_places
      SET parent_place_id = v_country, updated_at = now()
      WHERE id = v_orphan.id;
      v_rewrites := v_rewrites || jsonb_build_array(jsonb_build_object(
        'place_id', v_orphan.id,
        'old_parent_place_id', v_old_parent,
        'new_parent_place_id', v_country
      ));
    END IF;
  END LOOP;

  -- Primary map links for non-archived places (never invent classification).
  FOR v_place_row IN
    SELECT p.id
    FROM public.world_places p
    WHERE p.world_profile_id = p_world_profile_id
      AND p.status IS DISTINCT FROM 'archived'
      AND NOT EXISTS (
        SELECT 1 FROM public.world_place_map_links l
        WHERE l.place_id = p.id AND l.usage = 'primary'
      )
  LOOP
    v_link := public.atlas_wb_migration_ensure_primary_link(
      p_world_profile_id, v_place_row.id
    );
    IF v_link IS NOT NULL AND NOT (v_link = ANY (v_created_links)) THEN
      v_created_links := array_append(v_created_links, v_link);
    END IF;
  END LOOP;

  -- Repair parent_map_id for non-root maps that are NULL → world root.
  UPDATE public.world_atlas_maps m
  SET parent_map_id = v_root_map,
      updated_at = now()
  WHERE m.world_profile_id = p_world_profile_id
    AND m.parent_map_id IS NULL
    AND m.kind IS DISTINCT FROM 'world'
    AND m.kind IS DISTINCT FROM 'legacy_tiles';

  SELECT count(*)::int INTO v_after_places
  FROM public.world_places
  WHERE world_profile_id = p_world_profile_id;

  INSERT INTO public.atlas_wb_migration_apply_batches (
    id, world_profile_id, target, created_place_ids, created_map_ids,
    created_link_ids, parent_rewrites, notes
  ) VALUES (
    v_batch, p_world_profile_id, p_target, v_created_places, v_created_maps,
    v_created_links, v_rewrites,
    format('apply places %s→%s', v_before_places, v_after_places)
  );

  RETURN jsonb_build_object(
    'batch_id', v_batch,
    'target', p_target,
    'world_profile_id', p_world_profile_id,
    'created_place_ids', to_jsonb(v_created_places),
    'created_map_ids', to_jsonb(v_created_maps),
    'created_link_ids', to_jsonb(v_created_links),
    'parent_rewrites', v_rewrites,
    'place_count_before', v_before_places,
    'place_count_after', v_after_places
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.atlas_wb_migration_ensure_primary_link(p_world uuid, p_place uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_existing UUID;
  v_map UUID;
  v_link UUID;
  v_kind TEXT;
  v_name TEXT;
  v_parent_map UUID;
  v_root UUID;
BEGIN
  SELECT l.id INTO v_existing
  FROM public.world_place_map_links l
  WHERE l.place_id = p_place AND l.usage = 'primary'
  LIMIT 1;
  IF v_existing IS NOT NULL THEN
    RETURN v_existing;
  END IF;

  -- Prefer overview → footprint → any existing link (retain map UUID).
  SELECT l.map_id INTO v_map
  FROM public.world_place_map_links l
  WHERE l.place_id = p_place
  ORDER BY CASE l.usage
    WHEN 'overview' THEN 0
    WHEN 'footprint' THEN 1
    WHEN 'entrance' THEN 2
    WHEN 'interior' THEN 3
    WHEN 'dungeon' THEN 4
    ELSE 5
  END, l.created_at ASC
  LIMIT 1;

  IF v_map IS NOT NULL THEN
    INSERT INTO public.world_place_map_links (
      world_profile_id, place_id, map_id, usage, anchor
    ) VALUES (
      p_world, p_place, v_map, 'primary', '{}'::jsonb
    )
    RETURNING id INTO v_link;
    RETURN v_link;
  END IF;

  SELECT kind, name INTO v_kind, v_name
  FROM public.world_places
  WHERE id = p_place AND world_profile_id = p_world;

  SELECT map_id INTO v_parent_map
  FROM public.world_place_map_links
  WHERE place_id = (
    SELECT parent_place_id FROM public.world_places WHERE id = p_place
  ) AND usage = 'primary'
  LIMIT 1;

  v_root := public.atlas_wb_ensure_world_root_map(p_world);
  v_map := public.atlas_wb_create_primary_map(
    p_world,
    p_place,
    COALESCE(v_kind, 'place'),
    COALESCE(v_name, 'Ort') || ' (Karte)',
    COALESCE(v_parent_map, v_root)
  );

  SELECT id INTO v_link
  FROM public.world_place_map_links
  WHERE place_id = p_place AND usage = 'primary'
  LIMIT 1;
  RETURN v_link;
END;
$function$

CREATE OR REPLACE FUNCTION public.atlas_wb_migration_inventory(p_world_profile_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user UUID := auth.uid();
  v_owner UUID;
BEGIN
  IF v_user IS NULL THEN
    RAISE EXCEPTION 'not authenticated' USING ERRCODE = '42501';
  END IF;
  SELECT owner_user_id INTO v_owner FROM public.world_profiles WHERE id = p_world_profile_id;
  IF v_owner IS NULL OR v_owner <> v_user THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  RETURN jsonb_build_object(
    'world_profile_id', p_world_profile_id,
    'gate_enabled', COALESCE(
      (SELECT enabled FROM public.atlas_wb_migration_gates g WHERE g.world_profile_id = p_world_profile_id),
      false
    ),
    'place_counts', (
      SELECT COALESCE(jsonb_object_agg(kind, n), '{}'::jsonb)
      FROM (
        SELECT kind, count(*)::int AS n
        FROM public.world_places
        WHERE world_profile_id = p_world_profile_id
        GROUP BY kind
      ) s
    ),
    'orphan_settlements', (
      SELECT COALESCE(jsonb_agg(jsonb_build_object(
        'id', id, 'public_id', public_id, 'name', name, 'kind', kind
      ) ORDER BY name), '[]'::jsonb)
      FROM public.world_places
      WHERE world_profile_id = p_world_profile_id
        AND parent_place_id IS NULL
        AND kind = 'settlement'
        AND status IS DISTINCT FROM 'archived'
    ),
    'review_kinds', (
      SELECT COALESCE(jsonb_agg(jsonb_build_object(
        'id', id, 'public_id', public_id, 'name', name, 'kind', kind
      ) ORDER BY kind, name), '[]'::jsonb)
      FROM public.world_places
      WHERE world_profile_id = p_world_profile_id
        AND kind IN ('region', 'district', 'site', 'interior', 'dungeon')
        AND status IS DISTINCT FROM 'archived'
    ),
    'map_counts', (
      SELECT COALESCE(jsonb_object_agg(kind, n), '{}'::jsonb)
      FROM (
        SELECT kind, count(*)::int AS n
        FROM public.world_atlas_maps
        WHERE world_profile_id = p_world_profile_id
        GROUP BY kind
      ) s
    )
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.atlas_wb_migration_rollback_batch(p_batch_id uuid, p_confirm text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_batch public.atlas_wb_migration_apply_batches%ROWTYPE;
  v_user UUID := auth.uid();
  v_owner UUID;
  v_rewrite JSONB;
  v_place_id UUID;
  v_old UUID;
  v_removed_places INT := 0;
  v_removed_maps INT := 0;
  v_removed_links INT := 0;
BEGIN
  IF p_confirm IS DISTINCT FROM 'ROLLBACK_BATCH' THEN
    RAISE EXCEPTION 'rollback confirm token required' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO v_batch
  FROM public.atlas_wb_migration_apply_batches
  WHERE id = p_batch_id;
  IF v_batch.id IS NULL THEN
    RAISE EXCEPTION 'batch not found' USING ERRCODE = 'P0002';
  END IF;
  IF v_batch.rolled_back_at IS NOT NULL THEN
    RETURN jsonb_build_object(
      'batch_id', p_batch_id,
      'already_rolled_back', true,
      'rolled_back_at', v_batch.rolled_back_at
    );
  END IF;

  SELECT owner_user_id INTO v_owner
  FROM public.world_profiles WHERE id = v_batch.world_profile_id;
  IF v_user IS NOT NULL AND v_user <> v_owner THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  IF v_user IS NULL
     AND current_setting('atlas.migration_operator', true) IS DISTINCT FROM '1' THEN
    RAISE EXCEPTION 'not authenticated' USING ERRCODE = '42501';
  END IF;

  -- Restore parent rewrites first (orphan settlements).
  FOR v_rewrite IN SELECT * FROM jsonb_array_elements(v_batch.parent_rewrites)
  LOOP
    v_place_id := (v_rewrite->>'place_id')::uuid;
    v_old := NULLIF(v_rewrite->>'old_parent_place_id', '')::uuid;
    UPDATE public.world_places
    SET parent_place_id = v_old, updated_at = now()
    WHERE id = v_place_id
      AND world_profile_id = v_batch.world_profile_id;
  END LOOP;

  -- Remove additive primary links created by this batch (maps may be shared).
  IF COALESCE(cardinality(v_batch.created_link_ids), 0) > 0 THEN
    DELETE FROM public.world_place_map_links
    WHERE id = ANY (v_batch.created_link_ids)
      AND world_profile_id = v_batch.world_profile_id;
    GET DIAGNOSTICS v_removed_links = ROW_COUNT;
  END IF;

  IF COALESCE(cardinality(v_batch.created_map_ids), 0) > 0 THEN
    DELETE FROM public.world_atlas_maps
    WHERE id = ANY (v_batch.created_map_ids)
      AND world_profile_id = v_batch.world_profile_id;
    GET DIAGNOSTICS v_removed_maps = ROW_COUNT;
  END IF;

  IF COALESCE(cardinality(v_batch.created_place_ids), 0) > 0 THEN
    DELETE FROM public.world_places
    WHERE id = ANY (v_batch.created_place_ids)
      AND world_profile_id = v_batch.world_profile_id
      AND status = 'placeholder'
      AND seed_key LIKE 'mig.ph.%';
    GET DIAGNOSTICS v_removed_places = ROW_COUNT;
  END IF;

  UPDATE public.atlas_wb_migration_apply_batches
  SET rolled_back_at = now(),
      notes = COALESCE(notes, '') || ' | rolled_back'
  WHERE id = p_batch_id;

  RETURN jsonb_build_object(
    'batch_id', p_batch_id,
    'removed_places', v_removed_places,
    'removed_maps', v_removed_maps,
    'removed_links', v_removed_links,
    'restored_parent_rewrites', jsonb_array_length(v_batch.parent_rewrites)
  );
END;
$function$

