CREATE OR REPLACE FUNCTION public.build_dornhain_starter_map_data(p_size integer DEFAULT 24)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  n INT := GREATEST(16, LEAST(COALESCE(p_size, 24), 40));
  v_tiles JSONB := '{}'::jsonb;
  v_x INT;
  v_y INT;
  v_type TEXT;
  v_key TEXT;
BEGIN
  FOR v_y IN 0 .. (n - 1) LOOP
    FOR v_x IN 0 .. (n - 1) LOOP
      v_type := 'grass';
      IF v_x <= 2 OR (v_x <= 4 AND v_y >= n - 6) THEN
        v_type := 'water';
      ELSIF v_y <= 2 OR (v_y <= 4 AND v_x >= n - 8) THEN
        v_type := 'mountain';
      ELSIF v_x >= n - 5 OR (v_x >= n - 7 AND v_y >= 10 AND v_y <= 18) THEN
        v_type := 'forest';
      END IF;
      -- roads market↔tavern↔woods
      IF (v_y = 11 AND v_x BETWEEN 8 AND 12)
         OR (v_x = 10 AND v_y BETWEEN 10 AND 12)
         OR (v_y = 12 AND v_x BETWEEN 12 AND 16) THEN
        v_type := 'road';
      END IF;
      IF (v_x = 8 AND v_y = 12)
         OR (v_x = 12 AND v_y = 10)
         OR (v_x = 16 AND v_y = 14)
         OR (v_x = 18 AND v_y = 8) THEN
        v_type := 'city';
      END IF;
      v_key := v_x::text || ',' || v_y::text;
      v_tiles := jsonb_set(
        v_tiles,
        ARRAY[v_key],
        jsonb_build_object('type', v_type, 'countryId', NULL),
        true
      );
    END LOOP;
  END LOOP;

  RETURN jsonb_build_object(
    'size', n,
    'tiles', v_tiles,
    'countries', '[]'::jsonb,
    'pins', jsonb_build_array(
      jsonb_build_object('id', 'pin.tavern', 'title', 'Taverne', 'x', 8, 'y', 12, 'discovered', true, 'locationRef', 'loc.tavern'),
      jsonb_build_object('id', 'pin.market', 'title', 'Markt', 'x', 12, 'y', 10, 'discovered', true, 'locationRef', 'loc.market'),
      jsonb_build_object('id', 'pin.woods', 'title', 'Wald', 'x', 16, 'y', 14, 'discovered', true, 'locationRef', 'loc.woods'),
      jsonb_build_object('id', 'pin.crypt', 'title', 'Krypta', 'x', 18, 'y', 8, 'discovered', false, 'locationRef', 'loc.crypt')
    )
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.clear_npc_creature_instance_temp_controller_on_member_inactive()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_user UUID;
  v_project UUID;
BEGIN
  IF TG_OP = 'UPDATE'
     AND OLD.status = 'active'
     AND NEW.status IS DISTINCT FROM 'active' THEN
    v_user := NEW.user_id;
    v_project := NEW.project_id;
  ELSIF TG_OP = 'DELETE' AND OLD.status = 'active' THEN
    v_user := OLD.user_id;
    v_project := OLD.project_id;
  ELSE
    IF TG_OP = 'DELETE' THEN
      RETURN OLD;
    END IF;
    RETURN NEW;
  END IF;

  UPDATE public.npc_creature_instances
  SET runtime = jsonb_set(
        COALESCE(runtime, '{}'::jsonb),
        '{temporaryControllerUserId}',
        'null'::jsonb,
        true
      ),
      updated_at = NOW()
  WHERE project_id = v_project
    AND runtime->>'temporaryControllerUserId' = v_user::text;

  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.clear_npc_creature_instance_temp_controllers_for_session(p_session_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_project_id UUID;
  v_count INTEGER := 0;
BEGIN
  IF p_session_id IS NULL THEN
    RAISE EXCEPTION 'missing session';
  END IF;

  SELECT s.project_id INTO v_project_id
  FROM public.sessions s
  WHERE s.id = p_session_id;

  IF v_project_id IS NULL THEN
    RAISE EXCEPTION 'session not found';
  END IF;

  PERFORM public.assert_npc_creature_instance_gm(v_project_id);

  UPDATE public.npc_creature_instances
  SET runtime = jsonb_set(
        COALESCE(runtime, '{}'::jsonb),
        '{temporaryControllerUserId}',
        'null'::jsonb,
        true
      ),
      updated_at = NOW()
  WHERE session_id = p_session_id
    AND runtime ? 'temporaryControllerUserId'
    AND runtime->>'temporaryControllerUserId' IS NOT NULL
    AND btrim(COALESCE(runtime->>'temporaryControllerUserId', '')) <> '';

  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN v_count;
END;
$function$

CREATE OR REPLACE FUNCTION public.consume_session_recap_rate_limit(p_user_id uuid, p_limit integer, p_window_seconds integer DEFAULT 60)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_now TIMESTAMPTZ := clock_timestamp();
  v_count INTEGER;
BEGIN
  IF p_user_id IS NULL THEN
    RETURN FALSE;
  END IF;
  IF p_limit < 1 OR p_limit > 60 THEN
    RAISE EXCEPTION 'p_limit must be between 1 and 60';
  END IF;
  IF p_window_seconds < 1 OR p_window_seconds > 3600 THEN
    RAISE EXCEPTION 'p_window_seconds must be between 1 and 3600';
  END IF;

  INSERT INTO public.session_recap_rate_limits AS limits (
    user_id, window_started_at, request_count, updated_at
  )
  VALUES (p_user_id, v_now, 1, v_now)
  ON CONFLICT (user_id) DO UPDATE
  SET
    window_started_at = CASE
      WHEN limits.window_started_at <= v_now - (p_window_seconds * INTERVAL '1 second') THEN v_now
      ELSE limits.window_started_at
    END,
    request_count = CASE
      WHEN limits.window_started_at <= v_now - (p_window_seconds * INTERVAL '1 second') THEN 1
      ELSE LEAST(limits.request_count + 1, p_limit + 1)
    END,
    updated_at = v_now
  RETURNING request_count INTO v_count;

  RETURN v_count <= p_limit;
END;
$function$

CREATE OR REPLACE FUNCTION public.copy_native_saga_definition(p_source_saga_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user UUID := auth.uid();
  v_src public.saga_definitions%ROWTYPE;
  v_pub public.saga_definition_versions%ROWTYPE;
  v_new_id UUID := gen_random_uuid();
  v_ver_id UUID := gen_random_uuid();
  v_draft_id UUID := gen_random_uuid();
  v_slug TEXT;
  v_payload JSONB;
BEGIN
  IF v_user IS NULL THEN
    RAISE EXCEPTION 'not authenticated' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO v_src FROM public.saga_definitions WHERE id = p_source_saga_id;
  IF NOT FOUND OR v_src.origin <> 'native' THEN
    RAISE EXCEPTION 'Nur native Sagas können kopiert werden' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_pub
  FROM public.saga_definition_versions
  WHERE saga_id = v_src.id AND status = 'published'
  ORDER BY published_at DESC NULLS LAST, created_at DESC
  LIMIT 1;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Native Fassung fehlt' USING ERRCODE = 'P0002';
  END IF;

  v_payload := v_pub.payload;
  v_slug := 'user.' || replace(v_new_id::text, '-', '');

  INSERT INTO public.saga_definitions (
    id, slug, title, synopsis, origin, owner_user_id, draft_revision
  ) VALUES (
    v_new_id,
    v_slug,
    v_src.title || ' (Kopie)',
    v_src.synopsis,
    'user',
    v_user,
    0
  );

  INSERT INTO public.saga_definition_versions (
    id, saga_id, version_label, status, payload, published_at
  ) VALUES (
    v_ver_id, v_new_id, 'v1', 'published', v_payload, NOW()
  );

  INSERT INTO public.saga_definition_versions (
    id, saga_id, version_label, status, payload, published_at
  ) VALUES (
    v_draft_id, v_new_id, 'draft', 'draft', v_payload, NULL
  );

  RETURN jsonb_build_object('sagaId', v_new_id, 'versionId', v_ver_id);
END;
$function$

CREATE OR REPLACE FUNCTION public.create_play_session(p_project_id uuid, p_name text DEFAULT NULL::text)
 RETURNS sessions
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE actor UUID := auth.uid(); created public.sessions;
BEGIN
  IF actor IS NULL THEN RAISE EXCEPTION 'Authentication required' USING ERRCODE = '42501'; END IF;
  IF p_project_id IS NULL THEN RAISE EXCEPTION 'project_id required' USING ERRCODE = '22023'; END IF;
  IF NOT public.is_project_gm(p_project_id, actor) THEN RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501'; END IF;
  INSERT INTO public.sessions (project_id, session_number, name, status, code)
  VALUES (p_project_id, public.allocate_next_session_number(p_project_id), NULLIF(BTRIM(p_name), ''), 'waiting', public.generate_unique_session_code())
  RETURNING * INTO created;
  RETURN created;
END;
$function$

CREATE OR REPLACE FUNCTION public.create_project_from_saga_version(p_saga_id uuid, p_version_id uuid, p_name text DEFAULT NULL::text)
 RETURNS projects
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  actor UUID := auth.uid();
  v_def public.saga_definitions%ROWTYPE;
  v_ver public.saga_definition_versions%ROWTYPE;
  created public.projects;
  v_name TEXT;
  v_adv JSONB := '{}'::jsonb;
BEGIN
  IF actor IS NULL THEN RAISE EXCEPTION 'not authenticated' USING ERRCODE = '42501'; END IF;

  SELECT * INTO v_def FROM public.saga_definitions WHERE id = p_saga_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Saga not found' USING ERRCODE = 'P0002'; END IF;
  SELECT * INTO v_ver FROM public.saga_definition_versions
   WHERE id = p_version_id AND saga_id = p_saga_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Fassung not found' USING ERRCODE = 'P0002'; END IF;
  IF v_ver.status <> 'published' THEN
    RAISE EXCEPTION 'Nur veröffentlichte Fassungen' USING ERRCODE = '22023';
  END IF;

  IF v_def.origin NOT IN ('native', 'user') AND v_def.owner_user_id IS DISTINCT FROM actor THEN
    -- private_backfill: only owner may spawn another group
    IF v_def.owner_user_id IS DISTINCT FROM actor THEN
      RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
    END IF;
  END IF;

  v_name := NULLIF(BTRIM(COALESCE(p_name, '')), '');
  IF v_name IS NULL THEN
    v_name := v_def.title || ' · Gruppe';
  END IF;

  IF jsonb_typeof(v_ver.payload->'initialAdventure') = 'object' THEN
    v_adv := v_ver.payload->'initialAdventure';
  END IF;

  INSERT INTO public.projects (
    code, name, description, gm_user_id, status, saga_id, saga_version_id, adventure_runtime
  ) VALUES (
    NULL, -- trigger generate_project_code
    v_name,
    v_def.synopsis,
    actor,
    'active',
    v_def.id,
    v_ver.id,
    v_adv
  )
  RETURNING * INTO created;

  INSERT INTO public.project_members (project_id, user_id, role, status)
  VALUES (created.id, actor, 'gm', 'active');

  RETURN created;
END;
$function$

CREATE OR REPLACE FUNCTION public.create_project_session(p_project_id uuid, p_name text DEFAULT NULL::text, p_notes text DEFAULT NULL::text)
 RETURNS sessions
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  created public.sessions;
  actor UUID := auth.uid();
  is_member BOOLEAN := false;
  v_adv JSONB := '{}'::jsonb;
  v_knowledge JSONB := NULL;
  v_world JSONB;
BEGIN
  IF actor IS NULL THEN RAISE EXCEPTION 'not authenticated'; END IF;
  SELECT EXISTS (
    SELECT 1 FROM public.project_members pm
     WHERE pm.project_id = p_project_id AND pm.user_id = actor AND pm.status = 'active' AND pm.role IN ('gm', 'player')
  ) OR EXISTS (SELECT 1 FROM public.projects p WHERE p.id = p_project_id AND p.gm_user_id = actor)
  INTO is_member;
  IF NOT is_member THEN RAISE EXCEPTION 'forbidden'; END IF;

  SELECT COALESCE(adventure_runtime, '{}'::jsonb) INTO v_adv
  FROM public.projects WHERE id = p_project_id;
  IF jsonb_typeof(v_adv) IS DISTINCT FROM 'object' THEN
    v_adv := '{}'::jsonb;
  END IF;

  -- Carry knowledge from most recent completed session world_state when present.
  SELECT s.world_state->'shared'->'knowledge' INTO v_knowledge
  FROM public.sessions s
  WHERE s.project_id = p_project_id
    AND s.status = 'completed'
    AND s.world_state ? 'shared'
    AND (s.world_state->'shared') ? 'knowledge'
  ORDER BY s.session_number DESC
  LIMIT 1;

  v_world := jsonb_build_object(
    'shared',
    CASE
      WHEN v_knowledge IS NOT NULL AND jsonb_typeof(v_knowledge) = 'object' THEN
        jsonb_build_object('adventure', v_adv, 'knowledge', v_knowledge)
      ELSE
        jsonb_build_object('adventure', v_adv)
    END
  );

  INSERT INTO public.sessions (project_id, session_number, name, notes, status, code, world_state)
  VALUES (
    p_project_id,
    public.allocate_next_session_number(p_project_id),
    NULLIF(btrim(p_name), ''),
    NULLIF(btrim(p_notes), ''),
    'scheduled',
    public.generate_unique_session_code(),
    v_world
  )
  RETURNING * INTO created;
  RETURN created;
END;
$function$

CREATE OR REPLACE FUNCTION public.create_session_invite(p_session_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  actor UUID := auth.uid();
  v_session public.sessions;
  v_token TEXT;
  v_expires TIMESTAMPTZ;
  v_id UUID;
BEGIN
  IF actor IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE = '42501';
  END IF;
  IF p_session_id IS NULL THEN
    RAISE EXCEPTION 'session_id required' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_session FROM public.sessions WHERE id = p_session_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Session not found' USING ERRCODE = 'P0002';
  END IF;
  IF v_session.status = 'completed' THEN
    RAISE EXCEPTION 'Session is completed' USING ERRCODE = '22023';
  END IF;
  IF NOT public.is_project_gm(v_session.project_id, actor) THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  -- Rotate: revoke prior active invites for this session.
  UPDATE public.session_invites
     SET revoked_at = NOW()
   WHERE session_id = p_session_id
     AND revoked_at IS NULL;

  v_token := public.generate_session_invite_token();
  v_expires := NOW() + INTERVAL '7 days';

  INSERT INTO public.session_invites (session_id, token, created_by, expires_at)
  VALUES (p_session_id, v_token, actor, v_expires)
  RETURNING id INTO v_id;

  RETURN jsonb_build_object(
    'id', v_id,
    'token', v_token,
    'session_id', v_session.id,
    'expires_at', v_expires
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.create_user_saga_definition(p_title text, p_blurb text DEFAULT ''::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user UUID := auth.uid();
  v_new_id UUID := gen_random_uuid();
  v_draft_id UUID := gen_random_uuid();
  v_title TEXT;
  v_blurb TEXT;
  v_payload JSONB;
BEGIN
  IF v_user IS NULL THEN
    RAISE EXCEPTION 'not authenticated' USING ERRCODE = '42501';
  END IF;

  v_title := NULLIF(BTRIM(COALESCE(p_title, '')), '');
  IF v_title IS NULL THEN
    RAISE EXCEPTION 'Titel darf nicht leer sein' USING ERRCODE = '22023';
  END IF;
  v_blurb := COALESCE(p_blurb, '');

  v_payload := jsonb_build_object(
    'packageId', NULL,
    'title', v_title,
    'blurb', v_blurb,
    'synopsis', v_blurb,
    'knowledgeFacts', '[]'::jsonb,
    'locations', '[]'::jsonb,
    'pregens', '[]'::jsonb
  );

  INSERT INTO public.saga_definitions (
    id, slug, title, synopsis, origin, owner_user_id, draft_revision
  ) VALUES (
    v_new_id,
    'user.' || replace(v_new_id::text, '-', ''),
    v_title,
    v_blurb,
    'user',
    v_user,
    0
  );

  INSERT INTO public.saga_definition_versions (
    id, saga_id, version_label, status, payload, published_at
  ) VALUES (
    v_draft_id, v_new_id, 'draft', 'draft', v_payload, NULL
  );

  RETURN jsonb_build_object('sagaId', v_new_id, 'versionId', v_draft_id, 'revision', 0);
END;
$function$

CREATE OR REPLACE FUNCTION public.create_world_node_with_maps(p_world_profile_id uuid, p_kind text, p_name text, p_idempotency_key text, p_subtype text DEFAULT NULL::text, p_parent_place_id uuid DEFAULT NULL::uuid, p_description text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_key TEXT := NULLIF(btrim(p_idempotency_key), '');
  v_name TEXT := NULLIF(btrim(p_name), '');
  v_kind TEXT := NULLIF(btrim(p_kind), '');
  v_cached JSONB;
  v_root_map UUID;
  v_parent UUID := p_parent_place_id;
  v_parent_kind TEXT;
  v_parent_map UUID;
  v_need TEXT;
  v_chain TEXT[];
  v_k TEXT;
  v_place UUID;
  v_map UUID;
  v_created JSONB := '[]'::jsonb;
  v_status TEXT;
  v_ph_name TEXT;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'not authenticated' USING ERRCODE = '42501';
  END IF;
  IF p_world_profile_id IS NULL OR v_kind IS NULL OR v_name IS NULL OR v_key IS NULL THEN
    RAISE EXCEPTION 'invalid input' USING ERRCODE = '22023';
  END IF;
  IF NOT public.atlas_wb_is_canonical_kind(v_kind) THEN
    RAISE EXCEPTION 'kind must be canonical WorldNodeKind' USING ERRCODE = '22023';
  END IF;
  IF NOT public.current_user_can_edit_world_profile(p_world_profile_id) THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  SELECT result INTO v_cached
  FROM public.world_node_create_idempotency
  WHERE world_profile_id = p_world_profile_id
    AND idempotency_key = v_key;
  IF v_cached IS NOT NULL THEN
    RETURN v_cached;
  END IF;

  -- Validate optional parent
  IF v_parent IS NOT NULL THEN
    SELECT kind INTO v_parent_kind
    FROM public.world_places
    WHERE id = v_parent AND world_profile_id = p_world_profile_id;
    IF v_parent_kind IS NULL THEN
      RAISE EXCEPTION 'parent not in world' USING ERRCODE = '23514';
    END IF;
  END IF;

  -- Missing ancestors (mirrors domains/world/hierarchy missingAncestorKinds):
  -- walk required parents upward; stop once tip rank covers the cursor.
  v_need := public.atlas_wb_required_parent_kind(v_kind);
  v_chain := ARRAY[]::TEXT[];
  WHILE v_need IS NOT NULL LOOP
    EXIT WHEN v_parent IS NOT NULL
      AND v_parent_kind IS NOT NULL
      AND public.atlas_wb_kind_rank(v_parent_kind) IS NOT NULL
      AND public.atlas_wb_kind_rank(v_need) <= public.atlas_wb_kind_rank(v_parent_kind);
    v_chain := array_prepend(v_need, v_chain);
    v_need := public.atlas_wb_required_parent_kind(v_need);
  END LOOP;

  -- Empty chain ⇒ tip must already be the valid immediate parent (legacy aliases OK).
  IF COALESCE(cardinality(v_chain), 0) = 0 THEN
    v_need := public.atlas_wb_required_parent_kind(v_kind);
    IF NOT public.atlas_wb_tip_satisfies(v_need, v_parent_kind) THEN
      RAISE EXCEPTION 'invalid parent kind edge' USING ERRCODE = '23514';
    END IF;
  ELSIF v_parent IS NOT NULL THEN
    -- Non-empty chain under a tip ⇒ tip must parent the highest missing ancestor.
    IF NOT public.atlas_wb_tip_satisfies(
      public.atlas_wb_required_parent_kind(v_chain[1]),
      v_parent_kind
    ) THEN
      RAISE EXCEPTION 'invalid parent kind edge' USING ERRCODE = '23514';
    END IF;
  END IF;

  v_root_map := public.atlas_wb_ensure_world_root_map(p_world_profile_id);

  -- Resolve parent map for first insert
  IF v_parent IS NOT NULL THEN
    SELECT map_id INTO v_parent_map
    FROM public.world_place_map_links
    WHERE place_id = v_parent AND usage = 'primary'
    LIMIT 1;
  END IF;
  IF v_parent_map IS NULL THEN
    v_parent_map := v_root_map;
  END IF;

  -- Create ancestors
  FOREACH v_k IN ARRAY v_chain LOOP
    v_ph_name := public.atlas_wb_next_placeholder_name(p_world_profile_id, v_parent, v_k);
    INSERT INTO public.world_places (
      world_profile_id, parent_place_id, kind, name, description, status, subtype, sort_order
    ) VALUES (
      p_world_profile_id, v_parent, v_k, v_ph_name, NULL, 'placeholder', NULL, 0
    )
    RETURNING id INTO v_place;

    v_map := public.atlas_wb_create_primary_map(
      p_world_profile_id, v_place, v_k, v_ph_name || ' (Karte)', v_parent_map
    );

    v_created := v_created || jsonb_build_array(jsonb_build_object(
      'placeId', v_place,
      'kind', v_k,
      'name', v_ph_name,
      'status', 'placeholder',
      'mapId', v_map,
      'role', 'ancestor_placeholder'
    ));

    v_parent := v_place;
    v_parent_kind := v_k;
    v_parent_map := v_map;
  END LOOP;

  -- Target node
  v_status := 'draft';
  INSERT INTO public.world_places (
    world_profile_id, parent_place_id, kind, name, description, status, subtype, sort_order
  ) VALUES (
    p_world_profile_id, v_parent, v_kind, v_name, p_description, v_status, NULLIF(btrim(p_subtype), ''), 0
  )
  RETURNING id INTO v_place;

  v_map := public.atlas_wb_create_primary_map(
    p_world_profile_id, v_place, v_kind, v_name || ' (Karte)', v_parent_map
  );

  v_created := v_created || jsonb_build_array(jsonb_build_object(
    'placeId', v_place,
    'kind', v_kind,
    'name', v_name,
    'status', v_status,
    'mapId', v_map,
    'role', 'target'
  ));

  v_cached := jsonb_build_object(
    'worldProfileId', p_world_profile_id,
    'worldRootMapId', v_root_map,
    'targetPlaceId', v_place,
    'targetMapId', v_map,
    'created', v_created,
    'idempotencyKey', v_key
  );

  INSERT INTO public.world_node_create_idempotency (world_profile_id, idempotency_key, result)
  VALUES (p_world_profile_id, v_key, v_cached);

  RETURN v_cached;
END;
$function$

CREATE OR REPLACE FUNCTION public.current_user_can_read_world_atlas_object(p_object_name text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_parts TEXT[];
  v_world UUID;
BEGIN
  IF auth.uid() IS NULL OR p_object_name IS NULL THEN
    RETURN FALSE;
  END IF;
  v_parts := storage.foldername(p_object_name);
  IF cardinality(v_parts) < 2 THEN
    RETURN FALSE;
  END IF;
  -- Owner folder always OK
  IF v_parts[1] = auth.uid()::text THEN
    RETURN TRUE;
  END IF;
  BEGIN
    v_world := v_parts[2]::UUID;
  EXCEPTION WHEN OTHERS THEN
    RETURN FALSE;
  END;
  IF public.current_user_can_edit_world_profile(v_world) THEN
    RETURN TRUE;
  END IF;
  -- Party: only if some revealed primary map uses this basemap path
  RETURN EXISTS (
    SELECT 1
    FROM public.world_atlas_maps m
    INNER JOIN public.world_place_map_links l
      ON l.map_id = m.id AND l.usage = 'primary'
    INNER JOIN public.world_places p
      ON p.id = l.place_id AND p.status = 'canonical'
    INNER JOIN public.saga_asset_bindings b
      ON b.world_place_id = p.id
     AND b.asset_kind = 'location'
     AND b.reveal = 'party'
    INNER JOIN public.projects proj
      ON proj.id = b.project_id
     AND proj.world_profile_id = m.world_profile_id
    WHERE m.world_profile_id = v_world
      AND (
        m.basemap_storage_path = p_object_name
        OR m.azgaar_map_storage_path = p_object_name
      )
      AND public.current_user_can_read_world_profile(v_world)
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.delete_world_node(p_world_profile_id uuid, p_place_id uuid, p_confirm boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_preview JSONB;
  v_ids UUID[];
  v_maps UUID[];
  v_n INT;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'not authenticated' USING ERRCODE = '42501';
  END IF;
  IF NOT public.current_user_can_edit_world_profile(p_world_profile_id) THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  v_preview := public.preview_world_node_consequences(p_world_profile_id, p_place_id);
  IF (v_preview->>'requiresConfirm')::BOOLEAN IS TRUE AND p_confirm IS NOT TRUE THEN
    RAISE EXCEPTION 'confirmation required' USING ERRCODE = '22023';
  END IF;

  v_ids := public.atlas_wb_descendant_ids(p_world_profile_id, p_place_id);
  v_ids := array_append(v_ids, p_place_id);

  SELECT COALESCE(array_agg(map_id), ARRAY[]::UUID[]) INTO v_maps
  FROM public.world_place_map_links
  WHERE world_profile_id = p_world_profile_id AND place_id = ANY (v_ids);

  -- Detach saga bindings (keep saga rows; clear place FK)
  UPDATE public.saga_asset_bindings
  SET world_place_id = NULL, updated_at = NOW()
  WHERE world_place_id = ANY (v_ids);

  DELETE FROM public.world_place_map_links
  WHERE world_profile_id = p_world_profile_id AND place_id = ANY (v_ids);

  DELETE FROM public.world_places
  WHERE world_profile_id = p_world_profile_id AND id = ANY (v_ids);

  GET DIAGNOSTICS v_n = ROW_COUNT;

  IF cardinality(v_maps) > 0 THEN
    DELETE FROM public.world_atlas_maps
    WHERE world_profile_id = p_world_profile_id
      AND id = ANY (v_maps)
      AND kind <> 'world';
  END IF;

  RETURN jsonb_build_object(
    'deletedCount', v_n,
    'placeIds', to_jsonb(v_ids),
    'consequences', v_preview
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.duplicate_saga_playthrough(p_project_id uuid, p_mode text DEFAULT 'fresh'::text)
 RETURNS TABLE(id uuid, public_id text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  actor UUID := auth.uid();
  src public.projects%ROWTYPE;
  v_ver public.saga_definition_versions%ROWTYPE;
  created public.projects%ROWTYPE;
  v_mode TEXT := lower(btrim(coalesce(p_mode, 'fresh')));
  v_name TEXT;
  v_adv JSONB := '{}'::jsonb;
BEGIN
  IF actor IS NULL THEN
    RAISE EXCEPTION 'not authenticated' USING ERRCODE = '42501';
  END IF;

  IF v_mode NOT IN ('fresh', 'with_progress') THEN
    RAISE EXCEPTION 'Ungültiger Duplikat-Modus' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO src
  FROM public.projects
  WHERE public.projects.id = p_project_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Saga nicht gefunden' USING ERRCODE = 'P0002';
  END IF;

  IF src.gm_user_id IS DISTINCT FROM actor THEN
    RAISE EXCEPTION 'Nur der Gamemaster kann duplizieren' USING ERRCODE = '42501';
  END IF;

  IF src.saga_id IS NULL OR src.saga_version_id IS NULL THEN
    RAISE EXCEPTION 'Diese Saga hat keine Fassung' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_ver
  FROM public.saga_definition_versions
  WHERE public.saga_definition_versions.id = src.saga_version_id
    AND public.saga_definition_versions.saga_id = src.saga_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Fassung nicht gefunden' USING ERRCODE = 'P0002';
  END IF;

  v_name := btrim(coalesce(src.name, '')) || ' · Kopie';
  IF length(v_name) > 120 THEN
    v_name := left(btrim(coalesce(src.name, 'Saga')), 110) || ' · Kopie';
  END IF;

  IF v_mode = 'with_progress' THEN
    v_adv := coalesce(src.adventure_runtime, '{}'::jsonb);
  ELSIF jsonb_typeof(v_ver.payload->'initialAdventure') = 'object' THEN
    v_adv := v_ver.payload->'initialAdventure';
  END IF;

  INSERT INTO public.projects (
    code,
    name,
    description,
    gm_user_id,
    status,
    saga_id,
    saga_version_id,
    adventure_runtime
  ) VALUES (
    NULL,
    v_name,
    src.description,
    actor,
    'active',
    src.saga_id,
    src.saga_version_id,
    v_adv
  )
  RETURNING * INTO created;

  INSERT INTO public.project_members (project_id, user_id, role, status)
  VALUES (created.id, actor, 'gm', 'active')
  ON CONFLICT (project_id, user_id) DO UPDATE SET
    role = 'gm',
    status = 'active';

  RETURN QUERY SELECT created.id, created.public_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.duplicate_world_node(p_world_profile_id uuid, p_place_id uuid, p_deep boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_src public.world_places%ROWTYPE;
  v_new UUID;
  v_map UUID;
  v_parent_map UUID;
  v_root_map UUID;
  v_created JSONB := '[]'::jsonb;
  v_new_parent UUID;
  v_new_child UUID;
  v_map_new UUID;
  r RECORD;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'not authenticated' USING ERRCODE = '42501';
  END IF;
  IF NOT public.current_user_can_edit_world_profile(p_world_profile_id) THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  v_src := public.atlas_wb_place_row(p_world_profile_id, p_place_id);
  v_root_map := public.atlas_wb_ensure_world_root_map(p_world_profile_id);

  IF v_src.parent_place_id IS NOT NULL THEN
    v_parent_map := public.atlas_wb_primary_map_id(v_src.parent_place_id);
  END IF;
  IF v_parent_map IS NULL THEN
    v_parent_map := v_root_map;
  END IF;

  INSERT INTO public.world_places (
    world_profile_id, parent_place_id, kind, name, description, status, subtype, sort_order
  ) VALUES (
    p_world_profile_id,
    v_src.parent_place_id,
    v_src.kind,
    v_src.name || ' (Kopie)',
    v_src.description,
    'draft',
    v_src.subtype,
    v_src.sort_order
  )
  RETURNING id INTO v_new;

  v_map := public.atlas_wb_create_primary_map(
    p_world_profile_id, v_new, v_src.kind, v_src.name || ' (Kopie) (Karte)', v_parent_map
  );

  v_created := v_created || jsonb_build_array(jsonb_build_object(
    'placeId', v_new, 'mapId', v_map, 'sourcePlaceId', p_place_id, 'role', 'root'
  ));

  IF p_deep IS TRUE THEN
    CREATE TEMP TABLE IF NOT EXISTS atlas_wb_dup_map (
      old_id UUID PRIMARY KEY,
      new_id UUID NOT NULL
    ) ON COMMIT DROP;
    DELETE FROM atlas_wb_dup_map;
    INSERT INTO atlas_wb_dup_map(old_id, new_id) VALUES (p_place_id, v_new);

    FOR r IN
      WITH RECURSIVE tree AS (
        SELECT id, parent_place_id, kind, name, description, subtype, sort_order, 1 AS depth
        FROM public.world_places
        WHERE world_profile_id = p_world_profile_id AND parent_place_id = p_place_id
        UNION ALL
        SELECT p.id, p.parent_place_id, p.kind, p.name, p.description, p.subtype, p.sort_order, t.depth + 1
        FROM public.world_places p
        INNER JOIN tree t ON p.parent_place_id = t.id
        WHERE p.world_profile_id = p_world_profile_id
      )
      SELECT * FROM tree ORDER BY depth ASC
    LOOP
      SELECT new_id INTO v_new_parent FROM atlas_wb_dup_map WHERE old_id = r.parent_place_id;
      INSERT INTO public.world_places (
        world_profile_id, parent_place_id, kind, name, description, status, subtype, sort_order
      ) VALUES (
        p_world_profile_id, v_new_parent, r.kind, r.name, r.description, 'draft', r.subtype, r.sort_order
      )
      RETURNING id INTO v_new_child;

      v_parent_map := public.atlas_wb_primary_map_id(v_new_parent);
      IF v_parent_map IS NULL THEN
        v_parent_map := v_root_map;
      END IF;
      v_map_new := public.atlas_wb_create_primary_map(
        p_world_profile_id, v_new_child, r.kind, r.name || ' (Karte)', v_parent_map
      );
      INSERT INTO atlas_wb_dup_map(old_id, new_id) VALUES (r.id, v_new_child);
      v_created := v_created || jsonb_build_array(jsonb_build_object(
        'placeId', v_new_child, 'mapId', v_map_new, 'sourcePlaceId', r.id, 'role', 'deep_copy'
      ));
    END LOOP;
  END IF;

  RETURN jsonb_build_object(
    'rootPlaceId', v_new,
    'rootMapId', v_map,
    'deep', COALESCE(p_deep, FALSE),
    'created', v_created
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.enforce_character_sheet_status_complete()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_ruleset TEXT := COALESCE(NEW.ruleset_key, 'sagatree-core');
  v_profile JSONB := NEW.sagatree_profile;
BEGIN
  IF NEW.sheet_status IS DISTINCT FROM 'complete' THEN
    RETURN NEW;
  END IF;

  IF TG_OP = 'UPDATE'
     AND COALESCE(OLD.sheet_status, 'incomplete') = 'complete'
  THEN
    RETURN NEW;
  END IF;

  IF NEW.name IS NULL OR length(btrim(NEW.name)) < 1
     OR NEW.class IS NULL OR length(btrim(NEW.class)) < 1
     OR NEW.race IS NULL OR length(btrim(NEW.race)) < 1
     OR NEW.level IS NULL OR NEW.level < 1 OR NEW.level > 20
  THEN
    RAISE EXCEPTION 'Unvollständiger Charakter kann nicht als complete markiert werden'
      USING ERRCODE = '22023';
  END IF;

  IF v_ruleset = 'sagatree-core'
     AND (
       v_profile IS NULL
       OR NEW.attributes IS NULL
       OR NEW.skills IS NULL
     )
  THEN
    RAISE EXCEPTION 'SagaTree-Bögen brauchen Profil, Attribute und Skills für complete'
      USING ERRCODE = '22023';
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.enforce_default_look_profile_binding()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  look_owner UUID;
  look_status TEXT;
BEGIN
  IF NEW.default_look_profile_id IS NULL THEN
    RETURN NEW;
  END IF;

  IF TG_OP = 'UPDATE'
     AND NEW.default_look_profile_id IS NOT DISTINCT FROM OLD.default_look_profile_id THEN
    RETURN NEW;
  END IF;

  SELECT owner_user_id, status
    INTO look_owner, look_status
  FROM public.look_profiles
  WHERE id = NEW.default_look_profile_id;

  IF look_owner IS NULL THEN
    RAISE EXCEPTION 'default_look_profile_id must reference an existing LookProfile';
  END IF;

  IF look_owner IS DISTINCT FROM auth.uid() THEN
    RAISE EXCEPTION 'default_look_profile_id may only reference a LookProfile you own';
  END IF;

  IF look_status IS DISTINCT FROM 'active' THEN
    RAISE EXCEPTION 'default_look_profile_id must reference an active LookProfile';
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.enforce_personal_look_profile_binding()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  new_personal TEXT;
  old_personal TEXT;
  look_owner UUID;
  look_status TEXT;
  blocked_project UUID;
BEGIN
  new_personal := NULLIF(trim(BOTH FROM COALESCE(NEW.appearance->>'personal_look_profile_id', '')), '');
  old_personal := NULLIF(trim(BOTH FROM COALESCE(OLD.appearance->>'personal_look_profile_id', '')), '');

  -- No change to personal look field → skip.
  IF new_personal IS NOT DISTINCT FROM old_personal THEN
    RETURN NEW;
  END IF;

  -- Owner-only (RLS also gates, but fail closed here).
  IF NEW.owner_user_id IS DISTINCT FROM auth.uid() THEN
    RAISE EXCEPTION 'personal_look_profile_id may only be changed by the character owner';
  END IF;

  -- Clearing override is always allowed for the owner.
  IF new_personal IS NULL THEN
    RETURN NEW;
  END IF;

  -- Look must exist, be active, and owned by the writer.
  SELECT owner_user_id, status
    INTO look_owner, look_status
  FROM public.look_profiles
  WHERE id = new_personal;

  IF look_owner IS NULL THEN
    RAISE EXCEPTION 'personal_look_profile_id must reference an existing LookProfile';
  END IF;

  IF look_owner IS DISTINCT FROM auth.uid() THEN
    RAISE EXCEPTION 'personal_look_profile_id may only reference a LookProfile you own';
  END IF;

  IF look_status IS DISTINCT FROM 'active' THEN
    RAISE EXCEPTION 'personal_look_profile_id must reference an active LookProfile';
  END IF;

  -- If any active adventure arc's project disallows player overrides, reject.
  SELECT caa.project_id
    INTO blocked_project
  FROM public.character_adventure_arcs caa
  JOIN public.projects p ON p.id = caa.project_id
  WHERE caa.character_id = NEW.id
    AND caa.status = 'active'
    AND p.allow_player_character_look_override IS FALSE
  LIMIT 1;

  IF blocked_project IS NOT NULL THEN
    RAISE EXCEPTION 'personal Look override is not allowed for this character''s active saga';
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.enforce_session_look_profile_binding()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  look_owner UUID;
  look_status TEXT;
  project_gm UUID;
BEGIN
  IF NEW.look_profile_id IS NULL THEN
    RETURN NEW;
  END IF;

  IF TG_OP = 'UPDATE'
     AND NEW.look_profile_id IS NOT DISTINCT FROM OLD.look_profile_id THEN
    RETURN NEW;
  END IF;

  SELECT gm_user_id INTO project_gm
  FROM public.projects
  WHERE id = NEW.project_id;

  IF project_gm IS NULL THEN
    RAISE EXCEPTION 'session look_profile_id requires a valid project';
  END IF;

  IF project_gm IS DISTINCT FROM auth.uid() THEN
    RAISE EXCEPTION 'session look_profile_id may only be set by the saga GM';
  END IF;

  SELECT owner_user_id, status
    INTO look_owner, look_status
  FROM public.look_profiles
  WHERE id = NEW.look_profile_id;

  IF look_owner IS NULL THEN
    RAISE EXCEPTION 'look_profile_id must reference an existing LookProfile';
  END IF;

  IF look_owner IS DISTINCT FROM auth.uid() THEN
    RAISE EXCEPTION 'look_profile_id may only reference a LookProfile you own';
  END IF;

  IF look_status IS DISTINCT FROM 'active' THEN
    RAISE EXCEPTION 'look_profile_id must reference an active LookProfile';
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.enforce_world_profile_binding_ownership()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.world_profile_id IS NULL THEN
    RETURN NEW;
  END IF;
  IF TG_OP = 'UPDATE'
     AND NEW.world_profile_id IS NOT DISTINCT FROM OLD.world_profile_id THEN
    RETURN NEW;
  END IF;
  IF NOT public.current_user_can_edit_world_profile(NEW.world_profile_id) THEN
    RAISE EXCEPTION 'world_profile_id may only reference a world profile you can edit';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.ensure_active_project_player(p_project_id uuid, p_user_id uuid, p_character_id uuid DEFAULT NULL::uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_status TEXT;
BEGIN
  SELECT status INTO v_status FROM public.project_members
   WHERE project_id = p_project_id AND user_id = p_user_id;
  IF FOUND THEN
    IF v_status IS DISTINCT FROM 'active' THEN
      UPDATE public.project_members SET status = 'active',
             character_id = COALESCE(p_character_id, character_id)
       WHERE project_id = p_project_id AND user_id = p_user_id;
    ELSIF p_character_id IS NOT NULL THEN
      UPDATE public.project_members SET character_id = p_character_id
       WHERE project_id = p_project_id AND user_id = p_user_id;
    END IF;
    RETURN;
  END IF;
  INSERT INTO public.project_members (project_id, user_id, character_id, role, status)
  VALUES (p_project_id, p_user_id, p_character_id, 'player', 'active');
END;
$function$

CREATE OR REPLACE FUNCTION public.ensure_member_saga_gm_bundle(p_member_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_project UUID;
  v_user UUID;
BEGIN
  IF p_member_id IS NULL THEN
    RETURN;
  END IF;

  SELECT project_id, user_id INTO v_project, v_user
  FROM public.project_members
  WHERE id = p_member_id AND status = 'active';
  IF NOT FOUND THEN
    RETURN;
  END IF;

  DELETE FROM public.project_member_saga_grants WHERE member_id = p_member_id;
  INSERT INTO public.project_member_saga_grants (
    project_id, member_id, user_id, permission_key, source_bundle_id, granted_by
  )
  SELECT v_project, p_member_id, v_user, bk.permission_key, 'bundle.saga.gm', NULL
  FROM public.saga_permission_bundle_keys bk
  WHERE bk.bundle_id = 'bundle.saga.gm';

  INSERT INTO public.project_member_saga_bundles (
    member_id, project_id, user_id, bundle_id, assigned_by, updated_at
  ) VALUES (
    p_member_id, v_project, v_user, 'bundle.saga.gm', NULL, NOW()
  )
  ON CONFLICT (member_id) DO UPDATE SET
    bundle_id = 'bundle.saga.gm',
    updated_at = NOW();
END;
$function$

CREATE OR REPLACE FUNCTION public.ensure_native_starter_project(p_slug text DEFAULT 'dornhain.whisper'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  actor UUID := auth.uid();
  v_result JSONB;
  v_def public.saga_definitions%ROWTYPE;
  v_ver public.saga_definition_versions%ROWTYPE;
  existing public.projects%ROWTYPE;
  created public.projects%ROWTYPE;
BEGIN
  IF actor IS NULL THEN
    RAISE EXCEPTION 'not authenticated' USING ERRCODE = '42501';
  END IF;

  IF BTRIM(COALESCE(p_slug, '')) IN ('', 'dornhain.whisper') THEN
    v_result := public.provision_dornhain_starter_for_user(actor);
    IF COALESCE((v_result->>'ok')::boolean, false) IS NOT TRUE THEN
      RAISE EXCEPTION '%', COALESCE(v_result->>'reason', 'provision_failed')
        USING ERRCODE = 'P0001';
    END IF;
    RETURN jsonb_build_object(
      'id', v_result->>'projectId',
      'public_id', v_result->>'publicId',
      'created', COALESCE((v_result->>'created')::boolean, false),
      'name', (SELECT name FROM public.projects WHERE id = (v_result->>'projectId')::uuid),
      'saga_id', (SELECT saga_id FROM public.projects WHERE id = (v_result->>'projectId')::uuid),
      'saga_version_id', (SELECT saga_version_id FROM public.projects WHERE id = (v_result->>'projectId')::uuid),
      'world_profile_id', v_result->>'worldProfileId',
      'bindings', (v_result->>'bindings')::int,
      'characters', (v_result->>'characters')::int
    );
  END IF;

  -- Non-Dornhain native slugs: create project only (legacy path).
  SELECT * INTO v_def
  FROM public.saga_definitions
  WHERE slug = BTRIM(COALESCE(p_slug, ''))
    AND origin = 'native';
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Native Saga nicht gefunden' USING ERRCODE = 'P0002';
  END IF;

  SELECT v.* INTO v_ver
  FROM public.saga_definition_versions v
  WHERE v.saga_id = v_def.id
    AND v.status = 'published'
  ORDER BY v.published_at DESC NULLS LAST
  LIMIT 1;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Keine veröffentlichte Fassung' USING ERRCODE = 'P0002';
  END IF;

  SELECT p.* INTO existing
  FROM public.projects p
  WHERE p.gm_user_id = actor
    AND p.saga_id = v_def.id
    AND p.status IN ('active', 'paused')
  ORDER BY p.created_at ASC NULLS LAST
  LIMIT 1;

  IF FOUND THEN
    RETURN jsonb_build_object(
      'id', existing.id,
      'public_id', existing.public_id,
      'created', false,
      'name', existing.name,
      'saga_id', v_def.id,
      'saga_version_id', COALESCE(existing.saga_version_id, v_ver.id)
    );
  END IF;

  created := public.create_project_from_saga_version(v_def.id, v_ver.id, v_def.title);

  RETURN jsonb_build_object(
    'id', created.id,
    'public_id', created.public_id,
    'created', true,
    'name', created.name,
    'saga_id', v_def.id,
    'saga_version_id', v_ver.id
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.ensure_public_id()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  prefix TEXT;
BEGIN
  IF NEW.public_id IS NOT NULL AND btrim(NEW.public_id) <> '' THEN
    NEW.public_id := upper(btrim(NEW.public_id));
    RETURN NEW;
  END IF;

  prefix := TG_ARGV[0];
  NEW.public_id := public.generate_sagatree_public_id(prefix);
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.ensure_world_atlas_root(p_world_profile_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user UUID := auth.uid();
  v_id UUID;
BEGIN
  IF v_user IS NULL THEN
    RAISE EXCEPTION 'not authenticated' USING ERRCODE = '42501';
  END IF;
  IF NOT public.current_user_can_edit_world_profile(p_world_profile_id) THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  SELECT id INTO v_id
  FROM public.world_atlas_maps
  WHERE world_profile_id = p_world_profile_id
    AND parent_map_id IS NULL
  ORDER BY CASE WHEN kind = 'legacy_tiles' THEN 0 ELSE 1 END, sort_order
  LIMIT 1;

  IF v_id IS NULL THEN
    INSERT INTO public.world_atlas_maps (
      world_profile_id, kind, title, generator_meta
    ) VALUES (
      p_world_profile_id,
      CASE WHEN EXISTS (
        SELECT 1 FROM public.world_maps w WHERE w.world_profile_id = p_world_profile_id
      ) THEN 'legacy_tiles' ELSE 'world' END,
      CASE WHEN EXISTS (
        SELECT 1 FROM public.world_maps w WHERE w.world_profile_id = p_world_profile_id
      ) THEN 'Kachelkarte (Legacy)' ELSE 'Weltkarte' END,
      jsonb_build_object(
        'engine',
        CASE WHEN EXISTS (
          SELECT 1 FROM public.world_maps w WHERE w.world_profile_id = p_world_profile_id
        ) THEN 'legacy_tiles' ELSE 'manual' END
      )
    )
    RETURNING id INTO v_id;
  END IF;

  RETURN public.list_world_atlas_maps(p_world_profile_id, false, NULL);
END;
$function$

CREATE OR REPLACE FUNCTION public.forbid_public_id_change()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF NEW.public_id IS DISTINCT FROM OLD.public_id THEN
    RAISE EXCEPTION 'public_id is immutable';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.generate_project_code()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF NEW.code IS NULL OR NEW.code = '' THEN
    NEW.code := UPPER(SUBSTRING(MD5(RANDOM()::TEXT) FROM 1 FOR 8));
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.generate_sagatree_public_id(p_prefix text)
 RETURNS text
 LANGUAGE plpgsql
AS $function$
DECLARE
  alphabet TEXT := 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
  body TEXT;
  i INT;
  idx INT;
  has_letter BOOLEAN;
  has_digit BOOLEAN;
  ch TEXT;
  attempt INT := 0;
BEGIN
  IF p_prefix IS NULL OR length(p_prefix) < 2 THEN
    RAISE EXCEPTION 'invalid public id prefix';
  END IF;

  LOOP
    attempt := attempt + 1;
    IF attempt > 64 THEN
      RAISE EXCEPTION 'failed to generate public id body';
    END IF;

    body := '';
    FOR i IN 1..5 LOOP
      idx := 1 + (get_byte(gen_random_bytes(1), 0) % length(alphabet));
      body := body || substr(alphabet, idx, 1);
    END LOOP;

    has_letter := body ~ '[A-Z]';
    has_digit := body ~ '[2-9]';
    IF has_letter AND has_digit THEN
      RETURN upper(p_prefix) || '-' || body;
    END IF;
  END LOOP;
END;
$function$

CREATE OR REPLACE FUNCTION public.generate_session_invite_token()
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  candidate TEXT;
  attempt INT := 0;
BEGIN
  LOOP
    attempt := attempt + 1;
    IF attempt > 16 THEN
      RAISE EXCEPTION 'session invite token collision retries exhausted' USING ERRCODE = 'P0001';
    END IF;
    candidate := replace(gen_random_uuid()::text || gen_random_uuid()::text, '-', '');
    EXIT WHEN NOT EXISTS (
      SELECT 1 FROM public.session_invites i WHERE i.token = candidate
    );
  END LOOP;
  RETURN candidate;
END;
$function$

CREATE OR REPLACE FUNCTION public.generate_unique_session_code()
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  alphabet TEXT := 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
  candidate TEXT; attempt INT := 0; i INT;
BEGIN
  LOOP
    attempt := attempt + 1;
    IF attempt > 32 THEN
      RAISE EXCEPTION 'session code collision retries exhausted' USING ERRCODE = 'P0001';
    END IF;
    candidate := '';
    FOR i IN 1..6 LOOP
      candidate := candidate || substr(alphabet, 1 + floor(random() * length(alphabet))::INT, 1);
    END LOOP;
    EXIT WHEN NOT EXISTS (
      SELECT 1 FROM public.sessions s WHERE s.code IS NOT NULL AND UPPER(BTRIM(s.code)) = candidate
    );
  END LOOP;
  RETURN candidate;
END;
$function$

CREATE OR REPLACE FUNCTION public.get_my_saga_permissions(p_public_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_project_id UUID;
  v_uid UUID := auth.uid();
  v_bundle TEXT;
  v_keys JSONB;
  v_is_gm BOOLEAN;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'not authenticated';
  END IF;

  SELECT id INTO v_project_id
  FROM public.projects
  WHERE public_id = UPPER(BTRIM(p_public_id));

  IF v_project_id IS NULL THEN
    RAISE EXCEPTION 'saga not found';
  END IF;

  v_is_gm := public.is_project_gm(v_project_id, v_uid);

  IF NOT public.current_user_is_active_project_member(v_project_id) AND NOT v_is_gm THEN
    RAISE EXCEPTION 'not a member';
  END IF;

  SELECT b.bundle_id INTO v_bundle
  FROM public.project_member_saga_bundles b
  WHERE b.project_id = v_project_id AND b.user_id = v_uid;

  IF v_is_gm THEN
    SELECT COALESCE(jsonb_agg(k.key ORDER BY k.key), '[]'::jsonb) INTO v_keys
    FROM public.saga_permission_keys k;
    v_bundle := COALESCE(v_bundle, 'bundle.saga.gm');
  ELSE
    SELECT COALESCE(jsonb_agg(g.permission_key ORDER BY g.permission_key), '[]'::jsonb) INTO v_keys
    FROM public.project_member_saga_grants g
    WHERE g.project_id = v_project_id AND g.user_id = v_uid;
  END IF;

  RETURN jsonb_build_object(
    'projectId', v_project_id,
    'bundleId', v_bundle,
    'isGm', v_is_gm,
    'keys', COALESCE(v_keys, '[]'::jsonb)
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.get_saga_definition_editor(p_saga_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user UUID := auth.uid();
  v_def public.saga_definitions%ROWTYPE;
  v_ver public.saga_definition_versions%ROWTYPE;
  v_can_edit BOOLEAN := false;
BEGIN
  IF v_user IS NULL THEN
    RAISE EXCEPTION 'not authenticated' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO v_def FROM public.saga_definitions WHERE id = p_saga_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Saga-Definition nicht gefunden' USING ERRCODE = 'P0002';
  END IF;

  IF v_def.origin = 'native' THEN
    SELECT * INTO v_ver
    FROM public.saga_definition_versions
    WHERE saga_id = v_def.id AND status = 'published'
    ORDER BY published_at DESC NULLS LAST, created_at DESC
    LIMIT 1;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'Native Fassung fehlt' USING ERRCODE = 'P0002';
    END IF;
    v_can_edit := false;
  ELSIF v_def.owner_user_id = v_user THEN
    v_ver := public.sagatree_ensure_saga_draft(v_def.id);
    v_can_edit := true;
  ELSE
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  RETURN jsonb_build_object(
    'sagaId', v_def.id,
    'sagaSlug', v_def.slug,
    'title', v_def.title,
    'synopsis', v_def.synopsis,
    'origin', v_def.origin,
    'versionId', v_ver.id,
    'versionLabel', v_ver.version_label,
    'status', v_ver.status,
    'payload', v_ver.payload,
    'revision', v_def.draft_revision,
    'canEdit', v_can_edit,
    'isGmProjection', true
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.get_saga_definition_version(p_version_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user UUID := auth.uid();
  v_ver public.saga_definition_versions%ROWTYPE;
  v_def public.saga_definitions%ROWTYPE;
  v_is_gm BOOLEAN := false;
  v_member BOOLEAN := false;
BEGIN
  IF v_user IS NULL THEN
    RAISE EXCEPTION 'not authenticated' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO v_ver FROM public.saga_definition_versions WHERE id = p_version_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Saga-Fassung nicht gefunden' USING ERRCODE = 'P0002';
  END IF;
  SELECT * INTO v_def FROM public.saga_definitions WHERE id = v_ver.saga_id;

  -- Access: native published readable to any authenticated; else owner or project member on that saga.
  IF v_def.origin = 'native' AND v_ver.status = 'published' THEN
    v_member := true;
  ELSIF v_def.owner_user_id = v_user THEN
    v_member := true;
    v_is_gm := true;
  ELSE
    SELECT EXISTS (
      SELECT 1 FROM public.projects p
      WHERE p.saga_id = v_def.id
        AND (
          p.gm_user_id = v_user
          OR public.current_user_is_active_project_member(p.id)
        )
    ) INTO v_member;
    SELECT EXISTS (
      SELECT 1 FROM public.projects p WHERE p.saga_id = v_def.id AND p.gm_user_id = v_user
    ) INTO v_is_gm;
  END IF;

  IF NOT v_member THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  -- Native: treat requester as GM only if they GM a project on this saga (else player projection).
  IF v_def.origin = 'native' THEN
    SELECT EXISTS (
      SELECT 1 FROM public.projects p WHERE p.saga_id = v_def.id AND p.gm_user_id = v_user
    ) INTO v_is_gm;
  END IF;

  RETURN jsonb_build_object(
    'sagaId', v_def.id,
    'sagaSlug', v_def.slug,
    'title', v_def.title,
    'synopsis', v_def.synopsis,
    'origin', v_def.origin,
    'versionId', v_ver.id,
    'versionLabel', v_ver.version_label,
    'status', v_ver.status,
    'payload', public.sagatree_project_saga_definition_payload(v_ver.payload, v_is_gm),
    'isGmProjection', v_is_gm
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.get_saga_lore_timeline(p_public_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_project RECORD;
  v_uid UUID := auth.uid();
  v_is_gm BOOLEAN;
  v_can_hidden BOOLEAN;
  v_entries JSONB := '[]'::jsonb;
  v_payload JSONB;
  v_elem JSONB;
  v_vis TEXT;
  v_recap RECORD;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'not authenticated';
  END IF;

  SELECT p.id, p.saga_id, p.saga_version_id
  INTO v_project
  FROM public.projects p
  WHERE p.public_id = UPPER(BTRIM(p_public_id));

  IF v_project.id IS NULL THEN
    RAISE EXCEPTION 'saga not found';
  END IF;

  IF NOT public.current_user_is_active_project_member(v_project.id)
     AND NOT public.is_project_gm(v_project.id, v_uid) THEN
    RAISE EXCEPTION 'not a member';
  END IF;

  IF NOT public.has_saga_permission(v_project.id, 'saga.lore.read')
     AND NOT public.is_project_gm(v_project.id, v_uid) THEN
    RAISE EXCEPTION 'missing saga.lore.read';
  END IF;

  v_is_gm := public.is_project_gm(v_project.id, v_uid);
  v_can_hidden := v_is_gm
    OR public.has_saga_permission(v_project.id, 'saga.lore.read_hidden')
    OR public.has_saga_permission(v_project.id, 'saga.secrets.read');

  -- Episode recaps (sessions of this project).
  FOR v_recap IN
    SELECT s.public_id AS session_public_id, s.name AS session_name, s.session_number,
           r.summary_text, r.highlight_lines, r.updated_at
    FROM public.sessions s
    JOIN public.session_recaps r ON r.session_id = s.id
    WHERE s.project_id = v_project.id
    ORDER BY COALESCE(s.session_number, 0) DESC, r.updated_at DESC
    LIMIT 40
  LOOP
    v_entries := v_entries || jsonb_build_array(
      jsonb_build_object(
        'id', 'recap:' || COALESCE(v_recap.session_public_id, ''),
        'kind', 'recap',
        'title', COALESCE(v_recap.session_name, 'Episode'),
        'summary', COALESCE(v_recap.summary_text, ''),
        'visibility', 'shared',
        'occurredAt', v_recap.updated_at,
        'meta', jsonb_build_object(
          'sessionPublicId', v_recap.session_public_id,
          'sessionNumber', v_recap.session_number,
          'highlightLines', COALESCE(v_recap.highlight_lines, '[]'::jsonb)
        )
      )
    );
  END LOOP;

  -- Definition knowledge facts (if saga linked).
  IF v_project.saga_version_id IS NOT NULL THEN
    SELECT payload INTO v_payload
    FROM public.saga_definition_versions
    WHERE id = v_project.saga_version_id;

    FOR v_elem IN
      SELECT elem
      FROM jsonb_array_elements(COALESCE(v_payload->'knowledgeFacts', '[]'::jsonb)) AS elem
    LOOP
      v_vis := COALESCE(v_elem->>'visibility', 'gm_only');
      IF v_can_hidden OR v_vis IN ('public', 'shared', 'discovered') THEN
        v_entries := v_entries || jsonb_build_array(
          jsonb_build_object(
            'id', 'fact:' || COALESCE(v_elem->>'id', md5(v_elem::text)),
            'kind', 'knowledge',
            'title', COALESCE(v_elem->>'id', 'Wissen'),
            'summary', COALESCE(v_elem->>'summary', ''),
            'visibility', v_vis,
            'occurredAt', NULL,
            'meta', '{}'::jsonb
          )
        );
      END IF;
    END LOOP;
  END IF;

  -- Bound lore assets revealed to viewer.
  v_entries := v_entries || COALESCE((
    SELECT jsonb_agg(
      jsonb_build_object(
        'id', 'binding:' || b.id::text,
        'kind', 'lore_binding',
        'title', NULLIF(BTRIM(b.label), ''),
        'summary', COALESCE(b.metadata->>'summary', ''),
        'visibility', b.reveal,
        'occurredAt', b.updated_at,
        'meta', jsonb_build_object('bindingId', b.id, 'reveal', b.reveal)
      )
    )
    FROM public.saga_asset_bindings b
    WHERE b.project_id = v_project.id
      AND b.asset_kind = 'lore'
      AND public.can_view_saga_binding(b.project_id, b.reveal, b.asset_kind)
      AND b.reveal <> 'unlisted'
  ), '[]'::jsonb);

  RETURN jsonb_build_object(
    'projectId', v_project.id,
    'canReadHidden', v_can_hidden,
    'entries', COALESCE(v_entries, '[]'::jsonb)
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.get_saga_overview(p_public_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user UUID := auth.uid();
  v_project public.projects%ROWTYPE;
  v_is_gm BOOLEAN := false;
  v_is_member BOOLEAN := false;
  v_role TEXT := 'viewer';
  v_shared JSONB;
  v_projected JSONB;
  v_adv JSONB;
  v_episodes JSONB := '[]'::jsonb;
  v_ensemble JSONB := '[]'::jsonb;
  v_clocks JSONB := '[]'::jsonb;
  v_consequences JSONB := '[]'::jsonb;
  v_open_deadlines JSONB := '[]'::jsonb;
  v_open_sessions INT := 0;
  v_latest_session JSONB := NULL;
  v_primary JSONB;
  v_key TEXT;
  v_entry JSONB;
  v_cons_cap INT := 20;
  v_saga_def_id UUID := NULL;
  v_saga_ver_id UUID := NULL;
  v_version_label TEXT := NULL;
  v_newer BOOLEAN := false;
BEGIN
  IF v_user IS NULL THEN
    RAISE EXCEPTION 'not authenticated' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO v_project
  FROM public.projects
  WHERE public_id = UPPER(BTRIM(COALESCE(p_public_id, '')));

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Saga not found' USING ERRCODE = 'P0002';
  END IF;

  v_is_gm := public.is_project_gm(v_project.id, v_user);
  v_is_member := public.current_user_is_active_project_member(v_project.id);

  IF NOT v_is_gm AND NOT v_is_member THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  IF v_is_gm THEN
    v_role := 'gamemaster';
  ELSE
    SELECT COALESCE(pm.role, 'player') INTO v_role
    FROM public.project_members pm
    WHERE pm.project_id = v_project.id
      AND pm.user_id = v_user
      AND pm.status = 'active'
    LIMIT 1;
    IF v_role = 'gm' THEN
      v_role := 'gamemaster';
    ELSIF v_role = 'observer' THEN
      v_role := 'viewer';
    ELSIF v_role IS NULL OR v_role = '' THEN
      v_role := 'player';
    END IF;
  END IF;


  v_saga_def_id := v_project.saga_id;
  v_saga_ver_id := v_project.saga_version_id;
  IF v_saga_ver_id IS NOT NULL THEN
    SELECT version_label INTO v_version_label
    FROM public.saga_definition_versions WHERE id = v_saga_ver_id;
    SELECT EXISTS (
      SELECT 1 FROM public.saga_definition_versions nv
      WHERE nv.saga_id = v_saga_def_id
        AND nv.status = 'published'
        AND nv.id IS DISTINCT FROM v_saga_ver_id
        AND COALESCE(nv.published_at, nv.created_at) > COALESCE(
          (SELECT published_at FROM public.saga_definition_versions WHERE id = v_saga_ver_id),
          '-infinity'::timestamptz
        )
    ) INTO v_newer;
  END IF;

  v_shared := jsonb_build_object(
    'adventure',
    COALESCE(v_project.adventure_runtime, '{}'::jsonb)
  );
  v_projected := public.sagatree_project_shared_adventure(v_shared, v_is_gm);
  v_adv := COALESCE(v_projected->'adventure', '{}'::jsonb);

  FOR v_key, v_entry IN SELECT * FROM jsonb_each(COALESCE(v_adv->'clocks', '{}'::jsonb))
  LOOP
    v_clocks := v_clocks || jsonb_build_array(
      jsonb_build_object(
        'id', COALESCE(v_entry->>'id', v_key),
        'label', COALESCE(v_entry->>'label', v_key),
        'value', COALESCE((v_entry->>'value')::INT, 0),
        'max', COALESCE((v_entry->>'max')::INT, 1),
        'visibility', COALESCE(v_entry->>'visibility', 'shared')
      )
    );
  END LOOP;

  SELECT COALESCE(jsonb_agg(elem ORDER BY ord), '[]'::jsonb)
    INTO v_consequences
    FROM (
      SELECT elem, ord
      FROM (
        SELECT
          elem,
          ROW_NUMBER() OVER (
            ORDER BY COALESCE(elem->>'createdAt', '') DESC
          ) AS ord
        FROM jsonb_array_elements(COALESCE(v_adv->'consequences', '[]'::jsonb)) AS elem
      ) ranked
      WHERE ord <= v_cons_cap
    ) capped;

  SELECT COALESCE(
    jsonb_agg(
      jsonb_build_object(
        'id', COALESCE(elem->>'id', ''),
        'label', COALESCE(elem->>'label', elem->>'id', 'Frist'),
        'dueDay', COALESCE((elem->>'dueDay')::INT, 0),
        'visibility', COALESCE(elem->>'visibility', 'shared')
      )
      ORDER BY COALESCE((elem->>'dueDay')::INT, 999999) ASC
    ),
    '[]'::jsonb
  )
  INTO v_open_deadlines
  FROM (
    SELECT elem
    FROM jsonb_array_elements(COALESCE(v_adv->'deadlines', '[]'::jsonb)) AS elem
    WHERE COALESCE((elem->>'fired')::boolean, false) IS NOT TRUE
      AND (
        v_is_gm
        OR COALESCE(elem->>'visibility', 'shared') IN ('public', 'shared')
      )
    ORDER BY COALESCE((elem->>'dueDay')::INT, 999999) ASC
    LIMIT 32
  ) open_dl;

  SELECT COALESCE(
    jsonb_agg(
      jsonb_build_object(
        'sessionId', s.id,
        'sessionPublicId', s.public_id,
        'sessionNumber', s.session_number,
        'name', s.name,
        'status', s.status,
        'startedAt', s.started_at,
        'endedAt', s.ended_at,
        'recapSnippet', COALESCE(
          CASE
            WHEN v_is_gm OR COALESCE(sr.summary_status, 'none') = 'approved' THEN
              NULLIF(BTRIM(COALESCE(sr.summary_text, '')), '')
            ELSE NULL
          END,
          (
            SELECT elem->>'summary'
            FROM jsonb_array_elements(
              public.sagatree_build_recap_highlight_lines(
                COALESCE(sr.snapshot, '{}'::jsonb),
                v_is_gm
              )
            ) AS elem
            LIMIT 1
          )
        )
      )
      ORDER BY s.session_number ASC
    ),
    '[]'::jsonb
  )
  INTO v_episodes
  FROM public.sessions s
  LEFT JOIN public.session_recaps sr ON sr.session_id = s.id
  WHERE s.project_id = v_project.id;

  SELECT COUNT(*)::INT INTO v_open_sessions
  FROM public.sessions s
  WHERE s.project_id = v_project.id
    AND s.status IN ('scheduled', 'active', 'paused');

  SELECT jsonb_build_object(
    'sessionPublicId', s.public_id,
    'sessionNumber', s.session_number,
    'status', s.status,
    'name', s.name
  )
  INTO v_latest_session
  FROM public.sessions s
  WHERE s.project_id = v_project.id
  ORDER BY s.session_number DESC
  LIMIT 1;

  SELECT COALESCE(
    jsonb_agg(
      jsonb_build_object(
        'userId', pm.user_id,
        'role', CASE
          WHEN pm.role = 'gm' THEN 'gamemaster'
          WHEN pm.role = 'observer' THEN 'viewer'
          ELSE pm.role
        END,
        'characterId', pm.character_id,
        'characterName', c.name,
        'isSelf', pm.user_id = v_user
      )
      ORDER BY pm.joined_at ASC
    ),
    '[]'::jsonb
  )
  INTO v_ensemble
  FROM public.project_members pm
  LEFT JOIN public.characters c ON c.id = pm.character_id
  WHERE pm.project_id = v_project.id
    AND pm.status = 'active';

  IF v_role = 'gamemaster' THEN
    IF v_open_sessions > 0 AND v_latest_session IS NOT NULL
       AND (v_latest_session->>'status') IN ('scheduled', 'active', 'paused') THEN
      v_primary := jsonb_build_object(
        'kind', 'continue-session',
        'labelDe', 'Session fortsetzen',
        'sessionPublicId', v_latest_session->>'sessionPublicId'
      );
    ELSE
      v_primary := jsonb_build_object(
        'kind', 'host-session',
        'labelDe', 'Session hosten',
        'sessionPublicId', NULL
      );
    END IF;
  ELSIF v_role = 'viewer' THEN
    IF v_open_sessions > 0 AND v_latest_session IS NOT NULL THEN
      v_primary := jsonb_build_object(
        'kind', 'join-session',
        'labelDe', 'Session beobachten',
        'sessionPublicId', v_latest_session->>'sessionPublicId'
      );
    ELSE
      v_primary := jsonb_build_object(
        'kind', 'wait',
        'labelDe', 'Warten auf Einladung',
        'sessionPublicId', NULL
      );
    END IF;
  ELSE
    IF v_open_sessions > 0 AND v_latest_session IS NOT NULL THEN
      v_primary := jsonb_build_object(
        'kind', 'join-session',
        'labelDe', 'Zur Session',
        'sessionPublicId', v_latest_session->>'sessionPublicId'
      );
    ELSE
      v_primary := jsonb_build_object(
        'kind', 'wait',
        'labelDe', 'Warten auf Einladung',
        'sessionPublicId', NULL
      );
    END IF;
  END IF;

  RETURN jsonb_build_object(
    'projectId', v_project.id,
    'sagaPublicId', v_project.public_id,
    'title', v_project.name,
    'blurb', COALESCE(v_project.description, ''),
    'status', v_project.status,
    'selfRole', v_role,
    'isGm', v_is_gm,
    'definitionRef', v_adv->>'definitionRef',
    'sagaDefinitionId', v_saga_def_id,
    'sagaVersionId', v_saga_ver_id,
    'versionLabel', v_version_label,
    'newerVersionAvailable', v_newer,
    'primaryAction', v_primary,
    'episodes', v_episodes,
    'ensemble', v_ensemble,
    'worldProfileId', v_project.world_profile_id,
    'worldStateSummary', jsonb_build_object(
      'clocks', v_clocks,
      'consequences', v_consequences,
      'openDeadlines', v_open_deadlines,
      'partyLocationRef', NULLIF(BTRIM(COALESCE(v_adv->>'partyLocationRef', '')), ''),
      'flagCount', public.jsonb_object_keys_count(v_adv->'flags'),
      'updatedAt', v_adv->>'updatedAt'
    )
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.get_session_recap(p_session_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user UUID := auth.uid();
  v_session public.sessions%ROWTYPE;
  v_is_gm BOOLEAN;
  v_recap public.session_recaps%ROWTYPE;
  v_lines JSONB;
  v_adv JSONB;
  v_summary TEXT;
  v_status TEXT;
BEGIN
  IF v_user IS NULL THEN
    RAISE EXCEPTION 'not authenticated' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO v_session FROM public.sessions WHERE id = p_session_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Session not found' USING ERRCODE = 'P0002';
  END IF;

  IF NOT public.is_session_participant(p_session_id, v_user) THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  v_is_gm := public.is_project_gm(v_session.project_id, v_user);

  SELECT * INTO v_recap FROM public.session_recaps WHERE session_id = p_session_id;
  IF NOT FOUND THEN
    RETURN NULL;
  END IF;

  v_adv := COALESCE(v_recap.snapshot, '{}'::jsonb);
  v_lines := public.sagatree_build_recap_highlight_lines(v_adv, v_is_gm);
  v_status := COALESCE(v_recap.summary_status, 'none');
  v_summary := v_recap.summary_text;

  IF NOT v_is_gm AND v_status IS DISTINCT FROM 'approved' THEN
    v_summary := NULL;
  END IF;

  RETURN jsonb_build_object(
    'sessionId', v_recap.session_id,
    'summaryText', v_summary,
    'summaryStatus', v_status,
    'highlightLines', v_lines,
    'createdAt', v_recap.created_at,
    'updatedAt', v_recap.updated_at
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.get_session_runtime_snapshot(p_session_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  actor UUID := auth.uid();
  v_session public.sessions;
  v_roster JSONB;
  v_shared JSONB;
  v_is_gm BOOLEAN;
  v_character_id UUID;
BEGIN
  IF actor IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE = '42501';
  END IF;
  IF p_session_id IS NULL THEN
    RAISE EXCEPTION 'session_id required' USING ERRCODE = '22023';
  END IF;
  IF NOT public.is_session_participant(p_session_id, actor) THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO v_session FROM public.sessions WHERE id = p_session_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Session not found' USING ERRCODE = 'P0002';
  END IF;

  v_is_gm := public.is_project_gm(v_session.project_id, actor);
  SELECT sp.character_id INTO v_character_id
  FROM public.session_players sp
  WHERE sp.session_id = p_session_id AND sp.user_id = actor
  LIMIT 1;

  SELECT COALESCE(jsonb_agg(
    jsonb_build_object(
      'userId', sp.user_id,
      'characterId', sp.character_id,
      'isOnline', sp.is_online,
      'joinedAt', sp.joined_at
    )
    ORDER BY sp.joined_at
  ), '[]'::jsonb)
  INTO v_roster
  FROM public.session_players sp
  WHERE sp.session_id = p_session_id;

  v_shared := public.sagatree_project_shared_knowledge(
    COALESCE(v_session.world_state->'shared', '{}'::jsonb),
    v_is_gm,
    v_character_id
  );
  v_shared := public.sagatree_project_shared_adventure(v_shared, v_is_gm);

  RETURN jsonb_build_object(
    'sessionId', v_session.id,
    'revision', v_session.runtime_revision,
    'status', CASE WHEN v_session.status = 'scheduled' THEN 'waiting' ELSE v_session.status END,
    'roster', v_roster,
    'gameplay', jsonb_build_object(
      'sceneId', COALESCE(v_session.world_state->>'sceneId', v_session.world_state->>'scene_id'),
      'combatActive', COALESCE(
        (v_session.world_state->>'combatActive')::boolean,
        (v_session.world_state->>'combat_active')::boolean,
        false
      ),
      'shared', v_shared
    ),
    'updatedAt', v_session.updated_at
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.get_world_atlas_map(p_map_id uuid, p_player_view boolean DEFAULT false, p_saga_public_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user UUID := auth.uid();
  v_row public.world_atlas_maps%ROWTYPE;
  v_layers JSONB;
  v_meta JSONB;
  v_can_edit BOOLEAN;
  v_party_only BOOLEAN;
  v_project UUID;
  v_allowed UUID[];
  v_parent UUID;
BEGIN
  IF v_user IS NULL THEN
    RAISE EXCEPTION 'not authenticated' USING ERRCODE = '42501';
  END IF;
  IF p_map_id IS NULL THEN
    RAISE EXCEPTION 'map_id required' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_row FROM public.world_atlas_maps WHERE id = p_map_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'not found' USING ERRCODE = 'P0002';
  END IF;
  IF NOT public.current_user_can_read_world_profile(v_row.world_profile_id) THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  v_can_edit := public.current_user_can_edit_world_profile(v_row.world_profile_id);
  v_party_only := (NOT v_can_edit) OR (p_player_view IS TRUE);

  IF v_party_only THEN
    IF p_saga_public_id IS NOT NULL AND btrim(p_saga_public_id) <> '' THEN
      v_project := public.atlas_wb_resolve_saga_project(v_row.world_profile_id, p_saga_public_id);
    END IF;
    IF v_project IS NULL THEN
      RAISE EXCEPTION 'not found' USING ERRCODE = 'P0002';
    END IF;
    v_allowed := public.atlas_wb_party_revealed_map_ids(v_row.world_profile_id, v_project);
    IF NOT (p_map_id = ANY (v_allowed)) THEN
      RAISE EXCEPTION 'not found' USING ERRCODE = 'P0002';
    END IF;
  END IF;

  v_layers := COALESCE(v_row.layers, '{"type":"FeatureCollection","features":[]}'::jsonb);
  v_meta := COALESCE(v_row.generator_meta, '{}'::jsonb);
  v_parent := v_row.parent_map_id;

  IF v_party_only THEN
    SELECT jsonb_build_object(
      'type', 'FeatureCollection',
      'features', COALESCE(jsonb_agg(f.feat), '[]'::jsonb)
    )
    INTO v_layers
    FROM jsonb_array_elements(COALESCE(v_layers->'features', '[]'::jsonb)) AS f(feat)
    WHERE COALESCE((f.feat->'properties'->>'secret')::boolean, false) IS NOT TRUE
      AND (
        (f.feat->'properties'->>'discovered') IS NULL
        OR COALESCE((f.feat->'properties'->>'discovered')::boolean, true) IS TRUE
      );

    v_meta := jsonb_build_object(
      'engine', COALESCE(v_meta->>'engine', 'unified_canvas')
    );

    IF v_parent IS NOT NULL AND NOT (v_parent = ANY (v_allowed)) THEN
      v_parent := NULL;
    END IF;
  END IF;

  RETURN jsonb_build_object(
    'id', v_row.id,
    'worldProfileId', v_row.world_profile_id,
    'parentMapId', v_parent,
    'kind', v_row.kind,
    'title', v_row.title,
    'sortOrder', v_row.sort_order,
    'bounds', v_row.bounds,
    'layers', v_layers,
    'basemapStoragePath', CASE
      WHEN v_party_only THEN v_row.basemap_storage_path
      ELSE v_row.basemap_storage_path
    END,
    'azgaarMapStoragePath', CASE
      WHEN v_party_only THEN NULL
      ELSE v_row.azgaar_map_storage_path
    END,
    'generatorMeta', v_meta,
    'revision', v_row.revision,
    'updatedAt', v_row.updated_at
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.get_world_map(p_world_profile_id uuid, p_player_view boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user UUID := auth.uid();
  v_row public.world_maps%ROWTYPE;
  v_data JSONB;
  v_pins JSONB;
BEGIN
  IF v_user IS NULL THEN
    RAISE EXCEPTION 'not authenticated' USING ERRCODE = '42501';
  END IF;
  IF p_world_profile_id IS NULL THEN
    RAISE EXCEPTION 'world_profile_id required' USING ERRCODE = '22023';
  END IF;
  IF NOT public.current_user_can_read_world_profile(p_world_profile_id) THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO v_row FROM public.world_maps WHERE world_profile_id = p_world_profile_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'worldProfileId', p_world_profile_id,
      'revision', 0,
      'mapData', jsonb_build_object(
        'size', 24,
        'tiles', '{}'::jsonb,
        'countries', '[]'::jsonb,
        'pins', '[]'::jsonb
      ),
      'updatedAt', NULL
    );
  END IF;

  v_data := COALESCE(v_row.map_data, '{}'::jsonb);
  IF p_player_view THEN
    SELECT COALESCE(jsonb_agg(elem), '[]'::jsonb)
      INTO v_pins
      FROM jsonb_array_elements(COALESCE(v_data->'pins', '[]'::jsonb)) AS elem
     WHERE COALESCE((elem->>'discovered')::boolean, true) IS TRUE;
    v_data := jsonb_set(v_data, '{pins}', v_pins, true);
  END IF;

  RETURN jsonb_build_object(
    'worldProfileId', v_row.world_profile_id,
    'revision', v_row.revision,
    'mapData', v_data,
    'updatedAt', v_row.updated_at
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.guard_character_avatar_artifact_escalation()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF auth.role() = 'authenticated' THEN
    IF NEW.origin IS DISTINCT FROM OLD.origin THEN
      RAISE EXCEPTION 'avatar artifact origin is immutable for clients';
    END IF;
    IF NEW.asset_key IS DISTINCT FROM OLD.asset_key THEN
      RAISE EXCEPTION 'avatar artifact asset_key is immutable for clients';
    END IF;
    IF NEW.owner_user_id IS DISTINCT FROM OLD.owner_user_id THEN
      RAISE EXCEPTION 'avatar artifact owner is immutable';
    END IF;
    IF NEW.analysis_status IS DISTINCT FROM OLD.analysis_status
       AND NEW.analysis_status NOT IN ('pending', 'failed') THEN
      RAISE EXCEPTION 'avatar artifact analysis_status escalation forbidden';
    END IF;
    IF NEW.analysis_status IN ('ready', 'limited', 'analyzing', 'unsupported')
       AND NEW.analysis_status IS DISTINCT FROM OLD.analysis_status THEN
      RAISE EXCEPTION 'avatar artifact trusted analysis statuses are server-only';
    END IF;
    IF NEW.is_active = true AND NEW.materialization_status <> 'materialized' THEN
      RAISE EXCEPTION 'incomplete avatar artifact cannot be activated';
    END IF;
    IF NEW.is_active = true AND NEW.analysis_status = 'failed' THEN
      RAISE EXCEPTION 'failed avatar artifact cannot be activated';
    END IF;
    -- analysis_result: clients may only null it out, never inject authoritative=true
    IF NEW.analysis_result IS DISTINCT FROM OLD.analysis_result
       AND NEW.analysis_result IS NOT NULL THEN
      IF COALESCE((NEW.analysis_result->>'authoritative')::boolean, false) = true THEN
        RAISE EXCEPTION 'client cannot persist authoritative analysis_result';
      END IF;
      IF COALESCE(NEW.analysis_result->>'status', '') IN ('ready', 'limited') THEN
        RAISE EXCEPTION 'client cannot persist trusted analysis_result status';
      END IF;
    END IF;
  END IF;
  NEW.updated_at = NOW();
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.handle_new_user_dornhain_starter()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  BEGIN
    PERFORM public.provision_dornhain_starter_for_user(NEW.id);
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'dornhain starter provision failed for %: %', NEW.id, SQLERRM;
  END;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.handle_new_user_profile()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  meta_name TEXT;
BEGIN
  meta_name := NULLIF(
    trim(
      coalesce(
        NEW.raw_user_meta_data ->> 'display_name',
        NEW.raw_user_meta_data ->> 'username',
        split_part(coalesce(NEW.email, ''), '@', 1)
      )
    ),
    ''
  );

  INSERT INTO public.user_profiles (id, display_name)
  VALUES (NEW.id, meta_name)
  ON CONFLICT (id) DO NOTHING;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.join_project_by_code(p_code text, p_character_id uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_user_id UUID := auth.uid();
  v_project_id UUID;
  v_existing_status TEXT;
  v_sheet_status TEXT;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE = '42501';
  END IF;

  IF NULLIF(BTRIM(p_code), '') IS NULL THEN
    RAISE EXCEPTION 'Project code is required' USING ERRCODE = '22023';
  END IF;

  SELECT id
  INTO v_project_id
  FROM public.projects
  WHERE UPPER(BTRIM(code)) = UPPER(BTRIM(p_code))
    AND status = 'active';

  IF v_project_id IS NULL THEN
    RAISE EXCEPTION 'Project not found' USING ERRCODE = 'P0002';
  END IF;

  SELECT status
  INTO v_existing_status
  FROM public.project_members
  WHERE project_id = v_project_id
    AND user_id = v_user_id;

  IF FOUND THEN
    RAISE EXCEPTION 'Project membership already exists with status %', v_existing_status
      USING ERRCODE = 'P0001';
  END IF;

  IF p_character_id IS NOT NULL THEN
    SELECT sheet_status
    INTO v_sheet_status
    FROM public.characters
    WHERE id = p_character_id
      AND owner_user_id = v_user_id
      AND character_type = 'pc';

    IF NOT FOUND THEN
      RAISE EXCEPTION 'Character is not owned by the current user' USING ERRCODE = '42501';
    END IF;

    IF COALESCE(v_sheet_status, 'complete') <> 'complete' THEN
      RAISE EXCEPTION 'Unvollständige Charakterbögen können keinem Abenteuer beitreten'
        USING ERRCODE = '22023';
    END IF;
  END IF;

  INSERT INTO public.project_members (
    project_id,
    user_id,
    character_id,
    role,
    status
  ) VALUES (
    v_project_id,
    v_user_id,
    p_character_id,
    'player',
    'active'
  );

  RETURN v_project_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.join_session_by_code(p_code text, p_character_id uuid DEFAULT NULL::uuid)
 RETURNS sessions
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  actor UUID := auth.uid();
  v_session public.sessions;
  v_sheet_status TEXT;
  v_revision BIGINT;
BEGIN
  IF actor IS NULL THEN RAISE EXCEPTION 'Authentication required' USING ERRCODE = '42501'; END IF;
  IF NULLIF(BTRIM(p_code), '') IS NULL THEN RAISE EXCEPTION 'Session code is required' USING ERRCODE = '22023'; END IF;
  SELECT * INTO v_session FROM public.sessions
   WHERE code IS NOT NULL AND UPPER(BTRIM(code)) = UPPER(BTRIM(p_code)) LIMIT 1 FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Session not found' USING ERRCODE = 'P0002'; END IF;
  IF v_session.status = 'completed' THEN RAISE EXCEPTION 'Session is completed' USING ERRCODE = '22023'; END IF;
  IF p_character_id IS NOT NULL THEN
    SELECT sheet_status INTO v_sheet_status FROM public.characters
     WHERE id = p_character_id AND owner_user_id = actor AND character_type = 'pc';
    IF NOT FOUND THEN RAISE EXCEPTION 'Character is not owned by the current user' USING ERRCODE = '42501'; END IF;
    IF COALESCE(v_sheet_status, 'complete') <> 'complete' THEN
      RAISE EXCEPTION 'Unvollständige Charakterbögen können keiner Session beitreten' USING ERRCODE = '22023';
    END IF;
  END IF;
  PERFORM public.ensure_active_project_player(v_session.project_id, actor, p_character_id);
  INSERT INTO public.session_players (session_id, user_id, character_id, is_online)
  VALUES (v_session.id, actor, p_character_id, true)
  ON CONFLICT (session_id, user_id) DO UPDATE
    SET character_id = COALESCE(EXCLUDED.character_id, public.session_players.character_id),
        is_online = true, left_at = NULL;

  v_revision := COALESCE(v_session.runtime_revision, 0) + 1;
  UPDATE public.sessions
     SET runtime_revision = v_revision, updated_at = NOW()
   WHERE id = v_session.id
  RETURNING * INTO v_session;

  PERFORM public.append_session_event(
    v_session.id,
    'join',
    actor,
    jsonb_build_object('characterId', p_character_id),
    v_revision,
    NULL
  );

  RETURN v_session;
END;
$function$

CREATE OR REPLACE FUNCTION public.leave_play_session(p_session_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  actor UUID := auth.uid();
  v_session public.sessions;
  v_revision BIGINT;
BEGIN
  IF actor IS NULL THEN RAISE EXCEPTION 'Authentication required' USING ERRCODE = '42501'; END IF;
  SELECT * INTO v_session FROM public.sessions WHERE id = p_session_id FOR UPDATE;
  IF FOUND THEN
    DELETE FROM public.session_players WHERE session_id = p_session_id AND user_id = actor;
    v_revision := COALESCE(v_session.runtime_revision, 0) + 1;
    UPDATE public.sessions
       SET runtime_revision = v_revision, updated_at = NOW()
     WHERE id = p_session_id;
    PERFORM public.append_session_event(
      p_session_id,
      'leave',
      actor,
      '{}'::jsonb,
      v_revision,
      NULL
    );
  ELSE
    DELETE FROM public.session_players WHERE session_id = p_session_id AND user_id = actor;
  END IF;
END;
$function$

CREATE OR REPLACE FUNCTION public.list_saga_bindings(p_public_id text, p_asset_kind text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_project_id UUID;
  v_uid UUID := auth.uid();
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'not authenticated';
  END IF;

  SELECT id INTO v_project_id
  FROM public.projects
  WHERE public_id = UPPER(BTRIM(p_public_id));

  IF v_project_id IS NULL THEN
    RAISE EXCEPTION 'saga not found';
  END IF;

  IF NOT public.current_user_is_active_project_member(v_project_id)
     AND NOT public.is_project_gm(v_project_id, v_uid) THEN
    RAISE EXCEPTION 'not a member';
  END IF;

  RETURN COALESCE((
    SELECT jsonb_agg(
      jsonb_build_object(
        'id', b.id,
        'assetKind', b.asset_kind,
        'assetId', b.asset_id,
        'reveal', b.reveal,
        'label', b.label,
        'metadata', b.metadata,
        'worldPlaceId', b.world_place_id
      )
      ORDER BY b.asset_kind, b.label, b.asset_id
    )
    FROM public.saga_asset_bindings b
    WHERE b.project_id = v_project_id
      AND (p_asset_kind IS NULL OR b.asset_kind = p_asset_kind)
      AND public.can_view_saga_binding(b.project_id, b.reveal, b.asset_kind)
      AND b.reveal <> 'unlisted'
  ), '[]'::jsonb);
END;
$function$

CREATE OR REPLACE FUNCTION public.list_saga_member_permission_state(p_public_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_project_id UUID;
  v_uid UUID := auth.uid();
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'not authenticated';
  END IF;

  SELECT id INTO v_project_id
  FROM public.projects
  WHERE public_id = UPPER(BTRIM(p_public_id));

  IF v_project_id IS NULL THEN
    RAISE EXCEPTION 'saga not found';
  END IF;

  IF NOT public.has_saga_permission(v_project_id, 'saga.members.read')
     AND NOT public.is_project_gm(v_project_id, v_uid) THEN
    RAISE EXCEPTION 'missing saga.members.read';
  END IF;

  RETURN COALESCE((
    SELECT jsonb_agg(
      jsonb_build_object(
        'memberId', m.id,
        'userId', m.user_id,
        'role', m.role,
        'status', m.status,
        'bundleId', b.bundle_id,
        'canSetBundle', public.has_saga_permission(v_project_id, 'saga.members.set_bundle')
          OR public.is_project_gm(v_project_id, v_uid)
      )
      ORDER BY m.joined_at
    )
    FROM public.project_members m
    LEFT JOIN public.project_member_saga_bundles b ON b.member_id = m.id
    WHERE m.project_id = v_project_id AND m.status = 'active'
  ), '[]'::jsonb);
END;
$function$

CREATE OR REPLACE FUNCTION public.list_world_atlas_maps(p_world_profile_id uuid, p_player_view boolean DEFAULT false, p_saga_public_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user UUID := auth.uid();
  v_rows JSONB;
  v_can_edit BOOLEAN;
  v_party_only BOOLEAN;
  v_project UUID;
  v_allowed UUID[];
BEGIN
  IF v_user IS NULL THEN
    RAISE EXCEPTION 'not authenticated' USING ERRCODE = '42501';
  END IF;
  IF p_world_profile_id IS NULL THEN
    RAISE EXCEPTION 'world_profile_id required' USING ERRCODE = '22023';
  END IF;
  IF NOT public.current_user_can_read_world_profile(p_world_profile_id) THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  v_can_edit := public.current_user_can_edit_world_profile(p_world_profile_id);
  v_party_only := (NOT v_can_edit) OR (p_player_view IS TRUE);

  IF p_saga_public_id IS NOT NULL AND btrim(p_saga_public_id) <> '' THEN
    v_project := public.atlas_wb_resolve_saga_project(p_world_profile_id, p_saga_public_id);
  END IF;

  IF v_party_only THEN
    IF v_project IS NULL THEN
      -- Fail closed: never dump full atlas catalog without saga.
      RETURN jsonb_build_object('maps', '[]'::jsonb);
    END IF;
    v_allowed := public.atlas_wb_party_revealed_map_ids(p_world_profile_id, v_project);

    SELECT COALESCE(jsonb_agg(
      jsonb_build_object(
        'id', m.id,
        'worldProfileId', m.world_profile_id,
        -- Hide parent id when parent map is not party-revealed (no breadcrumb leak).
        'parentMapId', CASE
          WHEN m.parent_map_id IS NULL THEN NULL
          WHEN m.parent_map_id = ANY (v_allowed) THEN m.parent_map_id
          ELSE NULL
        END,
        'kind', m.kind,
        'title', m.title,
        'sortOrder', m.sort_order,
        'revision', m.revision,
        'updatedAt', m.updated_at,
        'hasAzgaarMap', false,
        'hasBasemap', m.basemap_storage_path IS NOT NULL
      )
      ORDER BY m.sort_order, m.title
    ), '[]'::jsonb)
    INTO v_rows
    FROM public.world_atlas_maps m
    WHERE m.world_profile_id = p_world_profile_id
      AND m.id = ANY (v_allowed);
  ELSE
    SELECT COALESCE(jsonb_agg(
      jsonb_build_object(
        'id', m.id,
        'worldProfileId', m.world_profile_id,
        'parentMapId', m.parent_map_id,
        'kind', m.kind,
        'title', m.title,
        'sortOrder', m.sort_order,
        'revision', m.revision,
        'updatedAt', m.updated_at,
        'hasAzgaarMap', m.azgaar_map_storage_path IS NOT NULL,
        'hasBasemap', m.basemap_storage_path IS NOT NULL
      )
      ORDER BY m.sort_order, m.title
    ), '[]'::jsonb)
    INTO v_rows
    FROM public.world_atlas_maps m
    WHERE m.world_profile_id = p_world_profile_id;
  END IF;

  RETURN jsonb_build_object('maps', COALESCE(v_rows, '[]'::jsonb));
END;
$function$

CREATE OR REPLACE FUNCTION public.list_world_place_map_links(p_world_profile_id uuid, p_player_view boolean DEFAULT false, p_saga_public_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user UUID := auth.uid();
  v_project UUID;
  v_rows JSONB;
  v_can_edit BOOLEAN;
  v_party_only BOOLEAN;
BEGIN
  IF v_user IS NULL THEN
