CREATE OR REPLACE FUNCTION public.preview_world_node_consequences(p_world_profile_id uuid, p_place_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_desc UUID[];
  v_child INT;
  v_bind INT;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'not authenticated' USING ERRCODE = '42501';
  END IF;
  IF NOT public.current_user_can_edit_world_profile(p_world_profile_id) THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  PERFORM public.atlas_wb_place_row(p_world_profile_id, p_place_id);

  v_desc := public.atlas_wb_descendant_ids(p_world_profile_id, p_place_id);
  v_child := COALESCE(cardinality(v_desc), 0);

  SELECT COUNT(*)::INT INTO v_bind
  FROM public.saga_asset_bindings b
  WHERE b.world_place_id = p_place_id
     OR b.world_place_id = ANY (v_desc);

  RETURN jsonb_build_object(
    'placeId', p_place_id,
    'childCount', v_child,
    'sagaBindingCount', v_bind,
    'requiresConfirm', (v_child > 0 OR v_bind > 0),
    'descendantIds', to_jsonb(v_desc)
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.promote_session_outcome_to_saga(p_session_id uuid, p_consequence_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user UUID := auth.uid();
  v_session public.sessions%ROWTYPE;
  v_project public.projects%ROWTYPE;
  v_def public.saga_definitions%ROWTYPE;
  v_ver public.saga_definition_versions%ROWTYPE;
  v_cons JSONB;
  v_fact_id TEXT;
  v_visibility TEXT;
  v_summary TEXT;
  v_facts JSONB;
  v_exists BOOLEAN;
  v_promo public.session_outcome_promotions%ROWTYPE;
BEGIN
  IF v_user IS NULL THEN
    RAISE EXCEPTION 'not authenticated' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO v_session FROM public.sessions WHERE id = p_session_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Session nicht gefunden' USING ERRCODE = 'P0002';
  END IF;

  SELECT * INTO v_project FROM public.projects WHERE id = v_session.project_id;
  IF NOT public.is_project_gm(v_project.id, v_user) THEN
    RAISE EXCEPTION 'Nur Gamemaster darf übernehmen' USING ERRCODE = '42501';
  END IF;

  IF v_project.saga_id IS NULL THEN
    RAISE EXCEPTION 'Keine Saga-Definition an diese Gruppe gebunden' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_def FROM public.saga_definitions WHERE id = v_project.saga_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Saga-Definition nicht gefunden' USING ERRCODE = 'P0002';
  END IF;
  IF v_def.origin = 'native' THEN
    RAISE EXCEPTION 'Native Sagas sind unveränderlich — bitte zuerst als Kopie speichern' USING ERRCODE = '42501';
  END IF;
  IF v_def.owner_user_id IS DISTINCT FROM v_user THEN
    RAISE EXCEPTION 'Nur die Autorin/der Autor der Saga darf in die Definition übernehmen' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO v_promo
  FROM public.session_outcome_promotions
  WHERE project_id = v_project.id
    AND source_kind = 'consequence'
    AND source_id = p_consequence_id
    AND target_kind = 'saga_fact';
  IF FOUND THEN
    RETURN jsonb_build_object(
      'ok', true,
      'idempotent', true,
      'targetKind', 'saga_fact',
      'targetRef', v_promo.target_ref
    );
  END IF;

  v_cons := public.sagatree_find_session_consequence(p_session_id, p_consequence_id);
  IF v_cons IS NULL THEN
    RAISE EXCEPTION 'Ereignis nicht gefunden' USING ERRCODE = 'P0002';
  END IF;

  v_summary := NULLIF(BTRIM(COALESCE(v_cons->>'summary', '')), '');
  IF v_summary IS NULL THEN
    RAISE EXCEPTION 'Ereignis ohne Text' USING ERRCODE = '22023';
  END IF;
  v_visibility := COALESCE(NULLIF(BTRIM(v_cons->>'visibility'), ''), 'shared');
  IF v_visibility NOT IN ('public', 'shared', 'gm_only', 'discovered', 'character_specific') THEN
    v_visibility := 'shared';
  END IF;
  v_fact_id := 'promoted:' || left(p_consequence_id, 64);

  v_ver := public.sagatree_ensure_saga_draft(v_def.id);
  v_facts := COALESCE(v_ver.payload->'knowledgeFacts', '[]'::jsonb);

  SELECT EXISTS (
    SELECT 1 FROM jsonb_array_elements(v_facts) AS f
    WHERE f->>'id' = v_fact_id
  ) INTO v_exists;

  IF NOT v_exists THEN
    v_facts := v_facts || jsonb_build_array(
      jsonb_build_object(
        'id', v_fact_id,
        'visibility', v_visibility,
        'summary', left(v_summary, 200)
      )
    );
    UPDATE public.saga_definition_versions
       SET payload = jsonb_set(
         COALESCE(payload, '{}'::jsonb),
         '{knowledgeFacts}',
         v_facts,
         true
       )
     WHERE id = v_ver.id;
    UPDATE public.saga_definitions
       SET draft_revision = draft_revision + 1,
           updated_at = NOW()
     WHERE id = v_def.id;
  END IF;

  INSERT INTO public.session_outcome_promotions (
    project_id, session_id, source_kind, source_id, target_kind, target_ref, created_by
  ) VALUES (
    v_project.id, p_session_id, 'consequence', p_consequence_id, 'saga_fact', v_fact_id, v_user
  );

  PERFORM public.append_session_event(
    p_session_id,
    'adventure',
    v_user,
    jsonb_build_object(
      'op', 'promote_outcome',
      'target', 'saga',
      'consequenceId', p_consequence_id,
      'factId', v_fact_id
    ),
    COALESCE(v_session.runtime_revision, 0),
    'promote-saga:' || p_consequence_id
  );

  RETURN jsonb_build_object(
    'ok', true,
    'idempotent', false,
    'targetKind', 'saga_fact',
    'targetRef', v_fact_id,
    'messageDe', 'In die Saga-Definition übernommen (Entwurf).'
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.promote_session_outcome_to_world(p_session_id uuid, p_consequence_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user UUID := auth.uid();
  v_session public.sessions%ROWTYPE;
  v_project public.projects%ROWTYPE;
  v_world UUID;
  v_cons JSONB;
  v_fact_id TEXT;
  v_summary TEXT;
  v_visibility TEXT;
  v_modules JSONB;
  v_facts JSONB;
  v_exists BOOLEAN;
  v_promo public.session_outcome_promotions%ROWTYPE;
BEGIN
  IF v_user IS NULL THEN
    RAISE EXCEPTION 'not authenticated' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO v_session FROM public.sessions WHERE id = p_session_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Session nicht gefunden' USING ERRCODE = 'P0002';
  END IF;

  SELECT * INTO v_project FROM public.projects WHERE id = v_session.project_id;
  IF NOT public.is_project_gm(v_project.id, v_user) THEN
    RAISE EXCEPTION 'Nur Gamemaster darf übernehmen' USING ERRCODE = '42501';
  END IF;

  v_world := v_project.world_profile_id;
  IF v_world IS NULL THEN
    RAISE EXCEPTION 'Keine Welt an diese Gruppe gebunden' USING ERRCODE = '22023';
  END IF;
  IF NOT public.current_user_can_edit_world_profile(v_world) THEN
    RAISE EXCEPTION 'Nur die Welt-Besitzerin/der Welt-Besitzer darf übernehmen' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO v_promo
  FROM public.session_outcome_promotions
  WHERE project_id = v_project.id
    AND source_kind = 'consequence'
    AND source_id = p_consequence_id
    AND target_kind = 'world_fact';
  IF FOUND THEN
    RETURN jsonb_build_object(
      'ok', true,
      'idempotent', true,
      'targetKind', 'world_fact',
      'targetRef', v_promo.target_ref
    );
  END IF;

  v_cons := public.sagatree_find_session_consequence(p_session_id, p_consequence_id);
  IF v_cons IS NULL THEN
    RAISE EXCEPTION 'Ereignis nicht gefunden' USING ERRCODE = 'P0002';
  END IF;

  v_summary := NULLIF(BTRIM(COALESCE(v_cons->>'summary', '')), '');
  IF v_summary IS NULL THEN
    RAISE EXCEPTION 'Ereignis ohne Text' USING ERRCODE = '22023';
  END IF;
  v_visibility := COALESCE(NULLIF(BTRIM(v_cons->>'visibility'), ''), 'shared');
  v_fact_id := 'promoted:' || left(p_consequence_id, 64);

  SELECT modules INTO v_modules FROM public.world_profiles WHERE id = v_world FOR UPDATE;
  v_modules := COALESCE(v_modules, '{}'::jsonb);
  v_facts := COALESCE(v_modules->'promotedLore'->'facts', '[]'::jsonb);

  SELECT EXISTS (
    SELECT 1 FROM jsonb_array_elements(v_facts) AS f
    WHERE f->>'id' = v_fact_id
  ) INTO v_exists;

  IF NOT v_exists THEN
    v_facts := v_facts || jsonb_build_array(
      jsonb_build_object(
        'id', v_fact_id,
        'visibility', v_visibility,
        'summary', left(v_summary, 200),
        'sourceSessionId', p_session_id,
        'sourceConsequenceId', p_consequence_id
      )
    );
    v_modules := jsonb_set(
      v_modules,
      '{promotedLore}',
      COALESCE(v_modules->'promotedLore', '{}'::jsonb),
      true
    );
    v_modules := jsonb_set(v_modules, '{promotedLore,facts}', v_facts, true);
    UPDATE public.world_profiles
       SET modules = v_modules,
           updated_at = NOW()
     WHERE id = v_world;
  END IF;

  INSERT INTO public.session_outcome_promotions (
    project_id, session_id, source_kind, source_id, target_kind, target_ref, created_by
  ) VALUES (
    v_project.id, p_session_id, 'consequence', p_consequence_id, 'world_fact', v_fact_id, v_user
  );

  PERFORM public.append_session_event(
    p_session_id,
    'adventure',
    v_user,
    jsonb_build_object(
      'op', 'promote_outcome',
      'target', 'world',
      'consequenceId', p_consequence_id,
      'factId', v_fact_id
    ),
    COALESCE(v_session.runtime_revision, 0),
    'promote-world:' || p_consequence_id
  );

  RETURN jsonb_build_object(
    'ok', true,
    'idempotent', false,
    'targetKind', 'world_fact',
    'targetRef', v_fact_id,
    'messageDe', 'In die Welt übernommen.'
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.provision_dornhain_starter_for_user(p_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_def public.saga_definitions%ROWTYPE;
  v_ver public.saga_definition_versions%ROWTYPE;
  v_project public.projects%ROWTYPE;
  v_world UUID;
  v_member UUID;
  v_created BOOLEAN := false;
  v_adv JSONB := '{}'::jsonb;
  v_bindings INT := 0;
  v_chars INT := 0;
  v_gm INT := 0;
BEGIN
  IF p_user_id IS NULL THEN
    RAISE EXCEPTION 'user required' USING ERRCODE = '22023';
  END IF;

  IF NOT EXISTS (SELECT 1 FROM auth.users WHERE id = p_user_id) THEN
    RAISE EXCEPTION 'user not found' USING ERRCODE = 'P0002';
  END IF;

  PERFORM set_config('request.jwt.claim.sub', p_user_id::text, true);
  PERFORM set_config(
    'request.jwt.claims',
    json_build_object('sub', p_user_id::text, 'role', 'authenticated')::text,
    true
  );

  SELECT * INTO v_def
  FROM public.saga_definitions
  WHERE slug = 'dornhain.whisper' AND origin = 'native';
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'saga_missing');
  END IF;

  SELECT v.* INTO v_ver
  FROM public.saga_definition_versions v
  WHERE v.saga_id = v_def.id AND v.status = 'published'
  ORDER BY v.published_at DESC NULLS LAST
  LIMIT 1;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'version_missing');
  END IF;

  SELECT p.* INTO v_project
  FROM public.projects p
  WHERE p.gm_user_id = p_user_id
    AND p.saga_id = v_def.id
    AND p.status IN ('active', 'paused')
  ORDER BY p.created_at ASC NULLS LAST
  LIMIT 1;

  IF NOT FOUND THEN
    IF jsonb_typeof(v_ver.payload->'initialAdventure') = 'object' THEN
      v_adv := v_ver.payload->'initialAdventure';
    END IF;

    INSERT INTO public.projects (
      code, name, description, gm_user_id, status,
      saga_id, saga_version_id, adventure_runtime
    ) VALUES (
      NULL,
      v_def.title,
      v_def.synopsis,
      p_user_id,
      'active',
      v_def.id,
      v_ver.id,
      v_adv
    )
    RETURNING * INTO v_project;
    v_created := true;
  END IF;

  IF v_project.world_profile_id IS NULL THEN
    SELECT wp.id INTO v_world
    FROM public.world_profiles wp
    WHERE wp.owner_user_id = p_user_id
      AND wp.name = 'Dornhain'
    ORDER BY wp.created_at ASC
    LIMIT 1;

    IF v_world IS NULL THEN
      INSERT INTO public.world_profiles (owner_user_id, name, description, modules)
      VALUES (
        p_user_id,
        'Dornhain',
        'Starterwelt zum Abenteuer Das Flüstern unter Dornhain',
        jsonb_build_object('origin', 'native', 'sagaSlug', 'dornhain.whisper')
      )
      RETURNING id INTO v_world;
    END IF;

    UPDATE public.projects
    SET world_profile_id = v_world, updated_at = NOW()
    WHERE id = v_project.id;
    v_project.world_profile_id := v_world;
  END IF;

  INSERT INTO public.project_members (project_id, user_id, role, status)
  VALUES (v_project.id, p_user_id, 'gm', 'active')
  ON CONFLICT (project_id, user_id) DO UPDATE SET
    role = 'gm',
    status = 'active'
  RETURNING id INTO v_member;

  IF v_member IS NULL THEN
    SELECT id INTO v_member
    FROM public.project_members
    WHERE project_id = v_project.id AND user_id = p_user_id;
  END IF;

  PERFORM public.ensure_member_saga_gm_bundle(v_member);

  v_bindings := public.seed_dornhain_catalog_bindings(v_project.id);
  v_chars := public.seed_dornhain_starter_characters(v_project.id, p_user_id);
  v_gm := public.seed_dornhain_gm_presence_character(v_project.id, p_user_id);

  RETURN jsonb_build_object(
    'ok', true,
    'created', v_created,
    'projectId', v_project.id,
    'publicId', v_project.public_id,
    'worldProfileId', v_project.world_profile_id,
    'bindings', v_bindings,
    'characters', v_chars,
    'gmPresence', v_gm
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.publish_saga_definition_version(p_saga_id uuid, p_expected_revision integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user UUID := auth.uid();
  v_def public.saga_definitions%ROWTYPE;
  v_draft public.saga_definition_versions%ROWTYPE;
  v_new public.saga_definition_versions%ROWTYPE;
  v_next_num INTEGER;
  v_label TEXT;
BEGIN
  IF v_user IS NULL THEN
    RAISE EXCEPTION 'not authenticated' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO v_def FROM public.saga_definitions WHERE id = p_saga_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Saga-Definition nicht gefunden' USING ERRCODE = 'P0002';
  END IF;
  IF v_def.origin = 'native' THEN
    RAISE EXCEPTION 'Native Sagas sind unveränderlich' USING ERRCODE = '42501';
  END IF;
  IF v_def.owner_user_id IS DISTINCT FROM v_user THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  IF v_def.draft_revision IS DISTINCT FROM COALESCE(p_expected_revision, -1) THEN
    RAISE EXCEPTION 'Revisionskonflikt — bitte neu laden' USING ERRCODE = '40001';
  END IF;

  v_draft := public.sagatree_ensure_saga_draft(v_def.id);
  IF NULLIF(BTRIM(COALESCE(v_draft.payload->>'title', v_def.title, '')), '') IS NULL THEN
    RAISE EXCEPTION 'Titel darf nicht leer sein' USING ERRCODE = '22023';
  END IF;

  SELECT COALESCE(MAX(
    CASE
      WHEN version_label ~ '^v[0-9]+$' THEN SUBSTRING(version_label FROM 2)::INTEGER
      ELSE 0
    END
  ), 0) + 1
  INTO v_next_num
  FROM public.saga_definition_versions
  WHERE saga_id = v_def.id AND status = 'published';

  v_label := 'v' || v_next_num::TEXT;

  INSERT INTO public.saga_definition_versions (
    saga_id, version_label, status, payload, published_at
  ) VALUES (
    v_def.id,
    v_label,
    'published',
    v_draft.payload,
    NOW()
  )
  RETURNING * INTO v_new;

  -- Draft stays editable; pinned projects keep their saga_version_id unchanged.

  RETURN jsonb_build_object(
    'sagaId', v_def.id,
    'versionId', v_new.id,
    'versionLabel', v_new.version_label,
    'revision', v_def.draft_revision
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.remove_npc_creature_instance(p_instance_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_row public.npc_creature_instances;
BEGIN
  IF p_instance_id IS NULL THEN
    RAISE EXCEPTION 'missing instance';
  END IF;

  SELECT * INTO v_row
  FROM public.npc_creature_instances
  WHERE id = p_instance_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'instance not found';
  END IF;

  PERFORM public.assert_npc_creature_instance_gm(v_row.project_id);

  DELETE FROM public.npc_creature_instances WHERE id = p_instance_id;
  RETURN p_instance_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.rename_world_node(p_world_profile_id uuid, p_place_id uuid, p_name text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_row public.world_places%ROWTYPE;
  v_name TEXT := NULLIF(btrim(p_name), '');
  v_status TEXT;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'not authenticated' USING ERRCODE = '42501';
  END IF;
  IF NOT public.current_user_can_edit_world_profile(p_world_profile_id) THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  IF v_name IS NULL THEN
    RAISE EXCEPTION 'empty name' USING ERRCODE = '22023';
  END IF;

  v_row := public.atlas_wb_place_row(p_world_profile_id, p_place_id);
  v_status := CASE WHEN v_row.status = 'placeholder' THEN 'draft' ELSE v_row.status END;

  UPDATE public.world_places
  SET
    name = v_name,
    status = v_status,
    revision = revision + 1,
    updated_at = NOW()
  WHERE id = p_place_id AND world_profile_id = p_world_profile_id
  RETURNING * INTO v_row;

  RETURN public.atlas_wb_place_json(v_row);
END;
$function$

CREATE OR REPLACE FUNCTION public.reparent_world_node(p_world_profile_id uuid, p_place_id uuid, p_new_parent_place_id uuid, p_confirm_relocate boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_row public.world_places%ROWTYPE;
  v_parent public.world_places%ROWTYPE;
  v_parent_kind TEXT;
  v_need TEXT;
  v_desc UUID[];
  v_map UUID;
  v_parent_map UUID;
  v_root_map UUID;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'not authenticated' USING ERRCODE = '42501';
  END IF;
  IF NOT public.current_user_can_edit_world_profile(p_world_profile_id) THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  IF p_confirm_relocate IS NOT TRUE THEN
    RAISE EXCEPTION 'relocate confirmation required' USING ERRCODE = '22023';
  END IF;

  v_row := public.atlas_wb_place_row(p_world_profile_id, p_place_id);
  IF NOT public.atlas_wb_is_canonical_kind(v_row.kind) THEN
    RAISE EXCEPTION 'kind must be canonical WorldNodeKind' USING ERRCODE = '22023';
  END IF;

  IF p_new_parent_place_id IS NOT NULL THEN
    IF p_new_parent_place_id = p_place_id THEN
      RAISE EXCEPTION 'cycle' USING ERRCODE = '23514';
    END IF;
    v_desc := public.atlas_wb_descendant_ids(p_world_profile_id, p_place_id);
    IF p_new_parent_place_id = ANY (v_desc) THEN
      RAISE EXCEPTION 'cycle' USING ERRCODE = '23514';
    END IF;
    SELECT * INTO v_parent
    FROM public.world_places
    WHERE id = p_new_parent_place_id AND world_profile_id = p_world_profile_id;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'parent not in world' USING ERRCODE = '23514';
    END IF;
    v_parent_kind := v_parent.kind;
  ELSE
    v_parent_kind := NULL;
  END IF;

  v_need := public.atlas_wb_required_parent_kind(v_row.kind);
  IF NOT public.atlas_wb_tip_satisfies(v_need, v_parent_kind) THEN
    RAISE EXCEPTION 'invalid parent kind edge' USING ERRCODE = '23514';
  END IF;

  v_root_map := public.atlas_wb_ensure_world_root_map(p_world_profile_id);
  IF p_new_parent_place_id IS NOT NULL THEN
    v_parent_map := public.atlas_wb_primary_map_id(p_new_parent_place_id);
  END IF;
  IF v_parent_map IS NULL THEN
    v_parent_map := v_root_map;
  END IF;

  UPDATE public.world_places
  SET
    parent_place_id = p_new_parent_place_id,
    revision = revision + 1,
    updated_at = NOW()
  WHERE id = p_place_id AND world_profile_id = p_world_profile_id
  RETURNING * INTO v_row;

  v_map := public.atlas_wb_primary_map_id(p_place_id);
  IF v_map IS NOT NULL THEN
    UPDATE public.world_atlas_maps
    SET
      parent_map_id = v_parent_map,
      generator_meta = COALESCE(generator_meta, '{}'::jsonb)
        || jsonb_build_object('mapStatus', 'unlocated'),
      updated_at = NOW()
    WHERE id = v_map AND world_profile_id = p_world_profile_id;
  END IF;

  RETURN jsonb_build_object(
    'place', public.atlas_wb_place_json(v_row),
    'primaryMapId', v_map,
    'parentMapId', v_parent_map,
    'relocated', true
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.resolve_session_invite(p_token text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  actor UUID := auth.uid();
  v_invite public.session_invites;
  v_session public.sessions;
  v_saga_public_id TEXT;
  v_already_member BOOLEAN := false;
  v_is_gm BOOLEAN := false;
  v_character_id UUID;
  v_character_public_id TEXT;
BEGIN
  IF actor IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE = '42501';
  END IF;
  IF NULLIF(BTRIM(p_token), '') IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error_code', 'missing_token');
  END IF;

  SELECT * INTO v_invite
    FROM public.session_invites
   WHERE token = BTRIM(p_token)
   FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error_code', 'not_found');
  END IF;
  IF v_invite.revoked_at IS NOT NULL THEN
    RETURN jsonb_build_object('ok', false, 'error_code', 'revoked');
  END IF;
  IF v_invite.expires_at <= NOW() THEN
    RETURN jsonb_build_object('ok', false, 'error_code', 'expired');
  END IF;

  SELECT * INTO v_session FROM public.sessions WHERE id = v_invite.session_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error_code', 'session_missing');
  END IF;
  IF v_session.status = 'completed' THEN
    RETURN jsonb_build_object('ok', false, 'error_code', 'session_completed');
  END IF;

  SELECT p.public_id INTO v_saga_public_id
    FROM public.projects p
   WHERE p.id = v_session.project_id;
  IF v_saga_public_id IS NULL OR BTRIM(v_saga_public_id) = '' THEN
    RETURN jsonb_build_object('ok', false, 'error_code', 'saga_missing');
  END IF;

  v_is_gm := public.is_project_gm(v_session.project_id, actor);

  SELECT true, sp.character_id
    INTO v_already_member, v_character_id
    FROM public.session_players sp
   WHERE sp.session_id = v_session.id
     AND sp.user_id = actor
     AND sp.left_at IS NULL
   LIMIT 1;
  IF NOT FOUND THEN
    v_already_member := false;
    v_character_id := NULL;
  END IF;

  IF v_character_id IS NOT NULL THEN
    SELECT c.public_id INTO v_character_public_id
      FROM public.characters c
     WHERE c.id = v_character_id;
  END IF;

  UPDATE public.session_invites
     SET last_resolved_at = NOW()
   WHERE id = v_invite.id;

  -- Facts only — never invent a role claim for the client to assert privilege.
  RETURN jsonb_build_object(
    'ok', true,
    'saga_public_id', upper(btrim(v_saga_public_id)),
    'session_public_id', upper(btrim(v_session.public_id)),
    'project_id', v_session.project_id,
    'session_id', v_session.id,
    'session_status', v_session.status,
    'already_member', COALESCE(v_already_member, false),
    'is_project_gm', v_is_gm,
    'character_public_id', NULLIF(upper(btrim(COALESCE(v_character_public_id, ''))), '')
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.revoke_session_invite(p_token text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  actor UUID := auth.uid();
  v_invite public.session_invites;
  v_session public.sessions;
BEGIN
  IF actor IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE = '42501';
  END IF;
  IF NULLIF(BTRIM(p_token), '') IS NULL THEN
    RAISE EXCEPTION 'token required' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_invite
    FROM public.session_invites
   WHERE token = BTRIM(p_token)
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Invite not found' USING ERRCODE = 'P0002';
  END IF;

  SELECT * INTO v_session FROM public.sessions WHERE id = v_invite.session_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Session not found' USING ERRCODE = 'P0002';
  END IF;
  IF NOT public.is_project_gm(v_session.project_id, actor) THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  IF v_invite.revoked_at IS NULL THEN
    UPDATE public.session_invites SET revoked_at = NOW() WHERE id = v_invite.id;
  END IF;

  RETURN jsonb_build_object('ok', true, 'id', v_invite.id);
END;
$function$

CREATE OR REPLACE FUNCTION public.sagatree_apply_knowledge_reveal(p_world jsonb, p_payload jsonb, p_actor uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
AS $function$
DECLARE
  v_shared JSONB;
  v_knowledge JSONB;
  v_facts JSONB;
  v_fact JSONB;
  v_fact_id TEXT;
  v_target JSONB;
  v_target_kind TEXT;
  v_character_id TEXT;
  v_reveals JSONB;
  v_discoveries JSONB;
  v_reveal JSONB;
  v_found BOOLEAN := FALSE;
  v_i INT;
BEGIN
  p_payload := COALESCE(p_payload, '{}'::jsonb);
  v_fact_id := NULLIF(BTRIM(COALESCE(p_payload->>'factId', '')), '');
  IF v_fact_id IS NULL THEN
    RAISE EXCEPTION 'factId ist erforderlich' USING ERRCODE = '22023';
  END IF;
  v_fact_id := left(v_fact_id, 128);

  v_target := p_payload->'target';
  IF v_target IS NULL OR jsonb_typeof(v_target) <> 'object' THEN
    RAISE EXCEPTION 'Reveal-Target ungültig' USING ERRCODE = '22023';
  END IF;
  v_target_kind := NULLIF(BTRIM(COALESCE(v_target->>'kind', '')), '');
  IF v_target_kind NOT IN ('everyone', 'program', 'players', 'character') THEN
    RAISE EXCEPTION 'Reveal-Target ungültig' USING ERRCODE = '22023';
  END IF;
  IF v_target_kind = 'character' THEN
    v_character_id := NULLIF(BTRIM(COALESCE(v_target->>'characterId', '')), '');
    IF v_character_id IS NULL THEN
      RAISE EXCEPTION 'characterId ist erforderlich' USING ERRCODE = '22023';
    END IF;
    v_character_id := left(v_character_id, 128);
    v_target := jsonb_build_object('kind', 'character', 'characterId', v_character_id);
  ELSE
    v_target := jsonb_build_object('kind', v_target_kind);
  END IF;

  v_shared := COALESCE(p_world->'shared', '{}'::jsonb);
  v_knowledge := COALESCE(v_shared->'knowledge', '{}'::jsonb);
  IF COALESCE(v_knowledge->>'authoritative', 'false') <> 'true' THEN
    v_knowledge := jsonb_build_object(
      'schemaVersion', 1,
      'authoritative', true,
      'facts', '[]'::jsonb,
      'discoveries', '[]'::jsonb,
      'reveals', '[]'::jsonb,
      'updatedAt', to_jsonb(NOW() AT TIME ZONE 'utc')
    );
  END IF;

  v_facts := COALESCE(v_knowledge->'facts', '[]'::jsonb);
  IF jsonb_typeof(v_facts) = 'array' THEN
    FOR v_i IN 0 .. GREATEST(jsonb_array_length(v_facts) - 1, -1) LOOP
      IF v_facts->v_i->>'id' = v_fact_id THEN
        v_found := TRUE;
        EXIT;
      END IF;
    END LOOP;
  END IF;

  -- Upsert minimal fact stub if GM reveals an unpublished id with title/body in payload.
  IF NOT v_found THEN
    v_fact := jsonb_build_object(
      'id', v_fact_id,
      'title', left(COALESCE(NULLIF(BTRIM(p_payload->>'title'), ''), v_fact_id), 160),
      'visibility', COALESCE(NULLIF(BTRIM(p_payload->>'visibility'), ''), 'gm_only'),
      'body', to_jsonb(left(COALESCE(p_payload->>'body', ''), 4000)),
      'handoutRef', 'null'::jsonb,
      'characterId', to_jsonb(
        NULLIF(left(BTRIM(COALESCE(p_payload->>'characterId', '')), 128), '')
      )
    );
    IF v_fact->>'visibility' NOT IN (
      'public', 'gm_only', 'discovered', 'character_specific', 'program'
    ) THEN
      v_fact := jsonb_set(v_fact, '{visibility}', '"gm_only"'::jsonb, true);
    END IF;
    v_facts := v_facts || jsonb_build_array(v_fact);
  END IF;

  v_reveal := jsonb_build_object(
    'id', gen_random_uuid()::text,
    'factId', v_fact_id,
    'target', v_target,
    'revealedAt', to_jsonb(NOW() AT TIME ZONE 'utc'),
    'byUserId', to_jsonb(p_actor::text)
  );
  v_reveals := COALESCE(v_knowledge->'reveals', '[]'::jsonb) || jsonb_build_array(v_reveal);

  v_discoveries := COALESCE(v_knowledge->'discoveries', '[]'::jsonb);
  IF v_target_kind IN ('everyone', 'players', 'character') THEN
    v_found := FALSE;
    IF jsonb_typeof(v_discoveries) = 'array' THEN
      FOR v_i IN 0 .. GREATEST(jsonb_array_length(v_discoveries) - 1, -1) LOOP
        IF v_discoveries->v_i->>'factId' = v_fact_id THEN
          v_found := TRUE;
          EXIT;
        END IF;
      END LOOP;
    END IF;
    IF NOT v_found THEN
      v_discoveries := v_discoveries || jsonb_build_array(jsonb_build_object(
        'factId', v_fact_id,
        'discoveredAt', to_jsonb(NOW() AT TIME ZONE 'utc'),
        'byUserId', to_jsonb(p_actor::text)
      ));
    END IF;
  END IF;

  v_knowledge := jsonb_build_object(
    'schemaVersion', 1,
    'authoritative', true,
    'facts', v_facts,
    'discoveries', v_discoveries,
    'reveals', v_reveals,
    'updatedAt', to_jsonb(NOW() AT TIME ZONE 'utc')
  );
  v_shared := jsonb_set(v_shared, '{knowledge}', v_knowledge, true);
  RETURN jsonb_build_object(
    'worldState', jsonb_set(COALESCE(p_world, '{}'::jsonb), '{shared}', v_shared, true),
    'eventPayload', v_reveal
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.sagatree_build_encounter_participant_npc(p_instance npc_creature_instances)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
AS $function$
DECLARE
  v_bonus INT := 0;
  v_natural INT;
  v_hp_max INT;
  v_hp_cur INT;
  v_name TEXT;
  v_conditions JSONB;
BEGIN
  v_hp_max := COALESCE((p_instance.snapshot ->> 'maxHealth')::int, 10);
  IF v_hp_max < 1 THEN v_hp_max := 10; END IF;
  IF v_hp_max > 9999 THEN v_hp_max := 9999; END IF;

  v_hp_cur := COALESCE((p_instance.runtime ->> 'currentHp')::int, v_hp_max);
  IF v_hp_cur < 0 THEN v_hp_cur := 0; END IF;
  IF v_hp_cur > v_hp_max THEN v_hp_cur := v_hp_max; END IF;

  v_name := NULLIF(BTRIM(COALESCE(p_instance.display_name, '')), '');
  IF v_name IS NULL THEN
    v_name := NULLIF(BTRIM(COALESCE(p_instance.snapshot ->> 'name', '')), '');
  END IF;
  IF v_name IS NULL THEN v_name := 'Gegner'; END IF;
  v_name := left(v_name, 120);

  IF jsonb_typeof(p_instance.runtime -> 'conditions') = 'array' THEN
    v_conditions := p_instance.runtime -> 'conditions';
  ELSE
    v_conditions := '[]'::jsonb;
  END IF;

  -- Optional snapshot initiative hint; never trust client.
  IF (p_instance.snapshot ->> 'initiativeBonus') ~ '^[0-9]+$' THEN
    v_bonus := LEAST(40, (p_instance.snapshot ->> 'initiativeBonus')::int);
  END IF;

  v_natural := public.sagatree_roll_d20();

  RETURN jsonb_build_object(
    'id', 'npc:' || p_instance.id::text,
    'kind', 'npc',
    'refId', p_instance.id::text,
    'name', v_name,
    'initiative', v_natural + v_bonus,
    'initiativeBonus', v_bonus,
    'natural', v_natural,
    'hpCurrent', v_hp_cur,
    'hpMax', v_hp_max,
    'conditions', v_conditions,
    'actions', public.sagatree_fresh_action_economy()
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.sagatree_build_encounter_participant_pc(p_character characters)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
AS $function$
DECLARE
  v_perception INT;
  v_awareness INT;
  v_bonus INT;
  v_natural INT;
  v_hp_max INT;
  v_name TEXT;
BEGIN
  v_perception := COALESCE((p_character.attributes ->> 'perception')::int, 1);
  v_awareness := COALESCE((p_character.skills ->> 'awareness')::int, 0);
  v_bonus := public.sagatree_pc_initiative_bonus(
    v_perception, v_awareness, COALESCE(p_character.level, 1)
  );
  v_natural := public.sagatree_roll_d20();
  v_hp_max := public.sagatree_pc_health(
    COALESCE((p_character.attributes ->> 'endurance')::int, 1),
    COALESCE(p_character.level, 1)
  );
  v_name := NULLIF(BTRIM(COALESCE(p_character.name, '')), '');
  IF v_name IS NULL THEN v_name := 'Held'; END IF;
  v_name := left(v_name, 120);

  RETURN jsonb_build_object(
    'id', 'pc:' || p_character.id::text,
    'kind', 'pc',
    'refId', p_character.id::text,
    'name', v_name,
    'initiative', v_natural + v_bonus,
    'initiativeBonus', v_bonus,
    'natural', v_natural,
    'hpCurrent', v_hp_max,
    'hpMax', v_hp_max,
    'conditions', '[]'::jsonb,
    'actions', public.sagatree_fresh_action_economy()
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.sagatree_build_program_presentation(p_payload jsonb, p_previous jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
AS $function$
DECLARE
  v_source JSONB;
  v_source_kind TEXT;
  v_look_id TEXT;
  v_layout JSONB;
  v_layout_kind TEXT;
  v_overlay JSONB;
  v_overlay_text TEXT;
  v_prev_rev BIGINT := 0;
BEGIN
  p_payload := COALESCE(p_payload, '{}'::jsonb)
    - 'authoritative' - 'updatedAt' - 'updated_at'
    - 'revision' - 'schemaVersion' - 'programRevision'
    - 'gm_only' - 'character_specific';

  IF p_payload ? 'gm_only' OR p_payload ? 'character_specific' THEN
    RAISE EXCEPTION 'Program payload darf keine Secrets enthalten' USING ERRCODE = '22023';
  END IF;

  IF p_previous IS NOT NULL AND jsonb_typeof(p_previous) = 'object' THEN
    v_prev_rev := COALESCE((p_previous->>'programRevision')::bigint, 0);
  END IF;

  v_source_kind := NULLIF(BTRIM(COALESCE(p_payload->'source'->>'kind', '')), '');
  IF v_source_kind IS NULL OR v_source_kind NOT IN ('neutral', 'shared-scene', 'look') THEN
    v_source_kind := 'shared-scene';
  END IF;

  IF v_source_kind = 'look' THEN
    v_look_id := NULLIF(BTRIM(COALESCE(p_payload->'source'->>'lookId', '')), '');
    IF v_look_id IS NOT NULL THEN
      v_look_id := left(v_look_id, 128);
    END IF;
    v_source := jsonb_build_object('kind', 'look', 'lookId', to_jsonb(v_look_id));
  ELSIF v_source_kind = 'neutral' THEN
    v_source := jsonb_build_object('kind', 'neutral');
  ELSE
    v_source := jsonb_build_object('kind', 'shared-scene');
  END IF;

  v_layout_kind := NULLIF(BTRIM(COALESCE(p_payload->'layout'->>'kind', '')), '');
  IF v_layout_kind IS NULL OR v_layout_kind NOT IN ('fullscreen-16x9', 'letterbox') THEN
    v_layout_kind := 'fullscreen-16x9';
  END IF;
  v_layout := jsonb_build_object('kind', v_layout_kind);

  v_overlay := NULL;
  IF p_payload ? 'overlay' AND jsonb_typeof(p_payload->'overlay') = 'object' THEN
    IF COALESCE(p_payload->'overlay'->>'kind', '') = 'title' THEN
      v_overlay_text := NULLIF(BTRIM(COALESCE(p_payload->'overlay'->>'text', '')), '');
      IF v_overlay_text IS NOT NULL THEN
        v_overlay := jsonb_build_object(
          'kind', 'title',
          'text', left(v_overlay_text, 120)
        );
      END IF;
    END IF;
  END IF;

  RETURN jsonb_build_object(
    'schemaVersion', 1,
    'programRevision', v_prev_rev + 1,
    'source', v_source,
    'layout', v_layout,
    'overlay', COALESCE(v_overlay, 'null'::jsonb),
    'updatedAt', to_jsonb(NOW() AT TIME ZONE 'utc'),
    'authoritative', true
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.sagatree_build_recap_highlight_lines(p_adventure jsonb, p_is_gm boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
DECLARE
  v_out JSONB := '[]'::jsonb;
  v_elem JSONB;
  v_vis TEXT;
BEGIN
  FOR v_elem IN
    SELECT elem
    FROM jsonb_array_elements(COALESCE(p_adventure->'consequences', '[]'::jsonb)) AS elem
    ORDER BY COALESCE(elem->>'createdAt', '') DESC
    LIMIT 40
  LOOP
    v_vis := COALESCE(v_elem->>'visibility', 'gm_only');
    IF p_is_gm OR v_vis IN ('public', 'shared') THEN
      v_out := v_out || jsonb_build_array(
        jsonb_build_object(
          'id', COALESCE(v_elem->>'id', ''),
          'kind', COALESCE(v_elem->>'kind', 'generic'),
          'summary', COALESCE(v_elem->>'summary', ''),
          'visibility', v_vis
        )
      );
    END IF;
    IF jsonb_array_length(v_out) >= 20 THEN
      EXIT;
    END IF;
  END LOOP;
  RETURN v_out;
END;
$function$

CREATE OR REPLACE FUNCTION public.sagatree_build_scene_presentation(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
AS $function$
DECLARE
  v_title TEXT;
  v_location TEXT;
  v_description TEXT;
  v_backdrop TEXT;
  v_scene_id TEXT;
  v_ref JSONB;
  v_ref_kind TEXT;
  v_ref_id TEXT;
  v_actors JSONB := '[]'::jsonb;
  v_actor JSONB;
  v_actor_out JSONB;
  v_name TEXT;
  v_kind TEXT;
  v_role TEXT;
  v_portrait TEXT;
  v_i INT;
BEGIN
  -- Strip forged server-owned keys
  p_payload := p_payload - 'authoritative' - 'updatedAt' - 'updated_at' - 'revision' - 'schemaVersion';

  v_title := NULLIF(BTRIM(COALESCE(p_payload->>'title', '')), '');
  IF v_title IS NULL THEN
    RAISE EXCEPTION 'Szenen-Titel ist erforderlich' USING ERRCODE = '22023';
  END IF;
  v_title := left(v_title, 120);

  v_location := NULLIF(BTRIM(COALESCE(p_payload->>'locationLabel', '')), '');
  IF v_location IS NOT NULL THEN
    v_location := left(v_location, 120);
  END IF;

  v_description := NULLIF(BTRIM(COALESCE(p_payload->>'description', '')), '');
  IF v_description IS NOT NULL THEN
    v_description := left(v_description, 500);
  END IF;

  v_backdrop := NULLIF(BTRIM(COALESCE(p_payload->>'backdropUrl', '')), '');
  IF v_backdrop IS NOT NULL THEN
    v_backdrop := left(v_backdrop, 2048);
    IF NOT public.sagatree_is_http_url(v_backdrop) THEN
      RAISE EXCEPTION 'Backdrop-URL muss http(s) sein oder leer' USING ERRCODE = '22023';
    END IF;
  END IF;

  v_scene_id := NULLIF(BTRIM(COALESCE(p_payload->>'sceneId', '')), '');
  IF v_scene_id IS NOT NULL THEN
    v_scene_id := left(v_scene_id, 128);
  END IF;

  v_ref := NULL;
  IF p_payload ? 'sceneRef' AND jsonb_typeof(p_payload->'sceneRef') = 'object' THEN
    v_ref_kind := NULLIF(BTRIM(COALESCE(p_payload->'sceneRef'->>'kind', '')), '');
    IF v_ref_kind IN ('session-local', 'adventure-scene', 'world-location') THEN
      v_ref_id := NULLIF(BTRIM(COALESCE(p_payload->'sceneRef'->>'id', '')), '');
      IF v_ref_id IS NOT NULL THEN
        v_ref_id := left(v_ref_id, 128);
      END IF;
      v_ref := jsonb_build_object('kind', v_ref_kind, 'id', to_jsonb(v_ref_id));
    END IF;
  END IF;

  IF v_ref IS NULL AND v_scene_id IS NOT NULL THEN
    v_ref := jsonb_build_object('kind', 'session-local', 'id', to_jsonb(v_scene_id));
  END IF;

  IF p_payload ? 'visibleActors' AND jsonb_typeof(p_payload->'visibleActors') = 'array' THEN
    FOR v_i IN 0 .. LEAST(jsonb_array_length(p_payload->'visibleActors') - 1, 23) LOOP
      v_actor := p_payload->'visibleActors'->v_i;
      IF jsonb_typeof(v_actor) <> 'object' THEN
        CONTINUE;
      END IF;
      v_name := NULLIF(BTRIM(COALESCE(v_actor->>'displayName', '')), '');
      IF v_name IS NULL THEN
        CONTINUE;
      END IF;
      v_name := left(v_name, 80);
      v_kind := COALESCE(NULLIF(BTRIM(v_actor->>'kind'), ''), 'other');
      IF v_kind NOT IN ('character', 'npc', 'creature', 'other') THEN
        v_kind := 'other';
      END IF;
      v_role := COALESCE(NULLIF(BTRIM(v_actor->>'role'), ''), CASE WHEN v_kind = 'character' THEN 'pc' ELSE 'other' END);
      IF v_role NOT IN ('pc', 'npc', 'creature', 'other') THEN
        v_role := 'other';
      END IF;
      v_portrait := NULLIF(BTRIM(COALESCE(v_actor->>'portraitUrl', '')), '');
      IF v_portrait IS NOT NULL THEN
        v_portrait := left(v_portrait, 2048);
        IF NOT public.sagatree_is_http_url(v_portrait) THEN
          v_portrait := NULL;
        END IF;
      END IF;
      v_actor_out := jsonb_build_object(
        'kind', v_kind,
        'id', to_jsonb(NULLIF(left(BTRIM(COALESCE(v_actor->>'id', '')), 128), '')),
        'publicId', to_jsonb(NULLIF(left(BTRIM(COALESCE(v_actor->>'publicId', '')), 64), '')),
        'displayName', v_name,
        'portraitUrl', to_jsonb(v_portrait),
        'role', v_role
      );
      v_actors := v_actors || jsonb_build_array(v_actor_out);
    END LOOP;
  END IF;

  RETURN jsonb_build_object(
    'schemaVersion', 1,
    'title', v_title,
    'locationLabel', to_jsonb(v_location),
    'description', to_jsonb(v_description),
    'backdropUrl', to_jsonb(v_backdrop),
    'sceneRef', COALESCE(v_ref, 'null'::jsonb),
    'visibleActors', v_actors,
    'updatedAt', to_jsonb(NOW() AT TIME ZONE 'utc'),
    'authoritative', true,
    '_sceneId', to_jsonb(
      COALESCE(
        v_scene_id,
        NULLIF(BTRIM(COALESCE(v_ref->>'id', '')), '')
      )
    )
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.sagatree_ensure_saga_draft(p_saga_id uuid)
 RETURNS saga_definition_versions
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_draft public.saga_definition_versions%ROWTYPE;
  v_pub public.saga_definition_versions%ROWTYPE;
  v_payload JSONB := '{}'::jsonb;
BEGIN
  SELECT * INTO v_draft
  FROM public.saga_definition_versions
  WHERE saga_id = p_saga_id AND status = 'draft'
  ORDER BY created_at DESC
  LIMIT 1;

  IF FOUND THEN
    RETURN v_draft;
  END IF;

  SELECT * INTO v_pub
  FROM public.saga_definition_versions
  WHERE saga_id = p_saga_id AND status = 'published'
  ORDER BY published_at DESC NULLS LAST, created_at DESC
  LIMIT 1;

  IF FOUND THEN
    v_payload := v_pub.payload;
  END IF;

  INSERT INTO public.saga_definition_versions (
    saga_id, version_label, status, payload, published_at
  ) VALUES (
    p_saga_id,
    'draft',
    'draft',
    v_payload,
    NULL
  )
  RETURNING * INTO v_draft;

  RETURN v_draft;
END;
$function$

CREATE OR REPLACE FUNCTION public.sagatree_find_session_consequence(p_session_id uuid, p_consequence_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_adv JSONB := '{}'::jsonb;
  v_elem JSONB;
BEGIN
  SELECT COALESCE(sr.snapshot, '{}'::jsonb) INTO v_adv
  FROM public.session_recaps sr
  WHERE sr.session_id = p_session_id;

  IF v_adv = '{}'::jsonb OR v_adv IS NULL THEN
    SELECT COALESCE(p.adventure_runtime, '{}'::jsonb) INTO v_adv
    FROM public.sessions s
    JOIN public.projects p ON p.id = s.project_id
    WHERE s.id = p_session_id;
  END IF;

  FOR v_elem IN
    SELECT elem
    FROM jsonb_array_elements(COALESCE(v_adv->'consequences', '[]'::jsonb)) AS elem
  LOOP
    IF COALESCE(v_elem->>'id', '') = p_consequence_id THEN
      RETURN v_elem;
    END IF;
  END LOOP;

  RETURN NULL;
END;
$function$

CREATE OR REPLACE FUNCTION public.sagatree_forbid_native_saga_insert()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF NEW.origin = 'native' AND (auth.role() IS DISTINCT FROM 'service_role') THEN
    RAISE EXCEPTION 'native saga definitions are service_role only' USING ERRCODE = '42501';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.sagatree_is_http_url(p_url text)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
BEGIN
  IF p_url IS NULL OR BTRIM(p_url) = '' THEN
    RETURN TRUE;
  END IF;
  IF char_length(p_url) > 2048 THEN
    RETURN FALSE;
  END IF;
  RETURN lower(p_url) ~ '^https?://';
END;
$function$

CREATE OR REPLACE FUNCTION public.sagatree_life_conditions(p_status text, p_dying integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
DECLARE
  v_dying INT := GREATEST(0, LEAST(3, COALESCE(p_dying, 0)));
  v_out JSONB := '[]'::jsonb;
BEGIN
  IF p_status = 'dead' THEN
    RETURN '["tot","kampfunfähig"]'::jsonb;
  ELSIF p_status = 'stable' THEN
    v_out := '["kampfunfähig","stabil"]'::jsonb;
    IF v_dying > 0 THEN
      v_out := v_out || to_jsonb(('sterbend:' || v_dying::text));
    END IF;
    RETURN v_out;
  ELSIF p_status = 'downed' THEN
    v_out := '["kampfunfähig","bewusstlos"]'::jsonb;
    IF v_dying > 0 THEN
      v_out := v_out || to_jsonb(('sterbend:' || v_dying::text));
    END IF;
    RETURN v_out;
  END IF;
  RETURN '[]'::jsonb;
END;
$function$

CREATE OR REPLACE FUNCTION public.sagatree_life_start_level(p_difficulty text, p_explicit_deadly boolean)
 RETURNS integer
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
BEGIN
  IF p_difficulty = 'Heroisch' THEN
    IF p_explicit_deadly THEN
      RETURN 1;
    END IF;
    RETURN 0;
  ELSIF p_difficulty = 'Hart' THEN
    RETURN 2;
  END IF;
  RETURN 1; -- Standard
END;
$function$

CREATE OR REPLACE FUNCTION public.sagatree_merge_life_into_conditions(p_existing jsonb, p_life_conditions jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
DECLARE
  v_out JSONB := '[]'::jsonb;
  v_elem TEXT;
  v_count INT := 0;
BEGIN
  FOR v_elem IN SELECT jsonb_array_elements_text(COALESCE(p_existing, '[]'::jsonb))
  LOOP
    IF v_elem NOT IN ('tot', 'kampfunfähig', 'bewusstlos', 'unconscious', 'stabil')
       AND v_elem NOT LIKE 'sterbend:%' THEN
      v_out := v_out || to_jsonb(v_elem);
      v_count := v_count + 1;
      IF v_count >= 24 THEN
        RETURN v_out;
      END IF;
    END IF;
  END LOOP;
  FOR v_elem IN SELECT jsonb_array_elements_text(COALESCE(p_life_conditions, '[]'::jsonb))
  LOOP
    IF NOT (v_out @> to_jsonb(v_elem)) THEN
      v_out := v_out || to_jsonb(v_elem);
      v_count := v_count + 1;
      IF v_count >= 24 THEN
        RETURN v_out;
      END IF;
    END IF;
  END LOOP;
  RETURN v_out;
END;
$function$

CREATE OR REPLACE FUNCTION public.sagatree_project_saga_definition_payload(p_payload jsonb, p_is_gm boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
DECLARE
  v_out JSONB;
  v_facts JSONB := '[]'::jsonb;
  v_elem JSONB;
  v_vis TEXT;
BEGIN
  v_out := COALESCE(p_payload, '{}'::jsonb);
  IF jsonb_typeof(v_out->'knowledgeFacts') = 'array' THEN
    FOR v_elem IN SELECT elem FROM jsonb_array_elements(v_out->'knowledgeFacts') AS elem
    LOOP
      v_vis := COALESCE(v_elem->>'visibility', 'gm_only');
      IF p_is_gm OR v_vis IN ('public', 'discovered', 'shared') THEN
        v_facts := v_facts || jsonb_build_array(v_elem);
      END IF;
    END LOOP;
    v_out := jsonb_set(v_out, '{knowledgeFacts}', v_facts);
  END IF;
  RETURN v_out;
END;
$function$

CREATE OR REPLACE FUNCTION public.sagatree_project_shared_adventure(p_shared jsonb, p_is_gm boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
AS $function$
DECLARE
  v_adv JSONB;
  v_flags JSONB := '{}'::jsonb;
  v_rels JSONB := '{}'::jsonb;
  v_clocks JSONB := '{}'::jsonb;
  v_cons JSONB := '[]'::jsonb;
  v_deadlines JSONB := '[]'::jsonb;
  v_threats JSONB := '[]'::jsonb;
  v_key TEXT;
  v_entry JSONB;
  v_vis TEXT;
BEGIN
  IF p_shared IS NULL OR NOT (p_shared ? 'adventure') THEN
    RETURN COALESCE(p_shared, '{}'::jsonb);
  END IF;
  IF p_is_gm THEN
    RETURN p_shared;
  END IF;
  v_adv := p_shared->'adventure';
  IF jsonb_typeof(v_adv) <> 'object' THEN
    RETURN p_shared - 'adventure';
  END IF;

  FOR v_key, v_entry IN SELECT * FROM jsonb_each(COALESCE(v_adv->'flags', '{}'::jsonb))
  LOOP
    v_vis := COALESCE(v_entry->>'visibility', 'gm_only');
    IF v_vis IN ('public', 'shared') THEN
      v_flags := jsonb_set(v_flags, ARRAY[v_key], v_entry, true);
    END IF;
  END LOOP;

  FOR v_key, v_entry IN SELECT * FROM jsonb_each(COALESCE(v_adv->'relationships', '{}'::jsonb))
  LOOP
    v_vis := COALESCE(v_entry->>'visibility', 'gm_only');
    IF v_vis IN ('public', 'shared') THEN
      v_rels := jsonb_set(v_rels, ARRAY[v_key], v_entry, true);
    END IF;
  END LOOP;

  FOR v_key, v_entry IN SELECT * FROM jsonb_each(COALESCE(v_adv->'clocks', '{}'::jsonb))
  LOOP
    v_vis := COALESCE(v_entry->>'visibility', 'gm_only');
    IF v_vis IN ('public', 'shared') THEN
      v_clocks := jsonb_set(v_clocks, ARRAY[v_key], v_entry, true);
    END IF;
  END LOOP;

  SELECT COALESCE(jsonb_agg(elem), '[]'::jsonb)
    INTO v_cons
    FROM jsonb_array_elements(COALESCE(v_adv->'consequences', '[]'::jsonb)) AS elem
   WHERE COALESCE(elem->>'visibility', 'gm_only') IN ('public', 'shared');

  SELECT COALESCE(jsonb_agg(elem), '[]'::jsonb)
    INTO v_deadlines
    FROM jsonb_array_elements(COALESCE(v_adv->'deadlines', '[]'::jsonb)) AS elem
   WHERE COALESCE(elem->>'visibility', 'gm_only') IN ('public', 'shared');

  SELECT COALESCE(jsonb_agg(elem), '[]'::jsonb)
    INTO v_threats
    FROM jsonb_array_elements(COALESCE(v_adv->'threats', '[]'::jsonb)) AS elem
   WHERE COALESCE(elem->>'visibility', 'gm_only') IN ('public', 'shared');

  v_adv := jsonb_set(v_adv, '{flags}', v_flags, true);
  v_adv := jsonb_set(v_adv, '{relationships}', v_rels, true);
  v_adv := jsonb_set(v_adv, '{clocks}', v_clocks, true);
  v_adv := jsonb_set(v_adv, '{consequences}', v_cons, true);
  v_adv := jsonb_set(v_adv, '{deadlines}', v_deadlines, true);
  v_adv := jsonb_set(v_adv, '{threats}', v_threats, true);
  RETURN jsonb_set(p_shared, '{adventure}', v_adv, true);
END;
$function$

CREATE OR REPLACE FUNCTION public.sagatree_project_shared_knowledge(p_shared jsonb, p_is_gm boolean, p_character_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
AS $function$
DECLARE
  v_knowledge JSONB;
  v_facts JSONB := '[]'::jsonb;
  v_fact JSONB;
  v_out JSONB;
  v_vis TEXT;
  v_body_allowed BOOLEAN;
  v_revealed BOOLEAN;
  v_i INT;
  v_reveals JSONB;
  v_r JSONB;
  v_j INT;
  v_char TEXT;
BEGIN
  IF p_shared IS NULL OR NOT (p_shared ? 'knowledge') THEN
    RETURN COALESCE(p_shared, '{}'::jsonb);
  END IF;
  IF p_is_gm THEN
    RETURN p_shared;
  END IF;

  v_knowledge := p_shared->'knowledge';
  IF jsonb_typeof(v_knowledge) <> 'object' THEN
    RETURN p_shared - 'knowledge';
  END IF;

  v_reveals := COALESCE(v_knowledge->'reveals', '[]'::jsonb);
  v_char := CASE WHEN p_character_id IS NULL THEN NULL ELSE p_character_id::text END;

  IF jsonb_typeof(v_knowledge->'facts') = 'array' THEN
    FOR v_i IN 0 .. GREATEST(jsonb_array_length(v_knowledge->'facts') - 1, -1) LOOP
      v_fact := v_knowledge->'facts'->v_i;
      v_vis := COALESCE(v_fact->>'visibility', 'gm_only');
      v_revealed := FALSE;
      IF jsonb_typeof(v_reveals) = 'array' THEN
        FOR v_j IN 0 .. GREATEST(jsonb_array_length(v_reveals) - 1, -1) LOOP
          v_r := v_reveals->v_j;
          IF v_r->>'factId' = v_fact->>'id' THEN
            IF v_r->'target'->>'kind' IN ('everyone', 'program', 'players') THEN
              v_revealed := TRUE;
            ELSIF v_r->'target'->>'kind' = 'character'
              AND v_char IS NOT NULL
              AND v_r->'target'->>'characterId' = v_char THEN
              v_revealed := TRUE;
            END IF;
          END IF;
        END LOOP;
      END IF;

      v_body_allowed := FALSE;
      IF v_vis = 'public' OR v_vis = 'program' THEN
        v_body_allowed := TRUE;
      ELSIF v_vis = 'discovered' AND (
        v_revealed OR EXISTS (
          SELECT 1 FROM jsonb_array_elements(COALESCE(v_knowledge->'discoveries', '[]'::jsonb)) d
          WHERE d->>'factId' = v_fact->>'id'
        )
      ) THEN
        v_body_allowed := TRUE;
      ELSIF v_vis = 'character_specific' AND v_char IS NOT NULL AND v_fact->>'characterId' = v_char THEN
        v_body_allowed := TRUE;
      ELSIF v_vis = 'gm_only' AND v_revealed THEN
        v_body_allowed := TRUE;
      END IF;

      -- Hide gm_only facts entirely until revealed.
      IF v_vis = 'gm_only' AND NOT v_revealed THEN
        CONTINUE;
      END IF;
      IF v_vis = 'character_specific' AND (v_char IS NULL OR v_fact->>'characterId' IS DISTINCT FROM v_char) AND NOT v_revealed THEN
        CONTINUE;
      END IF;

      IF NOT v_body_allowed THEN
        v_fact := jsonb_set(v_fact, '{body}', 'null'::jsonb, true);
        v_fact := jsonb_set(v_fact, '{handoutRef}', 'null'::jsonb, true);
      END IF;
      v_facts := v_facts || jsonb_build_array(v_fact);
    END LOOP;
  END IF;

  v_out := jsonb_set(v_knowledge, '{facts}', v_facts, true);
  RETURN jsonb_set(p_shared, '{knowledge}', v_out, true);
END;
$function$

CREATE OR REPLACE FUNCTION public.sagatree_resolve_adventure_command(p_session_id uuid, p_payload jsonb, p_is_gm boolean, p_world jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_in JSONB := COALESCE(p_payload, '{}'::jsonb);
  v_world JSONB := COALESCE(p_world, '{}'::jsonb);
  v_shared JSONB := COALESCE(v_world->'shared', '{}'::jsonb);
  v_op TEXT;
  v_adv JSONB;
  v_project UUID;
  v_project_adv JSONB;
  v_key TEXT;
  v_value JSONB;
  v_vis TEXT;
  v_flags JSONB;
  v_clocks JSONB;
  v_clock JSONB;
  v_clock_id TEXT;
  v_max INT;
  v_val INT;
  v_delta INT;
  v_rel JSONB;
  v_rel_id TEXT;
  v_cons JSONB;
  v_id TEXT;
  v_event JSONB;
  v_rev INT;
  v_schema INT;
  v_patch JSONB;
  v_days INT;
  v_loc TEXT;
  v_cons_elem JSONB;
  v_batch_count INT;
BEGIN
  IF NOT p_is_gm THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  IF jsonb_typeof(v_shared) IS DISTINCT FROM 'object' THEN
    v_shared := '{}'::jsonb;
  END IF;

  v_op := NULLIF(BTRIM(COALESCE(v_in->>'op', '')), '');
  IF v_op IS NULL AND NULLIF(BTRIM(COALESCE(v_in->>'key', '')), '') IS NOT NULL THEN
    v_op := 'set_flag';
  END IF;
  IF v_op IS NULL THEN
    RAISE EXCEPTION 'Adventure-op erforderlich' USING ERRCODE = '22023';
  END IF;

  SELECT project_id INTO v_project FROM public.sessions WHERE id = p_session_id;
  IF v_project IS NULL THEN
    RAISE EXCEPTION 'Session not found' USING ERRCODE = 'P0002';
  END IF;
  SELECT COALESCE(adventure_runtime, '{}'::jsonb) INTO v_project_adv
  FROM public.projects WHERE id = v_project;

  v_adv := COALESCE(v_shared->'adventure', public.sagatree_empty_adventure_runtime());
  IF jsonb_typeof(v_adv) IS DISTINCT FROM 'object' THEN
    v_adv := public.sagatree_empty_adventure_runtime();
  END IF;
  v_schema := COALESCE((v_adv->>'schemaVersion')::int, 0);
  IF v_schema NOT IN (1, 2) THEN
    v_adv := public.sagatree_empty_adventure_runtime() || jsonb_build_object(
      'definitionRef', v_adv->'definitionRef'
    );
    v_schema := 1;
  END IF;

  IF v_op = 'hydrate_from_project' THEN
    IF jsonb_typeof(v_project_adv) = 'object'
       AND COALESCE((v_project_adv->>'schemaVersion')::int, 0) IN (1, 2) THEN
      v_adv := v_project_adv;
    ELSE
      v_adv := public.sagatree_empty_adventure_runtime();
    END IF;
  ELSIF v_op = 'set_definition_ref' THEN
    IF NULLIF(BTRIM(COALESCE(v_in->>'definitionRef', '')), '') IS NULL THEN
      RAISE EXCEPTION 'definitionRef erforderlich' USING ERRCODE = '22023';
    END IF;
    v_adv := jsonb_set(v_adv, '{definitionRef}', to_jsonb(left(v_in->>'definitionRef', 120)), true);
  ELSIF v_op = 'set_flag' THEN
    v_key := NULLIF(BTRIM(COALESCE(v_in->>'key', '')), '');
    IF v_key IS NULL THEN
      RAISE EXCEPTION 'key erforderlich' USING ERRCODE = '22023';
    END IF;
    v_key := left(v_key, 64);
    v_vis := COALESCE(NULLIF(BTRIM(COALESCE(v_in->>'visibility', '')), ''), 'shared');
    IF v_vis NOT IN ('public', 'shared', 'gm_only') THEN
      v_vis := 'shared';
    END IF;
    IF v_in ? 'value' THEN
      v_value := v_in->'value';
    ELSE
      v_value := 'true'::jsonb;
    END IF;
    v_flags := COALESCE(v_adv->'flags', '{}'::jsonb);
    v_flags := jsonb_set(
      v_flags,
      ARRAY[v_key],
      jsonb_build_object(
        'key', v_key,
        'value', v_value,
        'visibility', v_vis,
        'updatedAt', NOW()
      ),
      true
    );
    v_adv := jsonb_set(v_adv, '{flags}', v_flags, true);
  ELSIF v_op = 'set_relationship' THEN
    IF NULLIF(BTRIM(COALESCE(v_in->>'actorRef', '')), '') IS NULL
       OR NULLIF(BTRIM(COALESCE(v_in->>'targetRef', '')), '') IS NULL THEN
      RAISE EXCEPTION 'actorRef und targetRef erforderlich' USING ERRCODE = '22023';
    END IF;
    v_rel_id := left((v_in->>'actorRef') || '->' || (v_in->>'targetRef'), 64);
    v_vis := COALESCE(NULLIF(BTRIM(COALESCE(v_in->>'visibility', '')), ''), 'gm_only');
    IF v_vis NOT IN ('public', 'shared', 'gm_only') THEN
      v_vis := 'gm_only';
    END IF;
    v_rel := COALESCE(v_adv->'relationships', '{}'::jsonb);
    v_rel := jsonb_set(
      v_rel,
      ARRAY[v_rel_id],
      jsonb_build_object(
        'actorRef', left(v_in->>'actorRef', 80),
        'targetRef', left(v_in->>'targetRef', 80),
        'score', GREATEST(-100, LEAST(100, COALESCE((v_in->>'score')::int, 0))),
        'note', left(COALESCE(v_in->>'note', ''), 200),
        'visibility', v_vis
      ),
      true
    );
    v_adv := jsonb_set(v_adv, '{relationships}', v_rel, true);
  ELSIF v_op = 'tick_clock' THEN
    v_clock_id := left(COALESCE(NULLIF(BTRIM(COALESCE(v_in->>'clockId', '')), ''), 'danger'), 64);
    v_clocks := COALESCE(v_adv->'clocks', '{}'::jsonb);
    v_clock := COALESCE(v_clocks->v_clock_id, '{}'::jsonb);
    v_max := GREATEST(1, LEAST(12, COALESCE((v_in->>'clockMax')::int, (v_clock->>'max')::int, 4)));
    v_delta := COALESCE((v_in->>'clockDelta')::int, 1);
    v_val := GREATEST(0, LEAST(v_max, COALESCE((v_clock->>'value')::int, 0) + v_delta));
    v_vis := COALESCE(NULLIF(BTRIM(COALESCE(v_in->>'visibility', '')), ''), COALESCE(v_clock->>'visibility', 'shared'));
    IF v_vis NOT IN ('public', 'shared', 'gm_only') THEN
      v_vis := 'shared';
    END IF;
    v_clocks := jsonb_set(
      v_clocks,
      ARRAY[v_clock_id],
      jsonb_build_object(
        'id', v_clock_id,
        'label', left(COALESCE(NULLIF(BTRIM(COALESCE(v_in->>'clockLabel', '')), ''), v_clock->>'label', v_clock_id), 80),
        'value', v_val,
        'max', v_max,
        'visibility', v_vis
      ),
      true
    );
    v_adv := jsonb_set(v_adv, '{clocks}', v_clocks, true);
  ELSIF v_op = 'add_consequence' THEN
    IF NULLIF(BTRIM(COALESCE(v_in->>'summary', '')), '') IS NULL THEN
      RAISE EXCEPTION 'summary erforderlich' USING ERRCODE = '22023';
    END IF;
    v_vis := COALESCE(NULLIF(BTRIM(COALESCE(v_in->>'visibility', '')), ''), 'shared');
    IF v_vis NOT IN ('public', 'shared', 'gm_only') THEN
      v_vis := 'shared';
    END IF;
    v_id := 'c-' || substr(replace(gen_random_uuid()::text, '-', ''), 1, 12);
    v_cons := COALESCE(v_adv->'consequences', '[]'::jsonb);
    IF jsonb_typeof(v_cons) IS DISTINCT FROM 'array' THEN
      v_cons := '[]'::jsonb;
    END IF;
    v_cons := v_cons || jsonb_build_array(jsonb_build_object(
      'id', v_id,
      'kind', left(COALESCE(NULLIF(BTRIM(COALESCE(v_in->>'consequenceKind', '')), ''), 'generic'), 40),
      'summary', left(v_in->>'summary', 200),
      'visibility', v_vis,
      'createdAt', NOW()
    ));
    IF jsonb_array_length(v_cons) > 64 THEN
      v_cons := (
        SELECT COALESCE(jsonb_agg(elem), '[]'::jsonb)
        FROM (
          SELECT elem FROM jsonb_array_elements(v_cons) AS elem
          OFFSET GREATEST(jsonb_array_length(v_cons) - 64, 0)
        ) s
      );
    END IF;
    v_adv := jsonb_set(v_adv, '{consequences}', v_cons, true);
  ELSIF v_op = 'persist_to_project' THEN
    NULL;
  ELSIF v_op IN ('advance_time', 'apply_simulation_batch') THEN
    -- Client preview (pure kernel); server validates + persists patch only.
    v_days := COALESCE((v_in->>'days')::int, 0);
    IF v_op = 'advance_time' AND (v_days < 1 OR v_days > 30) THEN
      RAISE EXCEPTION 'days muss zwischen 1 und 30 liegen' USING ERRCODE = '22023';
    END IF;
    v_patch := v_in->'simulationPatch';
    IF jsonb_typeof(v_patch) IS DISTINCT FROM 'object' THEN
      RAISE EXCEPTION 'simulationPatch erforderlich' USING ERRCODE = '22023';
    END IF;
    -- Reject unknown top-level patch keys
    IF EXISTS (
      SELECT 1 FROM jsonb_object_keys(v_patch) k
      WHERE k NOT IN ('time', 'clocks', 'threats', 'deadlines', 'flags', 'rngSeed', 'partyLocationRef', 'rules')
    ) THEN
      RAISE EXCEPTION 'simulationPatch enthält unbekannte Felder' USING ERRCODE = '22023';
    END IF;
    v_adv := public.sagatree_ensure_adventure_v2(v_adv);
    IF v_patch ? 'time' AND jsonb_typeof(v_patch->'time') = 'object' THEN
      v_adv := jsonb_set(
        v_adv,
        '{time}',
        jsonb_build_object(
          'day', GREATEST(0, LEAST(9999, COALESCE((v_patch->'time'->>'day')::int, 0)))
        ),
        true
      );
    END IF;
    IF v_patch ? 'clocks' AND jsonb_typeof(v_patch->'clocks') = 'object' THEN
      v_adv := jsonb_set(v_adv, '{clocks}', v_patch->'clocks', true);
    END IF;
    IF v_patch ? 'threats' AND jsonb_typeof(v_patch->'threats') = 'array' THEN
      IF jsonb_array_length(v_patch->'threats') > 64 THEN
        RAISE EXCEPTION 'threats zu groß' USING ERRCODE = '22023';
      END IF;
      v_adv := jsonb_set(v_adv, '{threats}', v_patch->'threats', true);
    END IF;
    IF v_patch ? 'deadlines' AND jsonb_typeof(v_patch->'deadlines') = 'array' THEN
      IF jsonb_array_length(v_patch->'deadlines') > 64 THEN
        RAISE EXCEPTION 'deadlines zu groß' USING ERRCODE = '22023';
      END IF;
      v_adv := jsonb_set(v_adv, '{deadlines}', v_patch->'deadlines', true);
    END IF;
    IF v_patch ? 'flags' AND jsonb_typeof(v_patch->'flags') = 'object' THEN
      v_adv := jsonb_set(v_adv, '{flags}', v_patch->'flags', true);
    END IF;
    IF v_patch ? 'rngSeed' THEN
      v_adv := jsonb_set(v_adv, '{rngSeed}', to_jsonb(COALESCE((v_patch->>'rngSeed')::bigint, 0)), true);
    END IF;
    IF v_patch ? 'partyLocationRef' THEN
      v_adv := jsonb_set(
        v_adv,
        '{partyLocationRef}',
        CASE
          WHEN v_patch->>'partyLocationRef' IS NULL OR BTRIM(v_patch->>'partyLocationRef') = '' THEN 'null'::jsonb
          ELSE to_jsonb(left(v_patch->>'partyLocationRef', 80))
        END,
        true
      );
    END IF;
    -- Append consequences from approved preview (batch size limit)
    IF jsonb_typeof(v_in->'appendConsequences') = 'array' THEN
      v_batch_count := jsonb_array_length(v_in->'appendConsequences');
      IF v_batch_count > 32 THEN
        RAISE EXCEPTION 'appendConsequences zu groß' USING ERRCODE = '22023';
      END IF;
      v_cons := COALESCE(v_adv->'consequences', '[]'::jsonb);
      IF jsonb_typeof(v_cons) IS DISTINCT FROM 'array' THEN
        v_cons := '[]'::jsonb;
      END IF;
      FOR v_cons_elem IN SELECT elem FROM jsonb_array_elements(v_in->'appendConsequences') AS elem
      LOOP
        IF NULLIF(BTRIM(COALESCE(v_cons_elem->>'summary', '')), '') IS NULL THEN
          CONTINUE;
        END IF;
        v_vis := COALESCE(NULLIF(BTRIM(COALESCE(v_cons_elem->>'visibility', '')), ''), 'gm_only');
        IF v_vis NOT IN ('public', 'shared', 'gm_only') THEN
          v_vis := 'gm_only';
        END IF;
        v_id := 'c-' || substr(replace(gen_random_uuid()::text, '-', ''), 1, 12);
        v_cons := v_cons || jsonb_build_array(jsonb_build_object(
          'id', v_id,
          'kind', left(COALESCE(NULLIF(BTRIM(COALESCE(v_cons_elem->>'kind', '')), ''), 'sim'), 40),
          'summary', left(v_cons_elem->>'summary', 200),
          'visibility', v_vis,
          'createdAt', NOW()
        ));
      END LOOP;
      IF jsonb_array_length(v_cons) > 64 THEN
        v_cons := (
          SELECT COALESCE(jsonb_agg(elem), '[]'::jsonb)
          FROM (
            SELECT elem FROM jsonb_array_elements(v_cons) AS elem
            OFFSET GREATEST(jsonb_array_length(v_cons) - 64, 0)
          ) s
        );
      END IF;
      v_adv := jsonb_set(v_adv, '{consequences}', v_cons, true);
    END IF;
    v_schema := 2;
  ELSIF v_op = 'set_party_location' THEN
    v_loc := NULLIF(BTRIM(COALESCE(v_in->>'locationRef', '')), '');
    IF v_loc IS NULL THEN
      RAISE EXCEPTION 'locationRef erforderlich' USING ERRCODE = '22023';
    END IF;
    v_adv := public.sagatree_ensure_adventure_v2(v_adv);
    v_adv := jsonb_set(v_adv, '{partyLocationRef}', to_jsonb(left(v_loc, 80)), true);
    v_schema := 2;
  ELSE
    RAISE EXCEPTION 'Unbekannte Adventure-Operation' USING ERRCODE = '22023';
  END IF;

  v_rev := GREATEST(0, COALESCE((v_adv->>'sliceRevision')::int, 0)) + 1;
  IF v_op IN ('advance_time', 'apply_simulation_batch', 'set_party_location') OR v_schema = 2 THEN
    v_adv := jsonb_set(v_adv, '{schemaVersion}', '2'::jsonb, true);
  ELSE
    v_adv := jsonb_set(v_adv, '{schemaVersion}', to_jsonb(COALESCE((v_adv->>'schemaVersion')::int, 1)), true);
  END IF;
  v_adv := jsonb_set(v_adv, '{sliceRevision}', to_jsonb(v_rev), true);
  v_adv := jsonb_set(v_adv, '{updatedAt}', to_jsonb(NOW()), true);

  v_shared := jsonb_set(v_shared, '{adventure}', v_adv, true);
  v_world := jsonb_set(v_world, '{shared}', v_shared, true);

  IF v_op IS DISTINCT FROM 'hydrate_from_project' OR v_in->>'forcePersist' = 'true' THEN
    IF v_op IN (
      'set_flag', 'set_relationship', 'tick_clock', 'add_consequence',
      'set_definition_ref', 'persist_to_project',
      'advance_time', 'apply_simulation_batch', 'set_party_location'
    ) THEN
      UPDATE public.projects
         SET adventure_runtime = v_adv,
             updated_at = NOW()
       WHERE id = v_project;
    END IF;
  END IF;

  v_event := jsonb_build_object(
    'op', v_op,
    'key', v_in->>'key',
    'batchId', v_in->>'batchId',
    'days', v_in->'days',
    'definitionRef', v_adv->>'definitionRef',
    'sliceRevision', v_rev,
    'authoritative', true
  );
  RETURN jsonb_build_object('worldState', v_world, 'eventPayload', v_event);
END;
$function$

CREATE OR REPLACE FUNCTION public.sagatree_resolve_combat_command(p_session_id uuid, p_actor uuid, p_payload jsonb, p_is_gm boolean, p_world jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_in JSONB := public.sagatree_strip_forged_encounter_keys(p_payload);
  v_action TEXT := NULLIF(BTRIM(COALESCE(v_in->>'action', '')), '');
  v_world JSONB := COALESCE(p_world, '{}'::jsonb);
  v_shared JSONB := COALESCE(v_world->'shared', '{}'::jsonb);
  v_encounter JSONB;
  v_participants JSONB := '[]'::jsonb;
  v_seed JSONB;
  v_kind TEXT;
  v_ref TEXT;
  v_char public.characters;
  v_npc public.npc_creature_instances;
  v_built JSONB;
  v_session public.sessions;
  v_i INT;
  v_len INT;
  v_participant JSONB;
  v_slot TEXT;
  v_pid TEXT;
  v_actions JSONB;
  v_count INT;
  v_event JSONB;
BEGIN
  IF jsonb_typeof(v_shared) IS DISTINCT FROM 'object' THEN
    v_shared := '{}'::jsonb;
  END IF;
  v_encounter := COALESCE(v_shared->'encounter', '{}'::jsonb);

  IF v_action = 'start' THEN
    IF NOT p_is_gm THEN
      RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
    END IF;
    IF COALESCE(v_encounter->>'status', '') = 'active' THEN
      RAISE EXCEPTION 'Encounter bereits aktiv' USING ERRCODE = '22023';
    END IF;
    IF jsonb_typeof(v_in->'participants') IS DISTINCT FROM 'array'
       OR jsonb_array_length(v_in->'participants') < 1 THEN
      RAISE EXCEPTION 'Encounter-Start benötigt Teilnehmer' USING ERRCODE = '22023';
    END IF;

    SELECT * INTO v_session FROM public.sessions WHERE id = p_session_id;

    FOR v_i IN 0 .. LEAST(jsonb_array_length(v_in->'participants'), 24) - 1 LOOP
      v_seed := v_in->'participants'->v_i;
      v_kind := NULLIF(BTRIM(COALESCE(v_seed->>'kind', '')), '');
      v_ref := NULLIF(BTRIM(COALESCE(
        v_seed->>'refId',
        COALESCE(v_seed->>'characterId', v_seed->>'instanceId')
      )), '');
      IF v_kind IS NULL OR v_ref IS NULL THEN
        CONTINUE;
      END IF;

      IF v_kind = 'pc' THEN
        BEGIN
          SELECT * INTO v_char FROM public.characters WHERE id = v_ref::uuid;
        EXCEPTION WHEN others THEN
          RAISE EXCEPTION 'Ungültige Charakter-ID' USING ERRCODE = '22023';
        END;
        IF NOT FOUND THEN
          RAISE EXCEPTION 'Charakter nicht gefunden' USING ERRCODE = 'P0002';
        END IF;
        v_built := public.sagatree_build_encounter_participant_pc(v_char);
        IF NULLIF(BTRIM(COALESCE(v_seed->>'name', '')), '') IS NOT NULL THEN
          v_built := jsonb_set(v_built, '{name}', to_jsonb(left(BTRIM(v_seed->>'name'), 120)), true);
        END IF;
        v_participants := v_participants || jsonb_build_array(v_built);
      ELSIF v_kind = 'npc' THEN
        BEGIN
          SELECT * INTO v_npc FROM public.npc_creature_instances WHERE id = v_ref::uuid;
        EXCEPTION WHEN others THEN
          RAISE EXCEPTION 'Ungültige Instanz-ID' USING ERRCODE = '22023';
        END;
        IF NOT FOUND THEN
          RAISE EXCEPTION 'NPC-Instanz nicht gefunden' USING ERRCODE = 'P0002';
        END IF;
        IF v_npc.project_id IS DISTINCT FROM v_session.project_id THEN
          RAISE EXCEPTION 'NPC-Instanz gehört nicht zu diesem Abenteuer' USING ERRCODE = '42501';
        END IF;
        v_built := public.sagatree_build_encounter_participant_npc(v_npc);
        IF NULLIF(BTRIM(COALESCE(v_seed->>'name', '')), '') IS NOT NULL THEN
          v_built := jsonb_set(v_built, '{name}', to_jsonb(left(BTRIM(v_seed->>'name'), 120)), true);
        END IF;
        v_participants := v_participants || jsonb_build_array(v_built);
      END IF;
    END LOOP;

    IF jsonb_array_length(v_participants) < 1 THEN
      RAISE EXCEPTION 'Keine gültigen Teilnehmer' USING ERRCODE = '22023';
    END IF;

    v_participants := public.sagatree_sort_encounter_participants(v_participants);
    v_encounter := jsonb_build_object(
      'schemaVersion', 1,
      'status', 'active',
      'round', 1,
      'currentTurnIndex', 0,
      'participants', v_participants,
      'authoritative', true
    );
    v_shared := jsonb_set(v_shared, '{encounter}', v_encounter, true);
    v_world := jsonb_set(v_world, '{shared}', v_shared, true);
    v_world := jsonb_set(v_world, '{combatActive}', 'true'::jsonb, true);
    v_event := jsonb_build_object(
      'action', 'start',
      'round', 1,
      'participantCount', jsonb_array_length(v_participants),
      'authoritative', true
    );
    RETURN jsonb_build_object('worldState', v_world, 'eventPayload', v_event);
  END IF;

  IF v_action = 'end' THEN
    IF NOT p_is_gm THEN
      RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
    END IF;
    IF COALESCE(v_encounter->>'status', '') IS DISTINCT FROM 'active' THEN
      RAISE EXCEPTION 'Kein aktiver Encounter' USING ERRCODE = '22023';
    END IF;
    v_encounter := jsonb_set(v_encounter, '{status}', '"ended"'::jsonb, true);
    v_shared := jsonb_set(v_shared, '{encounter}', v_encounter, true);
    v_world := jsonb_set(v_world, '{shared}', v_shared, true);
    v_world := jsonb_set(v_world, '{combatActive}', 'false'::jsonb, true);
    v_event := jsonb_build_object('action', 'end', 'authoritative', true);
    RETURN jsonb_build_object('worldState', v_world, 'eventPayload', v_event);
  END IF;

  IF v_action = 'nextTurn' THEN
    IF NOT p_is_gm THEN
      RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
    END IF;
    IF COALESCE(v_encounter->>'status', '') IS DISTINCT FROM 'active' THEN
      RAISE EXCEPTION 'Kein aktiver Encounter' USING ERRCODE = '22023';
    END IF;
    v_participants := COALESCE(v_encounter->'participants', '[]'::jsonb);
    v_len := jsonb_array_length(v_participants);
    IF v_len < 1 THEN
      RAISE EXCEPTION 'Encounter ohne Teilnehmer' USING ERRCODE = '22023';
    END IF;
    v_i := COALESCE((v_encounter->>'currentTurnIndex')::int, 0);
    v_i := (v_i + 1) % v_len;
    IF v_i = 0 THEN
      v_encounter := jsonb_set(
        v_encounter,
        '{round}',
        to_jsonb(COALESCE((v_encounter->>'round')::int, 1) + 1),
        true
      );
    END IF;
    v_encounter := jsonb_set(v_encounter, '{currentTurnIndex}', to_jsonb(v_i), true);
    -- Refresh action economy for the actor whose turn begins
    v_participant := v_participants->v_i;
    v_participant := jsonb_set(v_participant, '{actions}', public.sagatree_fresh_action_economy(), true);
    v_participants := jsonb_set(v_participants, ARRAY[v_i::text], v_participant, true);
    v_encounter := jsonb_set(v_encounter, '{participants}', v_participants, true);
    v_shared := jsonb_set(v_shared, '{encounter}', v_encounter, true);
    v_world := jsonb_set(v_world, '{shared}', v_shared, true);
    v_event := jsonb_build_object(
      'action', 'nextTurn',
      'round', (v_encounter->>'round')::int,
      'currentTurnIndex', v_i,
      'currentParticipantId', v_participant->>'id',
      'authoritative', true
    );
    RETURN jsonb_build_object('worldState', v_world, 'eventPayload', v_event);
  END IF;

  IF v_action = 'spendAction' THEN
    IF COALESCE(v_encounter->>'status', '') IS DISTINCT FROM 'active' THEN
      RAISE EXCEPTION 'Kein aktiver Encounter' USING ERRCODE = '22023';
    END IF;
    v_pid := NULLIF(BTRIM(COALESCE(v_in->>'participantId', '')), '');
    v_slot := NULLIF(BTRIM(COALESCE(v_in->>'slot', '')), '');
    IF v_pid IS NULL OR v_slot IS NULL OR v_slot NOT IN ('main', 'move', 'free', 'reaction') THEN
      RAISE EXCEPTION 'spendAction benötigt participantId und Slot' USING ERRCODE = '22023';
    END IF;
    v_participants := COALESCE(v_encounter->'participants', '[]'::jsonb);
    v_len := jsonb_array_length(v_participants);
    v_i := COALESCE((v_encounter->>'currentTurnIndex')::int, 0);
    v_participant := NULL;
    FOR v_count IN 0 .. v_len - 1 LOOP
      IF (v_participants->v_count->>'id') = v_pid THEN
        v_participant := v_participants->v_count;
        v_i := v_count;
        EXIT;
      END IF;
    END LOOP;
    IF v_participant IS NULL THEN
      RAISE EXCEPTION 'Teilnehmer nicht gefunden' USING ERRCODE = 'P0002';
    END IF;
    -- Only current turn actor (PC owner) or GM may spend
    IF NOT p_is_gm THEN
      IF COALESCE((v_encounter->>'currentTurnIndex')::int, 0) IS DISTINCT FROM v_i THEN
        RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
      END IF;
      IF v_participant->>'kind' = 'pc' THEN
        SELECT * INTO v_char FROM public.characters WHERE id = (v_participant->>'refId')::uuid;
        IF NOT FOUND OR v_char.owner_user_id IS DISTINCT FROM p_actor THEN
          RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
        END IF;
      ELSE
        RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
      END IF;
    END IF;
    v_actions := COALESCE(v_participant->'actions', public.sagatree_fresh_action_economy());
    v_count := COALESCE((v_actions->>v_slot)::int, 0);
    IF v_count < 1 THEN
      RAISE EXCEPTION 'Keine Aktion mehr verfügbar' USING ERRCODE = '22023';
    END IF;
    v_actions := jsonb_set(v_actions, ARRAY[v_slot], to_jsonb(v_count - 1), true);
    v_participant := jsonb_set(v_participant, '{actions}', v_actions, true);
    v_participants := jsonb_set(v_participants, ARRAY[v_i::text], v_participant, true);
    v_encounter := jsonb_set(v_encounter, '{participants}', v_participants, true);
    v_shared := jsonb_set(v_shared, '{encounter}', v_encounter, true);
    v_world := jsonb_set(v_world, '{shared}', v_shared, true);
    v_event := jsonb_build_object(
      'action', 'spendAction',
      'participantId', v_pid,
      'slot', v_slot,
      'authoritative', true
    );
    RETURN jsonb_build_object('worldState', v_world, 'eventPayload', v_event);
  END IF;

  RAISE EXCEPTION 'Unbekannte Combat-Aktion' USING ERRCODE = '22023';
END;
$function$

CREATE OR REPLACE FUNCTION public.sagatree_resolve_condition_command(p_payload jsonb, p_is_gm boolean, p_world jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_in JSONB := public.sagatree_strip_forged_encounter_keys(p_payload);
  v_world JSONB := COALESCE(p_world, '{}'::jsonb);
  v_shared JSONB := COALESCE(v_world->'shared', '{}'::jsonb);
  v_encounter JSONB;
  v_participants JSONB;
  v_pid TEXT;
  v_op TEXT;
  v_condition TEXT;
  v_i INT;
  v_len INT;
  v_participant JSONB;
  v_conditions JSONB;
  v_event JSONB;
  v_has BOOLEAN;
BEGIN
  IF NOT p_is_gm THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  IF jsonb_typeof(v_shared) IS DISTINCT FROM 'object' THEN
    v_shared := '{}'::jsonb;
  END IF;
  v_encounter := COALESCE(v_shared->'encounter', '{}'::jsonb);
  IF COALESCE(v_encounter->>'status', '') IS DISTINCT FROM 'active' THEN
    RAISE EXCEPTION 'Kein aktiver Encounter' USING ERRCODE = '22023';
  END IF;

  v_pid := NULLIF(BTRIM(COALESCE(v_in->>'participantId', '')), '');
  v_op := COALESCE(NULLIF(BTRIM(COALESCE(v_in->>'op', '')), ''), 'add');
  v_condition := left(NULLIF(BTRIM(COALESCE(v_in->>'condition', '')), ''), 80);
  IF v_pid IS NULL OR v_condition IS NULL OR v_op NOT IN ('add', 'remove') THEN
    RAISE EXCEPTION 'Zustand benötigt participantId, op und condition' USING ERRCODE = '22023';
  END IF;

  v_participants := COALESCE(v_encounter->'participants', '[]'::jsonb);
  v_len := jsonb_array_length(v_participants);
  v_participant := NULL;
  FOR v_i IN 0 .. v_len - 1 LOOP
    IF (v_participants->v_i->>'id') = v_pid THEN
      v_participant := v_participants->v_i;
      EXIT;
    END IF;
  END LOOP;
  IF v_participant IS NULL THEN
    RAISE EXCEPTION 'Teilnehmer nicht gefunden' USING ERRCODE = 'P0002';
  END IF;

  v_conditions := COALESCE(v_participant->'conditions', '[]'::jsonb);
  SELECT EXISTS (
    SELECT 1 FROM jsonb_array_elements_text(v_conditions) AS c WHERE c = v_condition
  ) INTO v_has;

  IF v_op = 'add' AND NOT v_has AND jsonb_array_length(v_conditions) < 24 THEN
    v_conditions := v_conditions || to_jsonb(v_condition);
  ELSIF v_op = 'remove' THEN
    SELECT COALESCE(jsonb_agg(to_jsonb(c)), '[]'::jsonb)
      INTO v_conditions
      FROM jsonb_array_elements_text(COALESCE(v_participant->'conditions', '[]'::jsonb)) AS c
     WHERE c <> v_condition;
  END IF;

  v_participant := jsonb_set(v_participant, '{conditions}', v_conditions, true);
  FOR v_i IN 0 .. v_len - 1 LOOP
    IF (v_participants->v_i->>'id') = v_pid THEN
      v_participants := jsonb_set(v_participants, ARRAY[v_i::text], v_participant, true);
      EXIT;
    END IF;
  END LOOP;

  v_encounter := jsonb_set(v_encounter, '{participants}', v_participants, true);
  v_shared := jsonb_set(v_shared, '{encounter}', v_encounter, true);
  IF v_participant->>'kind' = 'pc' THEN
    v_shared := jsonb_set(
      v_shared,
      ARRAY['conditionsByCharacter', v_participant->>'refId'],
      v_conditions,
      true
    );
  END IF;
  v_world := jsonb_set(v_world, '{shared}', v_shared, true);
  PERFORM public.sagatree_sync_npc_instance_from_participant(v_participant);

  v_event := jsonb_build_object(
    'op', v_op,
    'participantId', v_pid,
    'condition', v_condition,
    'authoritative', true
  );
  RETURN jsonb_build_object('worldState', v_world, 'eventPayload', v_event);
END;
$function$

CREATE OR REPLACE FUNCTION public.sagatree_resolve_cue_command(p_payload jsonb, p_is_gm boolean, p_is_director boolean, p_world jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_in JSONB := COALESCE(p_payload, '{}'::jsonb);
  v_world JSONB := COALESCE(p_world, '{}'::jsonb);
  v_shared JSONB := COALESCE(v_world->'shared', '{}'::jsonb);
  v_op TEXT;
  v_dir JSONB;
  v_mode TEXT;
  v_trigger TEXT;
  v_manual BOOLEAN;
  v_source JSONB;
  v_layout JSONB;
  v_overlay TEXT;
  v_rev INT;
  v_cue JSONB;
  v_program JSONB;
  v_event JSONB;
  v_applied BOOLEAN := true;
  v_reason TEXT := NULL;
BEGIN
  IF NOT p_is_gm AND NOT p_is_director THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  IF jsonb_typeof(v_shared) IS DISTINCT FROM 'object' THEN
    v_shared := '{}'::jsonb;
  END IF;

  -- Reject secret bodies in cue payload
  IF v_in ? 'gm_only' OR v_in ? 'character_specific' THEN
    RAISE EXCEPTION 'Cue payload darf keine Secrets enthalten' USING ERRCODE = '22023';
  END IF;

  v_op := COALESCE(NULLIF(BTRIM(COALESCE(v_in->>'op', '')), ''), 'apply_cue');
  v_dir := COALESCE(v_shared->'director', jsonb_build_object(
    'schemaVersion', 1,
    'automaticMode', 'off',
    'preview', jsonb_build_object(
      'source', jsonb_build_object('kind', 'shared-scene'),
      'layout', jsonb_build_object('kind', 'fullscreen-16x9')
    ),
    'program', jsonb_build_object(
      'source', jsonb_build_object('kind', 'shared-scene'),
      'layout', jsonb_build_object('kind', 'fullscreen-16x9'),
      'revision', 0
    ),
    'lastCue', NULL,
    'lastManualOverrideAt', NULL,
    'cooldownMs', 1500,
    'lastAutoAppliedAt', NULL,
    'updatedAt', NULL
  ));

  IF v_op = 'set_automatic_mode' THEN
    v_mode := CASE WHEN v_in->>'mode' = 'on' THEN 'on' ELSE 'off' END;
    v_dir := jsonb_set(v_dir, '{automaticMode}', to_jsonb(v_mode), true);
    v_dir := jsonb_set(v_dir, '{updatedAt}', to_jsonb(NOW()), true);
    v_shared := jsonb_set(v_shared, '{director}', v_dir, true);
    v_world := jsonb_set(v_world, '{shared}', v_shared, true);
    RETURN jsonb_build_object(
      'worldState', v_world,
      'eventPayload', jsonb_build_object('op', v_op, 'mode', v_mode, 'authoritative', true)
    );
  END IF;

  IF v_op = 'set_preview' THEN
    v_source := COALESCE(v_in->'source', jsonb_build_object('kind', 'shared-scene'));
    v_layout := COALESCE(v_in->'layout', jsonb_build_object('kind', 'fullscreen-16x9'));
    v_dir := jsonb_set(
      v_dir,
      '{preview}',
      jsonb_build_object('source', v_source, 'layout', v_layout),
      true
    );
    v_dir := jsonb_set(v_dir, '{updatedAt}', to_jsonb(NOW()), true);
    v_shared := jsonb_set(v_shared, '{director}', v_dir, true);
    v_world := jsonb_set(v_world, '{shared}', v_shared, true);
    RETURN jsonb_build_object(
      'worldState', v_world,
      'eventPayload', jsonb_build_object('op', v_op, 'authoritative', true)
    );
  END IF;

  -- apply_cue / take_preview_to_program
  v_trigger := COALESCE(NULLIF(BTRIM(COALESCE(v_in->>'trigger', '')), ''), 'manual');
  v_manual := COALESCE((v_in->>'manual')::boolean, v_trigger = 'manual', true);

  IF v_op = 'take_preview_to_program' THEN
    v_source := COALESCE(v_dir->'preview'->'source', jsonb_build_object('kind', 'shared-scene'));
    v_layout := COALESCE(v_dir->'preview'->'layout', jsonb_build_object('kind', 'fullscreen-16x9'));
    v_trigger := 'manual';
    v_manual := true;
    v_overlay := NULL;
  ELSE
    IF NOT v_manual THEN
      IF COALESCE(v_dir->>'automaticMode', 'off') IS DISTINCT FROM 'on' THEN
        v_applied := false;
        v_reason := 'automatic_mode_off';
      ELSIF v_dir->>'lastAutoAppliedAt' IS NOT NULL
        AND (EXTRACT(EPOCH FROM (NOW() - (v_dir->>'lastAutoAppliedAt')::timestamptz)) * 1000)
            < COALESCE((v_dir->>'cooldownMs')::int, 1500) THEN
        v_applied := false;
        v_reason := 'cooldown';
      END IF;
    END IF;
    v_source := COALESCE(v_in->'source', jsonb_build_object('kind', 'shared-scene'));
    v_layout := COALESCE(v_in->'layout', jsonb_build_object('kind', 'fullscreen-16x9'));
    v_overlay := NULLIF(BTRIM(COALESCE(v_in->>'overlayText', v_in->>'note', '')), '');
  END IF;

  IF NOT v_applied THEN
    v_shared := jsonb_set(v_shared, '{director}', v_dir, true);
    v_world := jsonb_set(v_world, '{shared}', v_shared, true);
    RETURN jsonb_build_object(
      'worldState', v_world,
      'eventPayload', jsonb_build_object(
        'op', 'apply_cue',
        'applied', false,
        'reason', v_reason,
        'trigger', v_trigger,
        'authoritative', true
      )
    );
  END IF;

  v_rev := GREATEST(0, COALESCE((v_dir->'program'->>'revision')::int, 0)) + 1;
  v_cue := jsonb_build_object(
    'id', 'cue-' || substr(replace(gen_random_uuid()::text, '-', ''), 1, 10),
    'trigger', v_trigger,
    'source', v_source,
    'layout', v_layout,
    'overlayText', to_jsonb(v_overlay),
    'manual', v_manual,
    'appliedAt', NOW()
  );
  v_dir := jsonb_set(
    v_dir,
    '{program}',
    jsonb_build_object('source', v_source, 'layout', v_layout, 'revision', v_rev),
    true
  );
  v_dir := jsonb_set(v_dir, '{lastCue}', v_cue, true);
  IF v_manual THEN
    v_dir := jsonb_set(v_dir, '{lastManualOverrideAt}', to_jsonb(NOW()), true);
  ELSE
    v_dir := jsonb_set(v_dir, '{lastAutoAppliedAt}', to_jsonb(NOW()), true);
  END IF;
  v_dir := jsonb_set(v_dir, '{updatedAt}', to_jsonb(NOW()), true);

  -- Push presentation-safe programPresentation (no secrets)
  v_program := public.sagatree_build_program_presentation(
    jsonb_build_object(
      'source', CASE
        WHEN v_source->>'kind' = 'look' THEN v_source
        WHEN v_source->>'kind' = 'neutral' THEN jsonb_build_object('kind', 'neutral')
        ELSE jsonb_build_object('kind', 'shared-scene')
      END,
      'layout', CASE
        WHEN v_layout->>'kind' = 'letterbox' THEN jsonb_build_object('kind', 'letterbox')
        ELSE jsonb_build_object('kind', 'fullscreen-16x9')
      END,
      'overlay', CASE
        WHEN v_overlay IS NOT NULL THEN jsonb_build_object('kind', 'title', 'text', left(v_overlay, 120))
        ELSE NULL
      END
    ),
    COALESCE(v_shared->'programPresentation', NULL)
  );

  v_shared := jsonb_set(v_shared, '{director}', v_dir, true);
  v_shared := jsonb_set(v_shared, '{programPresentation}', v_program, true);
  v_world := jsonb_set(v_world, '{shared}', v_shared, true);

  v_event := jsonb_build_object(
    'op', v_op,
    'applied', true,
    'cue', v_cue,
    'programRevision', v_program->>'programRevision',
    'authoritative', true
  );
  RETURN jsonb_build_object('worldState', v_world, 'eventPayload', v_event);
END;
$function$

CREATE OR REPLACE FUNCTION public.sagatree_resolve_damage_command(p_payload jsonb, p_is_gm boolean, p_world jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_in JSONB := public.sagatree_strip_forged_encounter_keys(p_payload);
  v_world JSONB := COALESCE(p_world, '{}'::jsonb);
  v_shared JSONB := COALESCE(v_world->'shared', '{}'::jsonb);
  v_encounter JSONB;
  v_participants JSONB;
  v_pid TEXT;
  v_mode TEXT;
  v_amount INT;
  v_i INT;
  v_len INT;
  v_participant JSONB;
  v_hp INT;
  v_max INT;
  v_prev INT;
  v_conditions JSONB;
  v_event JSONB;
  v_ref TEXT;
  v_diff TEXT;
  v_life JSONB;
  v_prev_life JSONB;
  v_wounds INT;
  v_start INT;
  v_status TEXT;
  v_dying INT;
  v_life_conds JSONB;
BEGIN
  IF NOT p_is_gm THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  IF jsonb_typeof(v_shared) IS DISTINCT FROM 'object' THEN
    v_shared := '{}'::jsonb;
  END IF;
  v_encounter := COALESCE(v_shared->'encounter', '{}'::jsonb);
  IF COALESCE(v_encounter->>'status', '') IS DISTINCT FROM 'active' THEN
    RAISE EXCEPTION 'Kein aktiver Encounter' USING ERRCODE = '22023';
  END IF;

  v_pid := NULLIF(BTRIM(COALESCE(v_in->>'participantId', '')), '');
  v_mode := COALESCE(NULLIF(BTRIM(COALESCE(v_in->>'mode', '')), ''), 'damage');
  IF v_mode NOT IN ('damage', 'heal') THEN
    RAISE EXCEPTION 'Ungültiger Schaden-Modus' USING ERRCODE = '22023';
  END IF;
  IF v_pid IS NULL OR NOT ((v_in->>'amount') ~ '^[0-9]+$') THEN
    RAISE EXCEPTION 'Schaden/Heilung benötigt participantId und Betrag' USING ERRCODE = '22023';
  END IF;
  v_amount := (v_in->>'amount')::int;
  IF v_amount < 0 OR v_amount > 9999 THEN
    RAISE EXCEPTION 'Ungültiger Betrag' USING ERRCODE = '22023';
  END IF;

  v_participants := COALESCE(v_encounter->'participants', '[]'::jsonb);
  v_len := jsonb_array_length(v_participants);
  v_participant := NULL;
  FOR v_i IN 0 .. v_len - 1 LOOP
    IF (v_participants->v_i->>'id') = v_pid THEN
      v_participant := v_participants->v_i;
      EXIT;
    END IF;
  END LOOP;
  IF v_participant IS NULL THEN
    RAISE EXCEPTION 'Teilnehmer nicht gefunden' USING ERRCODE = 'P0002';
  END IF;

  v_max := GREATEST(1, COALESCE((v_participant->>'hpMax')::int, 1));
  v_prev := COALESCE((v_participant->>'hpCurrent')::int, v_max);
  IF v_mode = 'damage' THEN
    v_hp := GREATEST(0, v_prev - v_amount);
  ELSE
    v_hp := LEAST(v_max, v_prev + v_amount);
  END IF;
  v_participant := jsonb_set(v_participant, '{hpCurrent}', to_jsonb(v_hp), true);

  v_conditions := COALESCE(v_participant->'conditions', '[]'::jsonb);
  -- Legacy #300: bewusstlos on drop to 0 / clear on heal (kept for tests + UI)
  IF v_mode = 'damage' AND v_prev > 0 AND v_hp = 0 THEN
    IF NOT (v_conditions @> '"bewusstlos"'::jsonb) THEN
      v_conditions := v_conditions || '"bewusstlos"'::jsonb;
    END IF;
  ELSIF v_mode = 'heal' AND v_prev = 0 AND v_hp > 0 THEN
    SELECT COALESCE(jsonb_agg(to_jsonb(elem)), '[]'::jsonb)
      INTO v_conditions
      FROM jsonb_array_elements_text(v_conditions) AS elem
     WHERE elem NOT IN ('bewusstlos', 'unconscious');
  END IF;

  -- Life track (#373) for PCs (refId = character uuid)
  v_ref := NULLIF(BTRIM(COALESCE(v_participant->>'refId', '')), '');
  v_diff := COALESCE(NULLIF(BTRIM(COALESCE(v_shared->>'lifeDifficulty', '')), ''), 'Standard');
  IF v_diff NOT IN ('Heroisch', 'Standard', 'Hart') THEN
    v_diff := 'Standard';
  END IF;
  IF v_participant->>'kind' = 'pc' AND v_ref IS NOT NULL THEN
    v_prev_life := COALESCE(v_shared->'lifeByCharacter'->v_ref, '{}'::jsonb);
    IF v_mode = 'damage' AND v_prev > 0 AND v_hp = 0 THEN
      IF COALESCE(v_prev_life->>'status', '') = 'dead' THEN
        v_life := v_prev_life;
      ELSE
        v_wounds := GREATEST(0, COALESCE((v_prev_life->>'wounds')::int, 0));
        v_start := public.sagatree_life_start_level(v_diff, COALESCE((v_in->>'explicitDeadly')::boolean, false));
        IF v_diff = 'Hart' THEN
          IF v_wounds < 3 THEN
            v_wounds := v_wounds + 1;
          ELSE
            v_start := LEAST(3, v_start + 1);
          END IF;
        END IF;
        IF v_start >= 3 THEN
          v_status := 'dead';
          v_dying := 3;
        ELSIF v_start = 0 THEN
          v_status := 'stable';
          v_dying := 0;
        ELSE
          v_status := 'downed';
          v_dying := v_start;
        END IF;
        v_life := jsonb_build_object(
          'schemaVersion', 1,
          'status', v_status,
          'dyingLevel', v_dying,
          'wounds', v_wounds,
          'difficulty', v_diff,
          'updatedAt', NOW()
        );
      END IF;
      v_life_conds := public.sagatree_life_conditions(v_life->>'status', (v_life->>'dyingLevel')::int);
      v_conditions := public.sagatree_merge_life_into_conditions(v_conditions, v_life_conds);
      v_shared := jsonb_set(v_shared, ARRAY['lifeByCharacter', v_ref], v_life, true);
    ELSIF v_mode = 'heal' AND v_prev = 0 AND v_hp > 0 THEN
      IF COALESCE(v_prev_life->>'status', '') IS DISTINCT FROM 'dead' THEN
        v_life := jsonb_build_object(
          'schemaVersion', 1,
          'status', 'alive',
          'dyingLevel', 0,
          'wounds', GREATEST(0, COALESCE((v_prev_life->>'wounds')::int, 0)),
          'difficulty', COALESCE(v_prev_life->>'difficulty', v_diff),
          'updatedAt', NOW()
        );
        v_life_conds := public.sagatree_life_conditions('alive', 0);
        v_conditions := public.sagatree_merge_life_into_conditions(v_conditions, v_life_conds);
        v_shared := jsonb_set(v_shared, ARRAY['lifeByCharacter', v_ref], v_life, true);
      END IF;
    END IF;
  END IF;

  v_participant := jsonb_set(v_participant, '{conditions}', v_conditions, true);

  FOR v_i IN 0 .. v_len - 1 LOOP
    IF (v_participants->v_i->>'id') = v_pid THEN
      v_participants := jsonb_set(v_participants, ARRAY[v_i::text], v_participant, true);
      EXIT;
    END IF;
  END LOOP;

  v_encounter := jsonb_set(v_encounter, '{participants}', v_participants, true);
  v_shared := jsonb_set(v_shared, '{encounter}', v_encounter, true);
  IF v_participant->>'kind' = 'pc' AND v_ref IS NOT NULL THEN
    v_shared := jsonb_set(
      v_shared,
      ARRAY['hpByCharacter', v_ref],
      to_jsonb(v_hp),
      true
    );
    v_shared := jsonb_set(
      v_shared,
      ARRAY['conditionsByCharacter', v_ref],
      v_conditions,
      true
    );
  END IF;
  v_world := jsonb_set(v_world, '{shared}', v_shared, true);

  PERFORM public.sagatree_sync_npc_instance_from_participant(v_participant);

  v_event := jsonb_build_object(
    'mode', v_mode,
    'participantId', v_pid,
    'amount', v_amount,
    'hpCurrent', v_hp,
    'hpMax', v_max,
    'authoritative', true,
    'lifeStatus', COALESCE(v_shared->'lifeByCharacter'->v_ref->>'status', NULL)
  );
  RETURN jsonb_build_object('worldState', v_world, 'eventPayload', v_event);
END;
$function$

CREATE OR REPLACE FUNCTION public.sagatree_resolve_life_command(p_payload jsonb, p_is_gm boolean, p_world jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_in JSONB := COALESCE(p_payload, '{}'::jsonb);
  v_world JSONB := COALESCE(p_world, '{}'::jsonb);
  v_shared JSONB := COALESCE(v_world->'shared', '{}'::jsonb);
  v_op TEXT;
  v_char TEXT;
  v_pid TEXT;
  v_grade TEXT;
  v_diff TEXT;
  v_confirm BOOLEAN;
  v_note TEXT;
  v_prev JSONB;
  v_life JSONB;
  v_status TEXT;
  v_dying INT;
  v_wounds INT;
  v_life_conds JSONB;
  v_encounter JSONB;
  v_participants JSONB;
  v_participant JSONB;
  v_conditions JSONB;
  v_i INT;
  v_len INT;
  v_event JSONB;
BEGIN
  IF NOT p_is_gm THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  IF jsonb_typeof(v_shared) IS DISTINCT FROM 'object' THEN
    v_shared := '{}'::jsonb;
  END IF;

  v_op := NULLIF(BTRIM(COALESCE(v_in->>'op', '')), '');
  v_char := NULLIF(BTRIM(COALESCE(v_in->>'characterId', '')), '');
  v_pid := NULLIF(BTRIM(COALESCE(v_in->>'participantId', '')), '');
  v_grade := NULLIF(BTRIM(COALESCE(v_in->>'grade', '')), '');
  v_diff := NULLIF(BTRIM(COALESCE(v_in->>'difficulty', '')), '');
  v_confirm := COALESCE((v_in->>'confirmDead')::boolean, false);
  v_note := left(NULLIF(BTRIM(COALESCE(v_in->>'note', '')), ''), 200);

  IF v_op IS NULL THEN
    RAISE EXCEPTION 'Life-op erforderlich' USING ERRCODE = '22023';
  END IF;

  IF v_op = 'set_difficulty' THEN
    IF v_diff IS NULL OR v_diff NOT IN ('Heroisch', 'Standard', 'Hart') THEN
      RAISE EXCEPTION 'Ungültige difficulty' USING ERRCODE = '22023';
    END IF;
    v_shared := jsonb_set(v_shared, '{lifeDifficulty}', to_jsonb(v_diff), true);
    v_world := jsonb_set(v_world, '{shared}', v_shared, true);
    RETURN jsonb_build_object(
      'worldState', v_world,
      'eventPayload', jsonb_build_object('op', 'set_difficulty', 'difficulty', v_diff, 'authoritative', true)
    );
  END IF;

  IF v_char IS NULL THEN
    RAISE EXCEPTION 'characterId erforderlich' USING ERRCODE = '22023';
  END IF;

  v_prev := COALESCE(v_shared->'lifeByCharacter'->v_char, '{}'::jsonb);
  v_status := COALESCE(v_prev->>'status', 'alive');
  v_dying := GREATEST(0, COALESCE((v_prev->>'dyingLevel')::int, 0));
  v_wounds := GREATEST(0, COALESCE((v_prev->>'wounds')::int, 0));
  v_diff := COALESCE(
    NULLIF(BTRIM(COALESCE(v_prev->>'difficulty', '')), ''),
    NULLIF(BTRIM(COALESCE(v_shared->>'lifeDifficulty', '')), ''),
    'Standard'
  );

  IF v_op = 'death_save' THEN
    IF v_status = 'dead' THEN
      RAISE EXCEPTION 'Charakter ist bereits tot' USING ERRCODE = '22023';
    END IF;
    IF v_status IS DISTINCT FROM 'downed' THEN
      RAISE EXCEPTION 'Todeswurf nur bei Sterbend' USING ERRCODE = '22023';
    END IF;
    IF v_grade IS NULL OR v_grade NOT IN ('crit_success', 'success', 'failure', 'crit_failure') THEN
      RAISE EXCEPTION 'grade erforderlich' USING ERRCODE = '22023';
    END IF;
    IF v_grade = 'crit_success' THEN
      v_status := 'stable';
      v_dying := 0;
    ELSIF v_grade = 'success' THEN
      v_dying := GREATEST(0, v_dying - 1);
      v_status := CASE WHEN v_dying = 0 THEN 'stable' ELSE 'downed' END;
    ELSIF v_grade = 'failure' THEN
      v_dying := v_dying + 1;
      v_status := 'downed';
    ELSE
      v_dying := v_dying + 2;
      v_status := 'downed';
    END IF;
    IF v_dying >= 3 THEN
      v_status := 'dead';
      v_dying := 3;
    END IF;
  ELSIF v_op = 'stabilize' THEN
    IF v_status = 'dead' THEN
      RAISE EXCEPTION 'Tote können nicht stabilisiert werden' USING ERRCODE = '22023';
    END IF;
    IF v_status NOT IN ('downed', 'stable') THEN
      RAISE EXCEPTION 'Nur Downed/Stabil können stabilisiert werden' USING ERRCODE = '22023';
    END IF;
    v_status := 'stable';
    v_dying := 0;
  ELSIF v_op = 'mark_dead' THEN
    IF NOT v_confirm THEN
      RAISE EXCEPTION 'confirmDead erforderlich' USING ERRCODE = '22023';
    END IF;
    v_status := 'dead';
    v_dying := 3;
  ELSIF v_op = 'clear_alive' THEN
    v_status := 'alive';
    v_dying := 0;
    v_wounds := 0;
  ELSIF v_op = 'enter_downed' THEN
    v_dying := public.sagatree_life_start_level(v_diff, COALESCE((v_in->>'explicitDeadly')::boolean, false));
    IF v_diff = 'Hart' THEN
      IF v_wounds < 3 THEN
        v_wounds := v_wounds + 1;
      ELSE
        v_dying := LEAST(3, v_dying + 1);
      END IF;
    END IF;
    IF v_dying >= 3 THEN
      v_status := 'dead';
      v_dying := 3;
    ELSIF v_dying = 0 THEN
      v_status := 'stable';
    ELSE
      v_status := 'downed';
    END IF;
  ELSE
    RAISE EXCEPTION 'Unbekannte Life-Operation' USING ERRCODE = '22023';
  END IF;

  v_life := jsonb_build_object(
    'schemaVersion', 1,
    'status', v_status,
    'dyingLevel', v_dying,
    'wounds', v_wounds,
    'difficulty', v_diff,
    'updatedAt', NOW()
  );
  v_life_conds := public.sagatree_life_conditions(v_status, v_dying);
  v_shared := jsonb_set(v_shared, ARRAY['lifeByCharacter', v_char], v_life, true);

  -- Mirror into active encounter participant + conditionsByCharacter when possible
  v_encounter := COALESCE(v_shared->'encounter', '{}'::jsonb);
  IF COALESCE(v_encounter->>'status', '') = 'active' THEN
    v_participants := COALESCE(v_encounter->'participants', '[]'::jsonb);
    v_len := jsonb_array_length(v_participants);
    FOR v_i IN 0 .. v_len - 1 LOOP
      v_participant := v_participants->v_i;
      IF (v_participant->>'kind') = 'pc'
         AND (
           (v_participant->>'refId') = v_char
           OR (v_pid IS NOT NULL AND (v_participant->>'id') = v_pid)
         ) THEN
        v_conditions := public.sagatree_merge_life_into_conditions(
          COALESCE(v_participant->'conditions', '[]'::jsonb),
          v_life_conds
        );
        v_participant := jsonb_set(v_participant, '{conditions}', v_conditions, true);
        v_participants := jsonb_set(v_participants, ARRAY[v_i::text], v_participant, true);
        v_shared := jsonb_set(
          v_shared,
          ARRAY['conditionsByCharacter', v_char],
          v_conditions,
          true
        );
        EXIT;
      END IF;
    END LOOP;
    v_encounter := jsonb_set(v_encounter, '{participants}', v_participants, true);
    v_shared := jsonb_set(v_shared, '{encounter}', v_encounter, true);
  ELSE
    v_shared := jsonb_set(
      v_shared,
      ARRAY['conditionsByCharacter', v_char],
      v_life_conds,
      true
    );
  END IF;

  v_world := jsonb_set(v_world, '{shared}', v_shared, true);
  v_event := jsonb_build_object(
    'op', v_op,
    'characterId', v_char,
    'participantId', v_pid,
    'grade', v_grade,
    'status', v_status,
    'dyingLevel', v_dying,
    'wounds', v_wounds,
    'difficulty', v_diff,
    'note', v_note,
    'authoritative', true
  );
  RETURN jsonb_build_object('worldState', v_world, 'eventPayload', v_event);
END;
$function$

CREATE OR REPLACE FUNCTION public.sagatree_resolve_probe_grade(p_total integer, p_target integer, p_natural integer)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
DECLARE
  v_margin INT := p_total - p_target;
  v_grade TEXT;
BEGIN
  IF v_margin >= 10 THEN
    v_grade := 'crit-success';
  ELSIF v_margin >= 0 THEN
    v_grade := 'success';
  ELSIF v_margin <= -10 THEN
    v_grade := 'crit-failure';
  ELSE
    v_grade := 'failure';
  END IF;

  IF p_natural = 20 AND v_grade IS DISTINCT FROM 'crit-success' THEN
    IF v_grade = 'crit-failure' THEN v_grade := 'failure';
    ELSIF v_grade = 'failure' THEN v_grade := 'success';
    ELSE v_grade := 'crit-success';
    END IF;
  ELSIF p_natural = 1 AND v_grade IS DISTINCT FROM 'crit-failure' THEN
    IF v_grade = 'crit-success' THEN v_grade := 'success';
    ELSIF v_grade = 'success' THEN v_grade := 'failure';
    ELSE v_grade := 'crit-failure';
    END IF;
  END IF;

  RETURN v_grade;
END;
$function$

CREATE OR REPLACE FUNCTION public.sagatree_resolve_session_check(p_session_id uuid, p_actor uuid, p_payload jsonb, p_is_gm boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_in JSONB := public.sagatree_strip_forged_roll_keys(p_payload);
  v_skill TEXT := NULLIF(BTRIM(COALESCE(v_in->>'skill', '')), '');
  v_mode TEXT := COALESCE(NULLIF(BTRIM(COALESCE(v_in->>'mode', '')), ''), 'normal');
  v_use_drive BOOLEAN := COALESCE((v_in->>'useDrive')::boolean, false);
  v_attr_key TEXT;
  v_character public.characters;
  v_char_id UUID;
  v_public_id TEXT;
  v_attr INT;
  v_skill_rank INT;
  v_eb INT;
  v_flat INT;
  v_world JSONB;
  v_shared JSONB;
  v_target INT;
  v_drive INT;
  v_n1 INT;
  v_n2 INT;
  v_natural INT;
  v_total INT;
  v_grade TEXT;
  v_n1b INT;
  v_n2b INT;
  v_natural_b INT;
  v_total_b INT;
  v_grade_b_text TEXT;
  v_drive_spent INT := 0;
  v_naturals JSONB;
  v_result JSONB;
BEGIN
  IF v_skill IS NULL OR public.sagatree_skill_attribute_key(v_skill) IS NULL THEN
    RAISE EXCEPTION 'Invalid skill for session check' USING ERRCODE = '22023';
  END IF;
  IF v_mode NOT IN ('normal', 'advantage', 'disadvantage') THEN
    RAISE EXCEPTION 'Invalid check mode' USING ERRCODE = '22023';
  END IF;

  v_attr_key := public.sagatree_skill_attribute_key(v_skill);
  v_public_id := NULLIF(BTRIM(COALESCE(v_in->>'characterPublicId', '')), '');

  IF v_in ? 'characterId' AND NULLIF(BTRIM(COALESCE(v_in->>'characterId', '')), '') IS NOT NULL THEN
    BEGIN
      v_char_id := (v_in->>'characterId')::uuid;
    EXCEPTION WHEN others THEN
      RAISE EXCEPTION 'Invalid characterId' USING ERRCODE = '22023';
    END;
    SELECT * INTO v_character FROM public.characters WHERE id = v_char_id;
  ELSIF v_public_id IS NOT NULL THEN
    SELECT * INTO v_character FROM public.characters WHERE public_id = v_public_id;
  ELSE
    RAISE EXCEPTION 'characterPublicId or characterId required' USING ERRCODE = '22023';
  END IF;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Character not found for session check' USING ERRCODE = 'P0002';
  END IF;

  -- Membership already checked by caller; character must belong to actor or actor is GM.
  IF NOT p_is_gm AND v_character.user_id IS DISTINCT FROM p_actor THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  v_attr := COALESCE((v_character.attributes ->> v_attr_key)::int, 0);
  IF v_attr < 1 OR v_attr > 5 THEN
    RAISE EXCEPTION 'Character attribute out of range for check' USING ERRCODE = '22023';
  END IF;

  v_skill_rank := COALESCE((v_character.skills ->> v_skill)::int, 0);
  IF v_skill_rank < 0 OR v_skill_rank > 5 THEN
    RAISE EXCEPTION 'Character skill rank out of range' USING ERRCODE = '22023';
  END IF;

  v_eb := public.sagatree_applied_experience_bonus(v_skill_rank, COALESCE(v_character.level, 1));
  v_flat := v_attr + v_skill_rank + v_eb;

  SELECT world_state INTO v_world FROM public.sessions WHERE id = p_session_id;
  v_world := COALESCE(v_world, '{}'::jsonb);
  v_shared := COALESCE(v_world->'shared', '{}'::jsonb);
  IF jsonb_typeof(v_shared) IS DISTINCT FROM 'object' THEN
    v_shared := '{}'::jsonb;
  END IF;

  -- Target: GM may set via payload; else shared.checkTarget / resistance; default 15.
  IF p_is_gm AND v_in ? 'target' AND (v_in->>'target') ~ '^-?[0-9]+$' THEN
    v_target := (v_in->>'target')::int;
    v_shared := jsonb_set(v_shared, '{checkTarget}', to_jsonb(v_target), true);
  ELSIF p_is_gm AND v_in ? 'resistance' AND (v_in->>'resistance') ~ '^-?[0-9]+$' THEN
    v_target := (v_in->>'resistance')::int;
    v_shared := jsonb_set(v_shared, '{checkTarget}', to_jsonb(v_target), true);
  ELSIF v_shared ? 'checkTarget' AND (v_shared->>'checkTarget') ~ '^-?[0-9]+$' THEN
    v_target := (v_shared->>'checkTarget')::int;
  ELSE
    v_target := 15;
  END IF;

  -- Drive pool: prefer shared overlay keyed by character id, else profile.
  IF v_shared ? 'driveByCharacter'
     AND jsonb_typeof(v_shared->'driveByCharacter') = 'object'
     AND (v_shared->'driveByCharacter') ? v_character.id::text
     AND ((v_shared->'driveByCharacter'->>v_character.id::text) ~ '^[0-9]+$') THEN
    v_drive := (v_shared->'driveByCharacter'->>v_character.id::text)::int;
  ELSE
    v_drive := COALESCE((v_character.sagatree_profile->>'drive')::int, 3);
  END IF;
  IF v_drive < 0 THEN v_drive := 0; END IF;
  IF v_drive > 5 THEN v_drive := 5; END IF;

  v_n1 := public.sagatree_roll_d20();
  IF v_mode = 'normal' THEN
    v_natural := v_n1;
    v_naturals := jsonb_build_array(v_n1);
  ELSE
    v_n2 := public.sagatree_roll_d20();
    IF v_mode = 'advantage' THEN
      v_natural := GREATEST(v_n1, v_n2);
    ELSE
      v_natural := LEAST(v_n1, v_n2);
    END IF;
    v_naturals := jsonb_build_array(v_n1, v_n2);
  END IF;

  v_total := v_natural + v_flat;
  v_grade := public.sagatree_resolve_probe_grade(v_total, v_target, v_natural);

  IF v_use_drive THEN
    IF v_drive < 1 THEN
      RAISE EXCEPTION 'No Drive available for reroll' USING ERRCODE = '22023';
    END IF;
    v_n1b := public.sagatree_roll_d20();
    IF v_mode = 'normal' THEN
      v_natural_b := v_n1b;
    ELSE
      v_n2b := public.sagatree_roll_d20();
      IF v_mode = 'advantage' THEN
        v_natural_b := GREATEST(v_n1b, v_n2b);
      ELSE
        v_natural_b := LEAST(v_n1b, v_n2b);
      END IF;
    END IF;
    v_total_b := v_natural_b + v_flat;
    v_grade_b_text := public.sagatree_resolve_probe_grade(v_total_b, v_target, v_natural_b);
    -- Keep better (§2.10): higher grade rank, then higher total.
    IF public.sagatree_grade_rank(v_grade_b_text) > public.sagatree_grade_rank(v_grade)
       OR (
         public.sagatree_grade_rank(v_grade_b_text) = public.sagatree_grade_rank(v_grade)
         AND v_total_b > v_total
       ) THEN
      v_natural := v_natural_b;
      v_total := v_total_b;
      v_grade := v_grade_b_text;
      IF v_mode = 'normal' THEN
        v_naturals := jsonb_build_array(v_n1b);
      ELSE
        v_naturals := jsonb_build_array(v_n1b, v_n2b);
      END IF;
    END IF;
    v_drive_spent := 1;
    v_drive := v_drive - 1;
  END IF;

  v_shared := jsonb_set(
    COALESCE(v_shared, '{}'::jsonb),
    ARRAY['driveByCharacter', v_character.id::text],
    to_jsonb(v_drive),
    true
  );

  v_result := jsonb_build_object(
    'intent', 'standard-check',
    'skill', v_skill,
    'mode', v_mode,
    'useDrive', v_use_drive,
    'characterPublicId', COALESCE(v_character.public_id, v_public_id),
    'characterId', v_character.id,
    'target', v_target,
    'natural', v_natural,
    'naturals', v_naturals,
    'flatBonus', v_flat,
    'attributeValue', v_attr,
    'skillRank', v_skill_rank,
    'experienceBonus', v_eb,
    'total', v_total,
    'grade', v_grade,
    'driveSpent', v_drive_spent,
    'driveRemaining', v_drive,
    'actorUserId', p_actor,
    'authoritative', true
  );

  v_shared := jsonb_set(v_shared, '{lastRoll}', v_result, true);
  v_world := jsonb_set(COALESCE(v_world, '{}'::jsonb), '{shared}', v_shared, true);

  RETURN jsonb_build_object(
    'eventPayload', v_result,
    'worldState', v_world
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.sagatree_sync_npc_instance_from_participant(p_participant jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_id UUID;
  v_runtime JSONB;
BEGIN
  IF COALESCE(p_participant->>'kind', '') IS DISTINCT FROM 'npc' THEN
    RETURN;
  END IF;
  BEGIN
    v_id := (p_participant->>'refId')::uuid;
  EXCEPTION WHEN others THEN
    RETURN;
  END;

  SELECT runtime INTO v_runtime FROM public.npc_creature_instances WHERE id = v_id;
  IF NOT FOUND THEN
    RETURN;
  END IF;

  v_runtime := COALESCE(v_runtime, '{}'::jsonb);
  v_runtime := jsonb_set(v_runtime, '{currentHp}', to_jsonb(COALESCE((p_participant->>'hpCurrent')::int, 0)), true);
  IF p_participant ? 'conditions' AND jsonb_typeof(p_participant->'conditions') = 'array' THEN
    v_runtime := jsonb_set(v_runtime, '{conditions}', p_participant->'conditions', true);
  END IF;

  UPDATE public.npc_creature_instances
     SET runtime = v_runtime, updated_at = NOW()
   WHERE id = v_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.sagatree_upsert_session_recap(p_session_id uuid)
 RETURNS session_recaps
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_session public.sessions%ROWTYPE;
  v_adv JSONB;
  v_shared JSONB;
  v_lines JSONB;
  v_row public.session_recaps%ROWTYPE;
BEGIN
  SELECT * INTO v_session FROM public.sessions WHERE id = p_session_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Session not found' USING ERRCODE = 'P0002';
  END IF;

  v_shared := COALESCE(v_session.world_state->'shared', '{}'::jsonb);
  v_adv := COALESCE(v_shared->'adventure', '{}'::jsonb);
  IF jsonb_typeof(v_adv) IS DISTINCT FROM 'object' THEN
    v_adv := '{}'::jsonb;
  END IF;

  -- Persist latest adventure onto project for continuity (complete path).
  IF jsonb_typeof(v_adv) = 'object' AND COALESCE((v_adv->>'schemaVersion')::int, 0) = 1 THEN
    UPDATE public.projects
       SET adventure_runtime = v_adv,
           updated_at = NOW()
     WHERE id = v_session.project_id;
  END IF;

  -- Full adventure in snapshot; get_session_recap projects highlights by role.
  v_lines := public.sagatree_build_recap_highlight_lines(v_adv, true);

  INSERT INTO public.session_recaps AS sr (
    session_id, summary_text, highlight_lines, snapshot, created_at, updated_at
  ) VALUES (
    p_session_id,
    NULL,
    v_lines,
    COALESCE(v_adv, '{}'::jsonb),
    NOW(),
    NOW()
  )
  ON CONFLICT (session_id) DO UPDATE
    SET highlight_lines = EXCLUDED.highlight_lines,
        snapshot = EXCLUDED.snapshot,
        updated_at = NOW(),
        -- keep manual summary_text if already set
        summary_text = sr.summary_text
  RETURNING * INTO v_row;

  RETURN v_row;
END;
$function$

CREATE OR REPLACE FUNCTION public.save_saga_definition_draft(p_saga_id uuid, p_payload jsonb, p_expected_revision integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user UUID := auth.uid();
  v_def public.saga_definitions%ROWTYPE;
  v_ver public.saga_definition_versions%ROWTYPE;
  v_title TEXT;
  v_blurb TEXT;
BEGIN
  IF v_user IS NULL THEN
    RAISE EXCEPTION 'not authenticated' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO v_def FROM public.saga_definitions WHERE id = p_saga_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Saga-Definition nicht gefunden' USING ERRCODE = 'P0002';
  END IF;
  IF v_def.origin = 'native' THEN
    RAISE EXCEPTION 'Native Sagas sind unveränderlich' USING ERRCODE = '42501';
  END IF;
  IF v_def.owner_user_id IS DISTINCT FROM v_user THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  IF v_def.draft_revision IS DISTINCT FROM COALESCE(p_expected_revision, -1) THEN
    RAISE EXCEPTION 'Revisionskonflikt — bitte neu laden' USING ERRCODE = '40001';
  END IF;

  v_ver := public.sagatree_ensure_saga_draft(v_def.id);

  v_title := NULLIF(BTRIM(COALESCE(p_payload->>'title', '')), '');
  IF v_title IS NULL THEN
    RAISE EXCEPTION 'Titel darf nicht leer sein' USING ERRCODE = '22023';
  END IF;
  v_blurb := COALESCE(p_payload->>'blurb', p_payload->>'synopsis', '');

  UPDATE public.saga_definition_versions
     SET payload = COALESCE(p_payload, '{}'::jsonb)
   WHERE id = v_ver.id;

  UPDATE public.saga_definitions
     SET title = v_title,
         synopsis = v_blurb,
         draft_revision = draft_revision + 1,
         updated_at = NOW()
   WHERE id = v_def.id
  RETURNING * INTO v_def;

  SELECT * INTO v_ver FROM public.saga_definition_versions WHERE id = v_ver.id;

  RETURN jsonb_build_object(
    'sagaId', v_def.id,
    'versionId', v_ver.id,
    'revision', v_def.draft_revision,
    'payload', v_ver.payload
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.save_session_recap_summary(p_session_id uuid, p_summary_text text, p_status text DEFAULT 'draft'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user UUID := auth.uid();
  v_session public.sessions%ROWTYPE;
  v_status TEXT := lower(btrim(COALESCE(p_status, 'draft')));
BEGIN
  IF v_user IS NULL THEN
    RAISE EXCEPTION 'not authenticated' USING ERRCODE = '42501';
  END IF;
  IF v_status NOT IN ('draft', 'approved', 'none') THEN
    RAISE EXCEPTION 'invalid summary status' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_session FROM public.sessions WHERE id = p_session_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Session not found' USING ERRCODE = 'P0002';
  END IF;
  IF NOT public.is_project_gm(v_session.project_id, v_user) THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  INSERT INTO public.session_recaps (session_id, summary_text, summary_status, highlight_lines, snapshot)
  VALUES (
    p_session_id,
    NULLIF(BTRIM(COALESCE(p_summary_text, '')), ''),
    v_status,
    '[]'::jsonb,
    '{}'::jsonb
  )
  ON CONFLICT (session_id) DO UPDATE
    SET summary_text = EXCLUDED.summary_text,
        summary_status = EXCLUDED.summary_status,
        updated_at = NOW();

  RETURN public.get_session_recap(p_session_id);
END;
$function$

CREATE OR REPLACE FUNCTION public.save_world_map(p_world_profile_id uuid, p_expected_revision bigint, p_map_data jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user UUID := auth.uid();
  v_row public.world_maps%ROWTYPE;
  v_size INT;
  v_next BIGINT;
BEGIN
  IF v_user IS NULL THEN
    RAISE EXCEPTION 'not authenticated' USING ERRCODE = '42501';
  END IF;
  IF p_world_profile_id IS NULL THEN
    RAISE EXCEPTION 'world_profile_id required' USING ERRCODE = '22023';
  END IF;
  IF NOT public.current_user_can_edit_world_profile(p_world_profile_id) THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  IF p_map_data IS NULL OR jsonb_typeof(p_map_data) <> 'object' THEN
    RAISE EXCEPTION 'map_data ungültig' USING ERRCODE = '22023';
  END IF;

  v_size := COALESCE((p_map_data->>'size')::INT, 24);
  IF v_size < 1 OR v_size > 60 THEN
    RAISE EXCEPTION 'Kartengröße muss zwischen 1 und 60 liegen' USING ERRCODE = '22023';
  END IF;

  -- Reject Base64 image payloads in pins
  IF EXISTS (
    SELECT 1
    FROM jsonb_array_elements(COALESCE(p_map_data->'pins', '[]'::jsonb)) AS elem
    WHERE COALESCE(elem->>'imagePath', '') LIKE 'data:%'
       OR length(COALESCE(elem->>'imagePath', '')) > 512
  ) THEN
    RAISE EXCEPTION 'Pin-Bilder müssen Storage-Pfade sein (kein Base64)' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_row FROM public.world_maps WHERE world_profile_id = p_world_profile_id FOR UPDATE;
  IF FOUND THEN
    IF COALESCE(p_expected_revision, -1) >= 0 AND v_row.revision <> p_expected_revision THEN
      RAISE EXCEPTION 'revision conflict' USING ERRCODE = '40001';
    END IF;
    v_next := v_row.revision + 1;
    UPDATE public.world_maps
    SET map_data = p_map_data,
        revision = v_next,
        updated_at = now()
    WHERE world_profile_id = p_world_profile_id
    RETURNING * INTO v_row;
  ELSE
    v_next := 1;
    INSERT INTO public.world_maps (world_profile_id, revision, map_data, updated_at)
    VALUES (p_world_profile_id, v_next, p_map_data, now())
    RETURNING * INTO v_row;
  END IF;

  RETURN jsonb_build_object(
    'worldProfileId', v_row.world_profile_id,
    'revision', v_row.revision,
    'mapData', v_row.map_data,
    'updatedAt', v_row.updated_at
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.seed_dornhain_catalog_bindings(p_project_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_inserted INT := 0;
  v_world UUID;
  r RECORD;
  v_map JSONB;
BEGIN
  IF p_project_id IS NULL THEN
    RETURN 0;
  END IF;

  SELECT world_profile_id INTO v_world FROM public.projects WHERE id = p_project_id;

  FOR r IN
    SELECT * FROM (VALUES
      ('pregen.warrior', 'Brenna Sturmfaust', 'party'),
      ('pregen.scout', 'Kael Schattenpfad', 'party'),
      ('pregen.mystic', 'Liora Mondschein', 'party'),
      ('pregen.diplomat', 'Oskar Federkiel', 'party')
    ) AS t(asset_id, label, reveal)
  LOOP
    INSERT INTO public.saga_asset_bindings (
      project_id, asset_kind, asset_id, reveal, label, metadata
    ) VALUES (
      p_project_id, 'character', r.asset_id, r.reveal, r.label,
      jsonb_build_object('origin', 'native', 'immutable', true)
    )
    ON CONFLICT (project_id, asset_kind, asset_id) DO UPDATE SET
      label = EXCLUDED.label,
      reveal = EXCLUDED.reveal,
      metadata = public.saga_asset_bindings.metadata || EXCLUDED.metadata,
      updated_at = NOW();
    v_inserted := v_inserted + 1;
  END LOOP;

  FOR r IN
    SELECT * FROM (VALUES
      ('loc.tavern', 'Taverne Zum Flüstern', 'party'),
      ('loc.market', 'Marktplatz Dornhain', 'party'),
      ('loc.woods', 'Schattenwald', 'party'),
      ('loc.crypt', 'Krypta unter dem Hügel', 'gm_only'),
      ('loc.bandit-camp', 'Banditenlager (falsche Spur)', 'gm_only')
    ) AS t(asset_id, label, reveal)
  LOOP
    INSERT INTO public.saga_asset_bindings (
      project_id, asset_kind, asset_id, reveal, label, metadata
    ) VALUES (
      p_project_id, 'location', r.asset_id, r.reveal, r.label,
      jsonb_build_object('origin', 'native', 'immutable', true)
    )
    ON CONFLICT (project_id, asset_kind, asset_id) DO UPDATE SET
      label = EXCLUDED.label,
      reveal = EXCLUDED.reveal,
      metadata = public.saga_asset_bindings.metadata || EXCLUDED.metadata,
      updated_at = NOW();
    v_inserted := v_inserted + 1;
  END LOOP;

  FOR r IN
    SELECT * FROM (VALUES
      ('npc.innkeeper', 'Wirtin Maren', 'party'),
      ('npc.guard', 'Stadtwache Bren', 'party'),
      ('npc.bandit-a', 'Bandit Rusk', 'party'),
      ('npc.bandit-b', 'Banditin Syla', 'gm_only'),
      ('npc.hidden-villager', 'Dorfbewohner (Relikt)', 'gm_only')
    ) AS t(asset_id, label, reveal)
  LOOP
    INSERT INTO public.saga_asset_bindings (
      project_id, asset_kind, asset_id, reveal, label, metadata
    ) VALUES (
      p_project_id, 'npc', r.asset_id, r.reveal, r.label,
      jsonb_build_object('origin', 'native', 'immutable', true)
    )
    ON CONFLICT (project_id, asset_kind, asset_id) DO UPDATE SET
      label = EXCLUDED.label,
      reveal = EXCLUDED.reveal,
      metadata = public.saga_asset_bindings.metadata || EXCLUDED.metadata,
      updated_at = NOW();
    v_inserted := v_inserted + 1;
  END LOOP;

  FOR r IN
    SELECT * FROM (VALUES
      ('quest.missing-villagers', 'Die Verschwundenen', 'party'),
      ('quest.false-bandits', 'Falsche Spur: Banditen', 'party'),
      ('quest.relic-seal', 'Das Relikt versiegeln', 'gm_only')
    ) AS t(asset_id, label, reveal)
  LOOP
    INSERT INTO public.saga_asset_bindings (
      project_id, asset_kind, asset_id, reveal, label, metadata
    ) VALUES (
      p_project_id, 'quest', r.asset_id, r.reveal, r.label,
      jsonb_build_object('origin', 'native', 'immutable', true)
    )
    ON CONFLICT (project_id, asset_kind, asset_id) DO UPDATE SET
      label = EXCLUDED.label,
      reveal = EXCLUDED.reveal,
      metadata = public.saga_asset_bindings.metadata || EXCLUDED.metadata,
      updated_at = NOW();
    v_inserted := v_inserted + 1;
  END LOOP;

  FOR r IN
    SELECT * FROM (VALUES
      ('builtin.fantasy.healing-potion', 'Heiltrank', 'party'),
      ('builtin.fantasy.longsword', 'Langschwert', 'party'),
      ('builtin.fantasy.gemstone', 'Siegelstein', 'party'),
      ('item.relic-shard', 'Reliktsplitter', 'gm_only')
    ) AS t(asset_id, label, reveal)
  LOOP
    INSERT INTO public.saga_asset_bindings (
      project_id, asset_kind, asset_id, reveal, label, metadata
    ) VALUES (
      p_project_id, 'item', r.asset_id, r.reveal, r.label,
      jsonb_build_object('origin', 'native', 'immutable', true)
    )
    ON CONFLICT (project_id, asset_kind, asset_id) DO UPDATE SET
      label = EXCLUDED.label,
      reveal = EXCLUDED.reveal,
      metadata = public.saga_asset_bindings.metadata || EXCLUDED.metadata,
      updated_at = NOW();
    v_inserted := v_inserted + 1;
  END LOOP;

  FOR r IN
    SELECT * FROM (VALUES
      ('lore.market-rumors', 'Gerüchte am Markt', 'party', 'Am Markt flüstert man von Verschwundenen.'),
      ('lore.whisper-legend', 'Legende vom Flüstern', 'party', 'Unter dem Hügel soll etwas flüstern.'),
      ('lore.relic-truth', 'Wahrheit des Relikts', 'gm_only', '')
    ) AS t(asset_id, label, reveal, summary)
  LOOP
    INSERT INTO public.saga_asset_bindings (
      project_id, asset_kind, asset_id, reveal, label, metadata
    ) VALUES (
      p_project_id, 'lore', r.asset_id, r.reveal, r.label,
      jsonb_build_object(
        'origin', 'native',
        'immutable', true,
        'summary', r.summary
      )
    )
    ON CONFLICT (project_id, asset_kind, asset_id) DO UPDATE SET
      label = EXCLUDED.label,
      reveal = EXCLUDED.reveal,
      metadata = public.saga_asset_bindings.metadata || EXCLUDED.metadata,
      updated_at = NOW();
    v_inserted := v_inserted + 1;
  END LOOP;

  INSERT INTO public.saga_asset_bindings (
    project_id, asset_kind, asset_id, reveal, label, metadata
  ) VALUES (
    p_project_id, 'map', 'map.dornhain.overview', 'party', 'Dornhain Übersichtskarte',
    jsonb_build_object('origin', 'native', 'immutable', true, 'atlas', 'unified')
  )
  ON CONFLICT (project_id, asset_kind, asset_id) DO UPDATE SET
    label = EXCLUDED.label,
    reveal = EXCLUDED.reveal,
    metadata = public.saga_asset_bindings.metadata || EXCLUDED.metadata,
    updated_at = NOW();
  v_inserted := v_inserted + 1;

  IF v_world IS NOT NULL THEN
    v_map := public.build_dornhain_starter_map_data(24);
    INSERT INTO public.world_maps (world_profile_id, revision, map_data, updated_at)
    VALUES (v_world, 1, v_map, NOW())
    ON CONFLICT (world_profile_id) DO UPDATE SET
      map_data = CASE
        WHEN COALESCE(public.world_maps.map_data->'tiles', '{}'::jsonb) = '{}'::jsonb
          OR COALESCE(jsonb_typeof(public.world_maps.map_data->'pins'->0->'title'), 'null') = 'null'
          THEN EXCLUDED.map_data
        ELSE public.world_maps.map_data
      END,
      updated_at = NOW();

    PERFORM public.seed_dornhain_unified_atlas(v_world);
  END IF;

  RETURN v_inserted;
END;
$function$

CREATE OR REPLACE FUNCTION public.seed_dornhain_gm_presence_for_all_owners()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  r RECORD;
  v_total INT := 0;
  v_n INT;
BEGIN
  FOR r IN
    SELECT DISTINCT p.id AS project_id, p.gm_user_id AS user_id
    FROM public.projects p
    JOIN public.saga_definitions d ON d.id = p.saga_id
    WHERE p.gm_user_id IS NOT NULL
      AND d.slug = 'dornhain.whisper'
  LOOP
    v_n := public.seed_dornhain_gm_presence_character(r.project_id, r.user_id);
    v_total := v_total + COALESCE(v_n, 0);
  END LOOP;
  RETURN v_total;
END;
$function$

