CREATE OR REPLACE FUNCTION public.set_saga_member_bundle(p_project_id uuid, p_member_id uuid, p_bundle_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_uid UUID := auth.uid();
  v_member RECORD;
  v_governance_left INT;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'not authenticated';
  END IF;
  IF NOT public.has_saga_permission(p_project_id, 'saga.members.set_bundle')
     AND NOT public.is_project_gm(p_project_id, v_uid) THEN
    RAISE EXCEPTION 'missing saga.members.set_bundle';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.saga_permission_bundles WHERE id = p_bundle_id) THEN
    RAISE EXCEPTION 'unknown bundle %', p_bundle_id;
  END IF;

  SELECT * INTO v_member
  FROM public.project_members
  WHERE id = p_member_id AND project_id = p_project_id AND status = 'active';
  IF NOT FOUND THEN
    RAISE EXCEPTION 'member not found';
  END IF;

  -- Invariant: cannot demote last holder of set_bundle away from GM bundle.
  IF p_bundle_id <> 'bundle.saga.gm' THEN
    SELECT COUNT(DISTINCT g.user_id) INTO v_governance_left
    FROM public.project_member_saga_grants g
    JOIN public.project_members m ON m.id = g.member_id
    WHERE g.project_id = p_project_id
      AND g.permission_key = 'saga.members.set_bundle'
      AND m.status = 'active'
      AND g.member_id <> p_member_id;
    IF COALESCE(v_governance_left, 0) < 1
       AND EXISTS (
         SELECT 1 FROM public.project_member_saga_grants
         WHERE member_id = p_member_id AND permission_key = 'saga.members.set_bundle'
       ) THEN
      RAISE EXCEPTION 'cannot revoke last saga.members.set_bundle grant';
    END IF;
  END IF;

  DELETE FROM public.project_member_saga_grants WHERE member_id = p_member_id;

  INSERT INTO public.project_member_saga_grants (
    project_id, member_id, user_id, permission_key, source_bundle_id, granted_by
  )
  SELECT
    p_project_id,
    p_member_id,
    v_member.user_id,
    bk.permission_key,
    p_bundle_id,
    v_uid
  FROM public.saga_permission_bundle_keys bk
  WHERE bk.bundle_id = p_bundle_id;

  INSERT INTO public.project_member_saga_bundles (
    member_id, project_id, user_id, bundle_id, assigned_by, updated_at
  ) VALUES (
    p_member_id, p_project_id, v_member.user_id, p_bundle_id, v_uid, NOW()
  )
  ON CONFLICT (member_id) DO UPDATE SET
    bundle_id = EXCLUDED.bundle_id,
    assigned_by = EXCLUDED.assigned_by,
    updated_at = NOW();

  RETURN jsonb_build_object(
    'memberId', p_member_id,
    'bundleId', p_bundle_id,
    'grantCount', (
      SELECT COUNT(*)::INT FROM public.project_member_saga_grants WHERE member_id = p_member_id
    )
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.set_session_player_presence(p_session_id uuid, p_is_online boolean, p_expected_revision bigint DEFAULT NULL::bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  actor UUID := auth.uid();
  v_session public.sessions;
  v_revision BIGINT;
BEGIN
  IF actor IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE = '42501';
  END IF;
  IF NOT public.is_session_participant(p_session_id, actor) THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO v_session FROM public.sessions WHERE id = p_session_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Session not found' USING ERRCODE = 'P0002';
  END IF;

  IF p_expected_revision IS NOT NULL
     AND v_session.runtime_revision IS DISTINCT FROM p_expected_revision THEN
    RAISE EXCEPTION 'stale revision: expected %, actual %',
      p_expected_revision, v_session.runtime_revision
      USING ERRCODE = '40001';
  END IF;

  UPDATE public.session_players
     SET is_online = COALESCE(p_is_online, false)
   WHERE session_id = p_session_id AND user_id = actor;

  v_revision := v_session.runtime_revision + 1;
  UPDATE public.sessions
     SET runtime_revision = v_revision, updated_at = NOW()
   WHERE id = p_session_id;

  PERFORM public.append_session_event(
    p_session_id,
    'presence',
    actor,
    jsonb_build_object('isOnline', COALESCE(p_is_online, false)),
    v_revision,
    NULL
  );

  RETURN public.get_session_runtime_snapshot(p_session_id);
END;
$function$

CREATE OR REPLACE FUNCTION public.set_session_status(p_session_id uuid, p_status text)
 RETURNS sessions
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  actor UUID := auth.uid();
  v_session public.sessions;
  v_from TEXT;
  v_revision BIGINT;
BEGIN
  IF actor IS NULL THEN RAISE EXCEPTION 'Authentication required' USING ERRCODE = '42501'; END IF;
  IF p_status NOT IN ('waiting', 'active', 'paused', 'completed') THEN
    RAISE EXCEPTION 'Invalid session status' USING ERRCODE = '22023';
  END IF;
  SELECT * INTO v_session FROM public.sessions WHERE id = p_session_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Session not found' USING ERRCODE = 'P0002'; END IF;
  IF NOT public.is_project_gm(v_session.project_id, actor) THEN RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501'; END IF;
  v_from := v_session.status;
  IF v_from = 'scheduled' THEN v_from := 'waiting'; END IF;
  IF v_from = 'completed' THEN RAISE EXCEPTION 'Completed sessions cannot change status' USING ERRCODE = '22023'; END IF;
  IF NOT (
    (v_from = 'waiting' AND p_status IN ('active', 'completed'))
    OR (v_from = 'active' AND p_status IN ('paused', 'completed'))
    OR (v_from = 'paused' AND p_status IN ('active', 'completed'))
  ) THEN
    RAISE EXCEPTION 'Illegal status transition from % to %', v_from, p_status USING ERRCODE = '22023';
  END IF;

  v_revision := COALESCE(v_session.runtime_revision, 0) + 1;

  UPDATE public.sessions SET
    status = p_status,
    runtime_revision = v_revision,
    updated_at = NOW(),
    started_at = CASE WHEN p_status = 'active' AND started_at IS NULL THEN NOW() ELSE started_at END,
    ended_at = CASE WHEN p_status = 'completed' THEN NOW() ELSE ended_at END
  WHERE id = p_session_id
  RETURNING * INTO v_session;

  PERFORM public.append_session_event(
    p_session_id,
    'status',
    actor,
    jsonb_build_object('from', v_from, 'to', p_status),
    v_revision,
    NULL
  );

  IF p_status = 'completed' THEN
    PERFORM public.sagatree_upsert_session_recap(p_session_id);
  END IF;

  RETURN v_session;
END;
$function$

